        ["src/games/universal/Movement/HookPart.lua"] = [[
--!strict
export type Runtime = {
    framework: any,
    host: any,
    services: any,
}

type HookKind = "Ladder" | "Obstacle" | "Wall"

type HookSighting = {
    kind: HookKind,
    part: BasePart,
    normal: Vector3,
    direction: Vector3,
    distance: number,
    name: string,
    isWedge: boolean,
}

local Module = {
    Name = "HookPart",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCard: any = nil

local SCAN_DIRECTIONS: number = 16
local SCAN_HEIGHTS: {number} = {-1.8, -0.6, 0.5, 1.5}

function Module.init(context: Runtime): any
    local framework: any = context.framework
    local host: any = context.host
    local services: any = context.services
    local movementInput: any = services.movementInput
    local getCharacterParts: any = host.getCharacterParts
    local UserInputService: any = host.UserInputService or (game :: any):GetService("UserInputService")
    local RunService: RunService = host.RunService or (game :: any):GetService("RunService")
    local currentWorkspace: Workspace = host.workspace or workspace

    local lastHookJumpAt: number = -math.huge
    local lastScanAt: number = -math.huge
    local lastClimbAt: number = -math.huge
    local currentSighting: HookSighting? = nil
    local highlight: Highlight? = nil

    local settings = {
        ladderBoost = true,
        ladderJumpLength = 70,
        ladderJumpHeight = 65,
        obstacleBoost = true,
        obstaclePower = 90,
        selfFling = false,
        flingMultiplier = 1100,
        wallhopAssist = true,
        wallhopPower = 38,
        airborneWallhopOnly = true,
        requireStuckIntent = true,
        allowDownwardBoost = true,
        sliderAssist = true,
        directionMode = "Camera",
        detectionRange = 2.4,
        checkAllParts = true,
        highlightObject = true,
    }

    local function destroyHighlight(): ()
        if highlight then
            pcall(function()
                highlight:Destroy()
            end)
            highlight = nil
        end
    end

    local function isLadderStructure(part: Instance): boolean
        if part:IsA("TrussPart") then
            return true
        end
        local current: Instance? = part
        for _ = 1, 3 do
            if not current then break end
            local lowerName: string = string.lower(current.Name)
            if string.find(lowerName, "ladder") ~= nil
                or string.find(lowerName, "truss") ~= nil
                or string.find(lowerName, "escalera") ~= nil
                or string.find(lowerName, "climb") ~= nil then
                return true
            end
            current = current.Parent
        end
        return false
    end

    local function isSmallDecoration(part: BasePart): boolean

        local sz: Vector3 = part.Size
        if (sz.X <= 0.9 and sz.Z <= 0.9) or (sz.X <= 0.5 and sz.Y <= 0.5) then
            return true
        end
        return false
    end

    local function scanSurroundings(
        character: Model,
        humanoid: Humanoid,
        root: BasePart
    ): HookSighting?
        local now: number = os.clock()
        local state: Enum.HumanoidStateType = humanoid:GetState()
        local isCurrentlyClimbing: boolean = state == Enum.HumanoidStateType.Climbing
        if isCurrentlyClimbing then
            lastClimbAt = now
        end

        local isGrounded: boolean = humanoid.FloorMaterial ~= Enum.Material.Air
        local moveDir: Vector3 = humanoid.MoveDirection
        local horizVelocity: number = Vector3.new(root.AssemblyLinearVelocity.X, 0, root.AssemblyLinearVelocity.Z).Magnitude

        local filter: {Instance} = {character}
        local ghost: Instance? = currentWorkspace:FindFirstChild("Wurst_Ghost")
        if ghost then
            table.insert(filter, ghost)
        end

        local parameters: RaycastParams = RaycastParams.new()
        parameters.FilterType = Enum.RaycastFilterType.Exclude
        parameters.FilterDescendantsInstances = filter
        parameters.IgnoreWater = true
        parameters.RespectCanCollide = true

        local climbingGrace: boolean = (now - lastClimbAt) <= 0.22
        if isCurrentlyClimbing or climbingGrace then

            local forwardRay: RaycastResult? = currentWorkspace:Raycast(
                root.Position,
                root.CFrame.LookVector * 3.0,
                parameters
            )
            local ladderPart: BasePart = (forwardRay and forwardRay.Instance:IsA("BasePart") and forwardRay.Instance) or root
            local ladderNorm: Vector3 = (forwardRay and forwardRay.Normal) or -root.CFrame.LookVector

            return {
                kind = "Ladder",
                part = ladderPart,
                normal = ladderNorm,
                direction = root.CFrame.LookVector,
                distance = forwardRay and forwardRay.Distance or 1.2,
                name = ladderPart.Name ~= root.Name and ladderPart.Name or "Ladder",
                isWedge = false,
            }
        end

        local bestSighting: HookSighting? = nil
        local bestDistance: number = settings.detectionRange + 1

        local overlapLadder: OverlapParams = OverlapParams.new()
        overlapLadder.FilterType = Enum.RaycastFilterType.Exclude
        overlapLadder.FilterDescendantsInstances = filter
        overlapLadder.MaxParts = 6

        local frontBoxCF: CFrame = root.CFrame * CFrame.new(0, 0, -1.3)
        local nearbyTrusses: {BasePart} = {}
        pcall(function()
            nearbyTrusses = currentWorkspace:GetPartBoundsInBox(frontBoxCF, Vector3.new(2.4, 4.0, 2.0), overlapLadder)
        end)
        for _, part: BasePart in ipairs(nearbyTrusses) do
            if part.CanCollide and isLadderStructure(part) then
                return {
                    kind = "Ladder",
                    part = part,
                    normal = -root.CFrame.LookVector,
                    direction = root.CFrame.LookVector,
                    distance = (part.Position - root.Position).Magnitude,
                    name = part.Name,
                    isWedge = false,
                }
            end
        end

        for i: number = 0, SCAN_DIRECTIONS - 1 do
            local angle: number = (i / SCAN_DIRECTIONS) * math.pi * 2
            local direction: Vector3 = Vector3.new(math.sin(angle), 0, math.cos(angle))

            for _, heightOffset: number in ipairs(SCAN_HEIGHTS) do
                local origin: Vector3 = root.Position + Vector3.new(0, heightOffset, 0)
                local hit: RaycastResult? = currentWorkspace:Raycast(
                    origin,
                    direction * settings.detectionRange,
                    parameters
                )

                if hit and hit.Instance and hit.Instance:IsA("BasePart") then
                    local part: BasePart = hit.Instance
                    if part.CanCollide then
                        local dist: number = hit.Distance
                        local norm: Vector3 = hit.Normal
                        local isLadder: boolean = isLadderStructure(part)

                        if isLadder then
                            return {
                                kind = "Ladder",
                                part = part,
                                normal = norm,
                                direction = direction,
                                distance = dist,
                                name = part.Name,
                                isWedge = false,
                            }
                        end

                        local partNameLower: string = string.lower(part.Name)
                        local isKnownObstacle: boolean = string.find(partNameLower, "tank") ~= nil
                            or string.find(partNameLower, "crate") ~= nil
                            or string.find(partNameLower, "box") ~= nil
                            or string.find(partNameLower, "prop") ~= nil
                            or string.find(partNameLower, "vehicle") ~= nil
                            or string.find(partNameLower, "barrel") ~= nil
                            or string.find(partNameLower, "wheel") ~= nil
                            or math.abs(norm.Y) > 0.40

                        local isSmall: boolean = isSmallDecoration(part)

                        if isGrounded then
                            if isSmall and not isKnownObstacle then

                                continue
                            end

                            if settings.requireStuckIntent then

                                local pushingIntoPart: boolean = moveDir.Magnitude > 0.1 and moveDir:Dot(direction) > 0.30
                                local isStuckMoving: boolean = moveDir.Magnitude > 0.1 and horizVelocity < 3.0
                                if not (pushingIntoPart or isStuckMoving or isKnownObstacle) then
                                    continue
                                end
                            end
                        else

                            if settings.airborneWallhopOnly and not isKnownObstacle and isSmall then
                                continue
                            end
                        end

                        local kind: HookKind = isKnownObstacle and "Obstacle" or "Wall"

                        if dist < bestDistance then
                            bestDistance = dist
                            bestSighting = {
                                kind = kind,
                                part = part,
                                normal = norm,
                                direction = direction,
                                distance = dist,
                                name = part.Name,
                                isWedge = isKnownObstacle,
                            }
                        end
                    end
                end
            end
        end

        if settings.checkAllParts and (not bestSighting or bestDistance > 1.8) then
            local overlap: OverlapParams = OverlapParams.new()
            overlap.FilterType = Enum.RaycastFilterType.Exclude
            overlap.FilterDescendantsInstances = filter
            overlap.MaxParts = 6
            overlap.RespectCanCollide = true

            local nearbyParts: {BasePart} = {}
            pcall(function()
                nearbyParts = currentWorkspace:GetPartBoundsInBox(root.CFrame, Vector3.new(3.2, 4.5, 3.2), overlap)
            end)

            for _, part: BasePart in ipairs(nearbyParts) do
                if part.CanCollide and part ~= root then
                    local isLadder: boolean = isLadderStructure(part)
                    if isLadder then
                        return {
                            kind = "Ladder",
                            part = part,
                            normal = -root.CFrame.LookVector,
                            direction = root.CFrame.LookVector,
                            distance = 1.0,
                            name = part.Name,
                            isWedge = false,
                        }
                    end

                    if not isSmallDecoration(part) then
                        local offset: Vector3 = part.Position - root.Position
                        local dist: number = offset.Magnitude
                        local normVec: Vector3 = offset.Magnitude > 0.01 and -offset.Unit or -root.CFrame.LookVector

                        if dist < bestDistance then
                            bestDistance = dist
                            bestSighting = {
                                kind = "Obstacle",
                                part = part,
                                normal = normVec,
                                direction = offset.Magnitude > 0.01 and offset.Unit or root.CFrame.LookVector,
                                distance = dist,
                                name = part.Name,
                                isWedge = true,
                            }
                        end
                    end
                end
            end
        end

        return bestSighting
    end

    local function getLaunchDirection(root: BasePart, humanoid: Humanoid, sighting: HookSighting): Vector3
        local cam: Camera? = currentWorkspace.CurrentCamera
        local mode: string = settings.directionMode

        if sighting.kind == "Ladder" then

            if cam then
                local camLook: Vector3 = cam.CFrame.LookVector
                return Vector3.new(camLook.X, math.max(camLook.Y, 0.4), camLook.Z).Unit
            end
            local outward: Vector3 = sighting.normal
            if outward.Magnitude > 0.1 then
                return Vector3.new(outward.X, 0.5, outward.Z).Unit
            end
            return Vector3.new(0, 1, 0)
        end

        if mode == "Camera" and cam then
            return cam.CFrame.LookVector
        elseif mode == "Movement" then
            local moveDir: Vector3 = humanoid.MoveDirection
            if moveDir.Magnitude > 0.1 then
                return moveDir.Unit
            end
            if cam then
                return cam.CFrame.LookVector
            end
            return root.CFrame.LookVector
        elseif mode == "Normal" then
            local norm: Vector3 = sighting.normal
            if norm.Magnitude > 0.1 then
                return norm.Unit
            end
        elseif mode == "Upward" then
            return Vector3.new(0, 1, 0)
        end

        if cam then
            return cam.CFrame.LookVector
        end
        return root.CFrame.LookVector
    end

    local function applySustainedImpulse(root: BasePart, targetVel: Vector3, durationSeconds: number): ()

        local startTime: number = os.clock()
        local connection: RBXScriptConnection? = nil
        connection = RunService.Heartbeat:Connect(function(): ()
            if not root or not root.Parent or (os.clock() - startTime) >= durationSeconds then
                if connection then
                    connection:Disconnect()
                    connection = nil
                end
                return
            end
            root.AssemblyLinearVelocity = targetVel
        end)
    end

    local function executeHookJump(): ()
        local now: number = os.clock()
        if now - lastHookJumpAt < 0.20 then
            return
        end

        local _, humanoid: Humanoid? = getCharacterParts()
        if not character or not humanoid or not root or humanoid.Health <= 0 then
            return
        end

        local sighting: HookSighting? = currentSighting or scanSurroundings(character, humanoid, root)
        if not sighting then
            return
        end

        local isGrounded: boolean = humanoid.FloorMaterial ~= Enum.Material.Air

        if isGrounded and sighting.kind == "Wall" and settings.airborneWallhopOnly then
            return
        end

        lastHookJumpAt = now
        local launchDir: Vector3 = getLaunchDirection(root, humanoid, sighting)
        local flatLaunchDir: Vector3 = Vector3.new(launchDir.X, 0, launchDir.Z)
        if flatLaunchDir.Magnitude > 0.01 then
            flatLaunchDir = flatLaunchDir.Unit
        else
            flatLaunchDir = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z).Unit
        end

        local currentVel: Vector3 = root.AssemblyLinearVelocity

        if sighting.kind == "Ladder" then
            if not settings.ladderBoost then
                return
            end

            humanoid:ChangeState(Enum.HumanoidStateType.Jumping)

            local horizSpeed: number = settings.ladderJumpLength
            local vertSpeed: number = settings.ladderJumpHeight
            local ladderVel: Vector3 = Vector3.new(
                flatLaunchDir.X * horizSpeed,
                vertSpeed,
                flatLaunchDir.Z * horizSpeed
            )

            root.AssemblyLinearVelocity = ladderVel

            applySustainedImpulse(root, ladderVel, 0.08)

            if activeCard then
                activeCard:SetStatus("Ladder Leap!")
            end

        elseif sighting.kind == "Obstacle" then
            if not settings.obstacleBoost then
                return
            end

            humanoid:ChangeState(Enum.HumanoidStateType.Jumping)

            local outwardNorm: Vector3 = sighting.normal
            local isSlopeOrStairs: boolean = outwardNorm.Y > 0.15 and outwardNorm.Y < 0.92

            local vertVel: number
            if settings.allowDownwardBoost and launchDir.Y < -0.10 then

                vertVel = launchDir.Y * (settings.obstaclePower * 1.1)
            elseif launchDir.Y > 0.10 then
                vertVel = math.max(launchDir.Y * settings.obstaclePower, settings.obstaclePower * 0.60)
            else
                vertVel = math.max(currentVel.Y + 16, settings.obstaclePower * 0.55)
            end

            if settings.selfFling then
                local flingSpeed: number = settings.flingMultiplier
                local vertFling: number = (settings.allowDownwardBoost and launchDir.Y < -0.10)
                    and (launchDir.Y * flingSpeed * 0.55)
                    or (flingSpeed * 0.40)

                local flingVec: Vector3 = Vector3.new(
                    flatLaunchDir.X * flingSpeed,
                    vertFling,
                    flatLaunchDir.Z * flingSpeed
                )
                root.AssemblyLinearVelocity = flingVec
                applySustainedImpulse(root, flingVec, 0.09)
                if activeCard then
                    activeCard:SetStatus("SELF FLING!")
                end
            else
                local boostPower: number = settings.obstaclePower
                local combinedDir: Vector3
                if isSlopeOrStairs and settings.sliderAssist then

                    combinedDir = flatLaunchDir
                else
                    combinedDir = (flatLaunchDir * 0.75 + Vector3.new(outwardNorm.X, 0, outwardNorm.Z) * 0.25)
                end

                if combinedDir.Magnitude > 0.01 then
                    combinedDir = combinedDir.Unit
                else
                    combinedDir = flatLaunchDir
                end

                local obstacleVel: Vector3 = Vector3.new(
                    combinedDir.X * boostPower,
                    vertVel,
                    combinedDir.Z * boostPower
                )
                root.AssemblyLinearVelocity = obstacleVel
                applySustainedImpulse(root, obstacleVel, 0.06)
                if activeCard then
                    activeCard:SetStatus(vertVel < -5 and "Slope Slide!" or "Obstacle Boost!")
                end
            end

        elseif sighting.kind == "Wall" then
            if not settings.wallhopAssist then
                return
            end

            humanoid:ChangeState(Enum.HumanoidStateType.Jumping)

            local kick: number = settings.wallhopPower
            local norm: Vector3 = sighting.normal
            local kickHoriz: Vector3 = Vector3.new(norm.X, 0, norm.Z)
            if kickHoriz.Magnitude > 0.01 then
                kickHoriz = kickHoriz.Unit
            else
                kickHoriz = -flatLaunchDir
            end

            local wallVel: Vector3 = Vector3.new(
                currentVel.X * 0.25 + kickHoriz.X * kick + flatLaunchDir.X * (kick * 0.45),
                math.max(currentVel.Y, 54),
                currentVel.Z * 0.25 + kickHoriz.Z * kick + flatLaunchDir.Z * (kick * 0.45)
            )
            root.AssemblyLinearVelocity = wallVel
            if activeCard then
                activeCard:SetStatus("Wallhop!")
            end
        end
    end

    local card: any
    card = framework.Categories.Movement:CreateModule({
        Name = "HookPart",
        Category = "Movement",
        ConfigKey = "Universal.HookPart",
        Order = 32,
        Tooltip = "Amplify jumps off ladders, get unstuck from obstacles (like MM2 tanks & crates) with custom boost or self-fling, and wallhop off any part.",
        Function = function(enabled: boolean): ()
            destroyHighlight()
            currentSighting = nil
            lastHookJumpAt = -math.huge
            lastClimbAt = -math.huge

            if not enabled then
                card:SetStatus(nil)
                return
            end
            card:SetStatus("Active")

            if movementInput and type(movementInput.onJumpRequest) == "function" then
                card:Clean(movementInput.onJumpRequest(function(): ()
                    executeHookJump()
                end))
            end

            if UserInputService and UserInputService.JumpRequest then
                card:Clean(UserInputService.JumpRequest:Connect(function(): ()
                    executeHookJump()
                end))
            end

            local _, humanoid: Humanoid? = getCharacterParts()
            if humanoid then
                card:Clean(humanoid.StateChanged:Connect(function(oldState: Enum.HumanoidStateType, newState: Enum.HumanoidStateType): ()
                    if newState == Enum.HumanoidStateType.Climbing or oldState == Enum.HumanoidStateType.Climbing then
                        lastClimbAt = os.clock()
                    end
                end))
            end

            card:Loop(function(): ()
                local now: number = os.clock()
                if now - lastScanAt < 0.05 then
                    return
                end
                lastScanAt = now

                local curChar: Model?, curHum: Humanoid?, curRoot: BasePart? = getCharacterParts()
                if not curChar or not curHum or not curRoot or curHum.Health <= 0 then
                    destroyHighlight()
                    currentSighting = nil
                    return
                end

                if curHum:GetState() == Enum.HumanoidStateType.Climbing then
                    lastClimbAt = now
                end

                local sighting: HookSighting? = scanSurroundings(curChar, curHum, curRoot)
                currentSighting = sighting

                if not sighting then
                    destroyHighlight()
                    card:SetStatus("Ready")
                    return
                end

                local statusText: string = sighting.kind .. ": " .. sighting.name
                if settings.selfFling and sighting.kind == "Obstacle" then
                    statusText = "Fling Ready: " .. sighting.name
                end
                card:SetStatus(statusText)

                if not settings.highlightObject or sighting.part == curRoot then
                    destroyHighlight()
                    return
                end

                if not highlight or not highlight.Parent then
                    highlight = Instance.new("Highlight")
                    highlight.Name = "Wurst_HookPart_Highlight"
                    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                    highlight.Parent = currentWorkspace
                end

                if sighting.kind == "Ladder" then
                    highlight.FillColor = Color3.fromRGB(80, 220, 255)
                    highlight.OutlineColor = Color3.fromRGB(150, 240, 255)
                elseif sighting.kind == "Obstacle" then
                    if settings.selfFling then
                        highlight.FillColor = Color3.fromRGB(255, 60, 60)
                        highlight.OutlineColor = Color3.fromRGB(255, 120, 120)
                    else
                        highlight.FillColor = Color3.fromRGB(255, 180, 50)
                        highlight.OutlineColor = Color3.fromRGB(255, 220, 100)
                    end
                else
                    highlight.FillColor = Color3.fromRGB(60, 255, 140)
                    highlight.OutlineColor = Color3.fromRGB(120, 255, 180)
                end
                highlight.FillTransparency = 0.70
                highlight.OutlineTransparency = 0.15
                highlight.Adornee = sighting.part
            end)
        end,
    })

    card:CreateToggle({
        Name = "Ladder Boost",
        Default = settings.ladderBoost,
        Function = function(value: boolean): ()
            settings.ladderBoost = value
        end,
        Tooltip = "Makes jumps off ladders and trusses significantly longer and higher.",
    })

    card:CreateSlider({
        Name = "Ladder Jump Length",
        Min = 20,
        Max = 200,
        Default = settings.ladderJumpLength,
        Step = 5,
        Function = function(value: number): ()
            settings.ladderJumpLength = value
        end,
        Tooltip = "Forward velocity impulse when jumping off a ladder.",
    })

    card:CreateSlider({
        Name = "Ladder Jump Height",
        Min = 20,
        Max = 150,
        Default = settings.ladderJumpHeight,
        Step = 5,
        Function = function(value: number): ()
            settings.ladderJumpHeight = value
        end,
        Tooltip = "Upward vertical impulse when leaping from a ladder.",
    })

    card:CreateToggle({
        Name = "Obstacle Boost",
        Default = settings.obstacleBoost,
        Function = function(value: boolean): ()
            settings.obstacleBoost = value
        end,
        Tooltip = "Gives a strong impulse when wedged or jumping against obstacles, tanks, and crates.",
    })

    card:CreateSlider({
        Name = "Obstacle Power",
        Min = 25,
        Max = 300,
        Default = settings.obstaclePower,
        Step = 5,
        Function = function(value: number): ()
            settings.obstaclePower = value
        end,
        Tooltip = "Power of the jump boost when hooked on an obstacle or tank.",
    })

    card:CreateToggle({
        Name = "Self Fling",
        Default = settings.selfFling,
        Function = function(value: boolean): ()
            settings.selfFling = value
        end,
        Tooltip = "Turns obstacle jump into a massive self-fling to launch yourself across the map.",
    })

    card:CreateSlider({
        Name = "Fling Multiplier",
        Min = 200,
        Max = 3500,
        Default = settings.flingMultiplier,
        Step = 50,
        Function = function(value: number): ()
            settings.flingMultiplier = value
        end,
        Tooltip = "Velocity magnitude applied when triggering a self-fling.",
    })

    card:CreateToggle({
        Name = "Wallhop Assist",
        Default = settings.wallhopAssist,
        Function = function(value: boolean): ()
            settings.wallhopAssist = value
        end,
        Tooltip = "Allows resetting jump and leaping off any wall surface.",
    })

    card:CreateSlider({
        Name = "Wallhop Power",
        Min = 15,
        Max = 100,
        Default = settings.wallhopPower,
        Step = 5,
        Function = function(value: number): ()
            settings.wallhopPower = value
        end,
        Tooltip = "Impulse applied when performing a wallhop.",
    })

    card:CreateToggle({
        Name = "Airborne Wallhop Only",
        Default = settings.airborneWallhopOnly,
        Function = function(value: boolean): ()
            settings.airborneWallhopOnly = value
        end,
        Tooltip = "Only triggers wallhop when already in mid-air, preventing strange jumps on the ground next to fences.",
    })

    card:CreateToggle({
        Name = "Allow Downward Boost",
        Default = settings.allowDownwardBoost,
        Function = function(value: boolean): ()
            settings.allowDownwardBoost = value
        end,
        Tooltip = "Looking downward launches or slides you down stairs, slopes, and ramps instead of forcing an upward jump.",
    })

    card:CreateToggle({
        Name = "Slider Assist",
        Default = settings.sliderAssist,
        Function = function(value: boolean): ()
            settings.sliderAssist = value
        end,
        Tooltip = "Follows the slope of stairs and ramps smoothly in your camera/movement direction.",
    })

    card:CreateToggle({
        Name = "Require Stuck Intent",
        Default = settings.requireStuckIntent,
        Function = function(value: boolean): ()
            settings.requireStuckIntent = value
        end,
        Tooltip = "Only activates obstacle boost when moving towards the object or wedged against it.",
    })

    card:CreateDropdown({
        Name = "Direction Mode",
        List = {"Camera", "Movement", "Normal", "Upward"},
        Index = 1,
        Function = function(value: string): ()
            settings.directionMode = value
        end,
        Tooltip = "Determines the direction in which boost / fling impulse is applied.",
    })

    card:CreateSlider({
        Name = "Detection Range",
        Min = 1.5,
        Max = 5.0,
        Default = settings.detectionRange,
        Step = 0.1,
        Function = function(value: number): ()
            settings.detectionRange = value
        end,
        Tooltip = "Distance around the player to scan for hooked parts, ladders, and walls.",
    })

    card:CreateToggle({
        Name = "Check All Parts",
        Default = settings.checkAllParts,
        Function = function(value: boolean): ()
            settings.checkAllParts = value
        end,
        Tooltip = "Deep spatial collision check (raycasts + box overlap) for tanks, crates, and geometry.",
    })

    card:CreateToggle({
        Name = "Highlight Object",
        Default = settings.highlightObject,
        Function = function(value: boolean): ()
            settings.highlightObject = value
        end,
        Tooltip = "Outlines the part, ladder, or obstacle you are hooked to.",
    })

    activeCard = card
    Module.Initialized = true
    return card
end

function Module.destroy(): ()
    if activeCard and activeCard.Enabled then
        pcall(activeCard.Toggle, false)
    end
    activeCard = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Movement/Jump.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "Jump",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local framework: any = context.framework
    local movementInput: any = context.services and context.services.movementInput
    local UserInputService: any = host.UserInputService or game:GetService("UserInputService")
    local LocalPlayer: Player = host.LocalPlayer or game:GetService("Players").LocalPlayer

    local originalJumpPower = setmetatable({}, {__mode = "k"}) :: {[Humanoid]: {jumpPower: number, useJumpPower: boolean}}
    local lastInfiniteJumpAt: number = -math.huge

    local function characterParts(): (Model?, Humanoid?, BasePart?)
        local character: Model? = LocalPlayer.Character
        if not character then
            return nil, nil, nil
        end
        local humanoid: Humanoid? = character:FindFirstChildOfClass("Humanoid")
        local root: BasePart? = character:FindFirstChild("HumanoidRootPart") :: BasePart?
        return character, humanoid, root
    end

    local function restoreJumpPower(): ()
        for humanoid: Humanoid, original in pairs(originalJumpPower) do
            if humanoid and humanoid.Parent then
                humanoid.JumpPower = original.jumpPower
                humanoid.UseJumpPower = original.useJumpPower
            end
        end
        originalJumpPower = setmetatable({}, {__mode = "k"}) :: any
    end

    local function performHighJump(velocityOverride: number?): ()
        local _, humanoid: Humanoid?, root: BasePart? = characterParts()
        if not humanoid or not root or humanoid.Health <= 0 then
            return
        end
        local velocityVal: number = velocityOverride or 72
        local current: Vector3 = (root :: BasePart).AssemblyLinearVelocity
        ;(root :: BasePart).AssemblyLinearVelocity = Vector3.new(
            current.X,
            velocityVal,
            current.Z
        )
        if humanoid.FloorMaterial ~= Enum.Material.Air then
            humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
        end
    end

    local function performInfiniteJump(mode: string, strength: number, interval: number, stackCeiling: number): ()
        local _, humanoid: Humanoid?, root: BasePart? = characterParts()
        if not humanoid or not root or humanoid.Health <= 0 then
            return
        end

        local spacing: number = interval
        if UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
            spacing = math.max(spacing, 0.25)
        end

        local now: number = os.clock()
        if now - lastInfiniteJumpAt < spacing then
            return
        end
        lastInfiniteJumpAt = now

        local velocity: Vector3 = (root :: BasePart).AssemblyLinearVelocity
        local vertical: number
        if mode == "Stack" then
            vertical = math.min(velocity.Y + strength, stackCeiling)
        elseif mode == "Impulse" then
            humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
            ;(root :: BasePart):ApplyImpulse(
                Vector3.new(0, strength - velocity.Y, 0) * (root :: BasePart).AssemblyMass
            )
            return
        elseif mode == "Fall" then
            if velocity.Y >= 0 then
                return
            end
            vertical = 0
        else
            vertical = strength
        end

        humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
        ;(root :: BasePart).AssemblyLinearVelocity = Vector3.new(velocity.X, vertical, velocity.Z)
    end

    local jump: any
    jump = framework.Categories.Movement:CreateModule({
        Name = "Jump",
        Category = "Movement",
        ConfigKey = "Universal.Jump",
        Order = 6,
        Tooltip = "Consolidated jump controls: adjust Jump Power, execute High Jump, enable Infinite Jump and Auto Jump.",
        Function = function(enabled: boolean): ()
            restoreJumpPower()
            lastInfiniteJumpAt = -math.huge
            if not enabled then
                jump:SetStatus(nil)
                return
            end

            jump:SetStatus("active")
            jump:Clean(restoreJumpPower)

            if movementInput and type(movementInput.onJumpRequest) == "function" then
                jump:Clean(movementInput.onJumpRequest(function(): ()
                    local opts = jump.Options
                    if not opts["Infinite jump"] or not opts["Infinite jump"].Value then
                        return
                    end
                    local mode: string = opts["Infinite jump mode"] and opts["Infinite jump mode"].Value or "Normal"
                    if mode == "Rise" then
                        return
                    end
                    local strength: number = opts["Infinite jump power"] and opts["Infinite jump power"].Value or 50
                    local interval: number = opts["Jump interval"] and opts["Jump interval"].Value or 0.18
                    performInfiniteJump(mode, strength, interval, 160)
                end))
            end

            jump:Loop(function(): ()
                local opts = jump.Options
                local _, humanoid: Humanoid?, root: BasePart? = characterParts()
                if not humanoid or not root or humanoid.Health <= 0 then
                    return
                end

                if opts["Custom jump power"] and opts["Custom jump power"].Value then
                    local wantedPower: number = opts["Jump power"] and opts["Jump power"].Value or 80
                    if originalJumpPower[humanoid] == nil then
                        originalJumpPower[humanoid] = {
                            jumpPower = humanoid.JumpPower,
                            useJumpPower = humanoid.UseJumpPower,
                        }
                    end
                    humanoid.UseJumpPower = true
                    humanoid.JumpPower = wantedPower
                else
                    restoreJumpPower()
                end

                if opts["Auto jump"] and opts["Auto jump"].Value then
                    local moveDir: Vector3 = humanoid.MoveDirection
                    if moveDir.Magnitude > 0.05 and humanoid.FloorMaterial ~= Enum.Material.Air then
                        humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                    end
                end

                if opts["Infinite jump"] and opts["Infinite jump"].Value then
                    local mode: string = opts["Infinite jump mode"] and opts["Infinite jump mode"].Value or "Normal"
                    if mode == "Rise" and movementInput and type(movementInput.isJumpHeld) == "function" and movementInput.isJumpHeld() then
                        humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
                        local curVel: Vector3 = (root :: BasePart).AssemblyLinearVelocity
                        local riseSpd: number = opts["Rise speed"] and opts["Rise speed"].Value or 75
                        ;(root :: BasePart).AssemblyLinearVelocity = Vector3.new(curVel.X, riseSpd, curVel.Z)
                    end
                end
            end)
        end,
    })

    jump:CreateToggle({
        Name = "Custom jump power",
        Default = false,
        Tooltip = "Enables custom jump height/power for ground jumps. Turn off if you only want Infinite Jump or High Jump.",
    })

    jump:CreateSlider({
        Name = "Jump power",
        Show = {Option = "Custom jump power", Values = {true}},
        Min = 0,
        Max = 500,
        Default = 80,
        Function = function(value: number): ()
            if jump.Enabled and jump.Options["Custom jump power"].Value then
                jump:SetStatus(tostring(math.round(value)))
            end
        end,
        Tooltip = "Character jump power (default Roblox jump is 50).",
    })

    jump:CreateButton({
        Name = "High jump",
        Function = function(): ()
            local velocityVal: number = jump.Options["High jump velocity"] and jump.Options["High jump velocity"].Value or 72
            performHighJump(velocityVal)
        end,
        Tooltip = "Launches your character into a single massive vertical jump.",
    })

    jump:CreateSlider({
        Name = "High jump velocity",
        Min = 25,
        Max = 250,
        Default = 72,
        Tooltip = "Vertical velocity applied when High Jump button is pressed.",
    })

    jump:CreateToggle({
        Name = "Infinite jump",
        Default = false,
        Tooltip = "Allows jumping repeatedly in mid-air.",
    })

    jump:CreateDropdown({
        Name = "Infinite jump mode",
        Show = {Option = "Infinite jump", Values = {true}},
        List = {"Normal", "Impulse", "Stack", "Rise", "Fall"},
        Index = 1,
        Tooltip = "Normal = fixed mid-air jump; Impulse = physical thrust; Stack = accumulative upward velocity; Rise = hold to float up; Fall = cancels downward fall speed.",
    })

    jump:CreateSlider({
        Name = "Infinite jump power",
        Show = {Option = "Infinite jump", Values = {true}},
        Min = 10,
        Max = 250,
        Default = 50,
        Tooltip = "Vertical impulse applied during mid-air jumps.",
    })

    jump:CreateSlider({
        Name = "Rise speed",
        Show = {Option = "Infinite jump", Values = {true}},
        Min = 10,
        Max = 350,
        Default = 75,
        Tooltip = "Vertical speed while holding jump in Rise mode.",
    })

    jump:CreateSlider({
        Name = "Jump interval",
        Show = {Option = "Infinite jump", Values = {true}},
        Min = 0.05,
        Max = 0.6,
        Default = 0.18,
        Tooltip = "Minimum delay in seconds between mid-air jumps.",
    })

    jump:CreateToggle({
        Name = "Auto jump",
        Default = false,
        Tooltip = "Continuously jumps while walking on the ground.",
    })

    activeCleanup = function(): ()
        restoreJumpPower()
    end
    Module.Initialized = true
    return jump
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Movement/SafeWalk.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "SafeWalk",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local TaskManager: any = host.TaskManager
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local getCharacterParts: any = host.getCharacterParts
    local createUniversalFeature: any = host.createUniversalFeature
    local addNumberOption: any = host.addNumberOption
    local currentWorkspace: Workspace = host.workspace or workspace

    local safeWalkSettings: {
        lookAhead: number,
        barrierHeight: number,
    } = {
        lookAhead = 2.8,
        barrierHeight = 4.5,
    }

    local barrierFolder: Folder? = nil
    local barrier: BasePart? = nil
    local SafeWalkFeature: any = nil

    local function ensureBarrier(): BasePart
        local existing: BasePart? = barrier
        if existing and existing.Parent then
            return existing
        end
        if not barrierFolder or not barrierFolder.Parent then
            barrierFolder = Instance.new("Folder")
            barrierFolder.Name = "WurstSafeWalk"
            barrierFolder.Parent = currentWorkspace
        end
        local part: BasePart = Instance.new("Part")
        part.Name = "SafeWalkBarrier"
        part.Anchored = true
        part.CanCollide = true
        part.CanQuery = false
        part.CanTouch = false
        part.Massless = true
        part.CastShadow = false
        part.Transparency = 1
        part.Material = Enum.Material.SmoothPlastic
        part.Size = Vector3.new(7, safeWalkSettings.barrierHeight, 0.35)
        part:SetAttribute("WurstSafeWalk", true)
        part.Parent = barrierFolder
        barrier = part
        return part
    end

    local function hideBarrier(): ()
        if barrierFolder then
            barrierFolder:Destroy()
        end
        barrierFolder = nil
        barrier = nil
    end

    local function toggleSafeWalk(enabled: boolean): ()
        disconnectFeatureConnection("SafeWalk")
        hideBarrier()
        if not enabled then
            if SafeWalkFeature then
                SafeWalkFeature:SetStatus(nil)
            end
            return
        end

        featureConnections.SafeWalk = TaskManager:Connect(function(): ()
            local character: Model?, humanoid: Humanoid?, root: BasePart? = getCharacterParts()
            if not character or not humanoid or not root
                or humanoid.Health <= 0 then
                hideBarrier()
                return
            end

            if humanoid.MoveDirection.Magnitude < 0.05 then
                return
            end
            if humanoid.FloorMaterial == Enum.Material.Air then
                return
            end

            local moveDirection: Vector3 = humanoid.MoveDirection.Unit
            local parameters: RaycastParams = RaycastParams.new()
            parameters.FilterType = Enum.RaycastFilterType.Exclude
            parameters.FilterDescendantsInstances = {character}
            parameters.IgnoreWater = true

            local stepCount: number = 7
            local reach: number = 1.0 + safeWalkSettings.lookAhead + 0.8
            local step: number = (reach - 1.0) / (stepCount - 1)
            local lastGrounded: number? = nil
            local firstGap: number? = nil
            for index: number = 1, stepCount do
                local distance: number = 1.0 + step * (index - 1)
                local probeOrigin: Vector3 = root.Position + moveDirection * distance
                local ground: RaycastResult? = currentWorkspace:Raycast(
                    probeOrigin,
                    Vector3.new(0, -6, 0),
                    parameters
                )
                if ground then
                    lastGrounded = distance
                elseif lastGrounded ~= nil then
                    firstGap = distance
                    break
                end
            end

            if lastGrounded == nil then

                lastGrounded = 0.4
                firstGap = 1.0
            end
            if firstGap == nil then

                hideBarrier()
                if SafeWalkFeature then
                    SafeWalkFeature:SetStatus(nil)
                end
                return
            end

            local edgeDistance: number = (lastGrounded + firstGap) * 0.5
            local feetHeight: number = root.Size.Y * 0.5 + humanoid.HipHeight
            local barrierHeight: number = math.max(safeWalkSettings.barrierHeight, 3)
            local part: BasePart = ensureBarrier()
            part.Size = Vector3.new(7, barrierHeight, 0.35)
            local feetY: number = root.Position.Y - feetHeight
            local position: Vector3 = root.Position + moveDirection * edgeDistance

            part.CFrame = CFrame.lookAt(
                Vector3.new(position.X, feetY + barrierHeight * 0.5, position.Z),
                Vector3.new(position.X, feetY + barrierHeight * 0.5, position.Z)
                    + moveDirection
            )
            if SafeWalkFeature then
                SafeWalkFeature:SetStatus("edge")
            end
        end)
    end

    SafeWalkFeature = createUniversalFeature(
        "SafeWalk",
        "Place an invisible barrier at edges so you cannot walk off ledges",
        21,
        toggleSafeWalk,
        {
            configKey = "Universal.SafeWalk",
            categoryName = "Movement",
        }
    )
    addNumberOption(
        SafeWalkFeature,
        "Edge look-ahead",
        safeWalkSettings.lookAhead,
        1.5,
        6,
        function(value: number): ()
            safeWalkSettings.lookAhead = value
        end
    )
    addNumberOption(
        SafeWalkFeature,
        "Barrier height",
        safeWalkSettings.barrierHeight,
        3,
        10,
        function(value: number): ()
            safeWalkSettings.barrierHeight = value
        end
    )

    activeCleanup = function(): ()
        disconnectFeatureConnection("SafeWalk")
        hideBarrier()
    end
    Module.Initialized = true
    return SafeWalkFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Movement/Speed.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "Speed",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local movementInput: any = context.services.movementInput
    local framework: any = context.framework
    local LocalPlayer: Player = host.LocalPlayer
    local currentWorkspace: Workspace = host.workspace or workspace

    type VehicleSeatState = {
        maxSpeed: number,
        torque: number,
        turnSpeed: number,
    }
    type HingeState = {
        angularVelocity: number,
        motorMaxTorque: number,
    }

    local runtime: any = {
        originalWalkSpeed = setmetatable({}, {__mode = "k"}) :: any,
        nextTeleportAt = 0,
        originalVehicleSeats = setmetatable({}, {__mode = "k"}) :: {[VehicleSeat]: VehicleSeatState},
        originalMotorHinges = setmetatable({}, {__mode = "k"}) :: {[HingeConstraint]: HingeState},
        velocityExcess = setmetatable({}, {__mode = "k"}) :: {[BasePart]: number},
        motorExcess = setmetatable({}, {__mode = "k"}) :: {[HingeConstraint]: number},
    }

    local function characterParts(): (Model?, Humanoid?, BasePart?)
        local character: Model? = LocalPlayer.Character
        if not character then
            return nil, nil, nil
        end
        local humanoid: Humanoid? =
            character:FindFirstChildOfClass("Humanoid") :: Humanoid?
        local root: BasePart? =
            character:FindFirstChild("HumanoidRootPart") :: BasePart?
        return character, humanoid, root
    end

    local function restoreWalkSpeed(): ()
        for humanoid: Humanoid, value: number in pairs(runtime.originalWalkSpeed) do
            if humanoid and humanoid.Parent then
                humanoid.WalkSpeed = value
            end
        end
        runtime.originalWalkSpeed = setmetatable({}, {__mode = "k"}) :: any
    end

    local function clearVehicleBoostHistory(): ()
        runtime.velocityExcess = setmetatable({}, {__mode = "k"}) :: any
        runtime.motorExcess = setmetatable({}, {__mode = "k"}) :: any
    end

    local function restoreVehicle(): ()
        for seat: VehicleSeat, original: VehicleSeatState in pairs(runtime.originalVehicleSeats) do
            if seat.Parent then
                seat.MaxSpeed = original.maxSpeed
                seat.Torque = original.torque
                seat.TurnSpeed = original.turnSpeed
            end
        end
        runtime.originalVehicleSeats = setmetatable({}, {__mode = "k"}) :: any
        for hinge: HingeConstraint, original: HingeState in pairs(runtime.originalMotorHinges) do
            if hinge.Parent then
                hinge.AngularVelocity = original.angularVelocity
                hinge.MotorMaxTorque = original.motorMaxTorque
            end
        end
        runtime.originalMotorHinges = setmetatable({}, {__mode = "k"}) :: any
        clearVehicleBoostHistory()
    end

    local function resolveVehicle(): (BasePart?, Model?, VehicleSeat?)
        local character: Model?, humanoid: Humanoid?, root: BasePart? =
            characterParts()
        if not character or not humanoid or not root then
            return nil, nil, nil
        end
        local seatPart: BasePart? = humanoid.SeatPart
        local assembly: BasePart? = nil
        if seatPart then
            assembly = seatPart.AssemblyRootPart or seatPart
        else
            assembly = root.AssemblyRootPart
            if not assembly or assembly:IsDescendantOf(character) then
                return nil, nil, nil
            end
        end
        local resolvedAssembly: BasePart = assembly :: BasePart
        local model: Model? = (seatPart or resolvedAssembly):FindFirstAncestorOfClass("Model")
        local vehicleSeat: VehicleSeat? = seatPart
                and seatPart:IsA("VehicleSeat")
                and seatPart :: VehicleSeat
            or nil
        return resolvedAssembly, model, vehicleSeat
    end

    local function rememberVehicleParts(model: Model?): ()
        if not model then
            return
        end
        for _, descendant: Instance in ipairs(model:GetDescendants()) do
            if descendant:IsA("VehicleSeat")
                and runtime.originalVehicleSeats[descendant] == nil then
                runtime.originalVehicleSeats[descendant] = {
                    maxSpeed = descendant.MaxSpeed,
                    torque = descendant.Torque,
                    turnSpeed = descendant.TurnSpeed,
                }
            elseif descendant:IsA("HingeConstraint")
                and descendant.ActuatorType == Enum.ActuatorType.Motor
                and runtime.originalMotorHinges[descendant] == nil then
                runtime.originalMotorHinges[descendant] = {
                    angularVelocity = descendant.AngularVelocity,
                    motorMaxTorque = descendant.MotorMaxTorque,
                }
            end
        end
    end

    local function boostedVehicleBase(current: number, previousExcess: number, multiplier: number): number
        local base: number = math.max(current - previousExcess, 0)
        if base < 0.01 and current > 0.01 then
            base = current / math.max(multiplier, 1)
        end
        return base
    end

    local function boostVehicleVelocity(assembly: BasePart, forcedDirection: Vector3?, multiplier: number): ()
        local current: Vector3 = assembly.AssemblyLinearVelocity
        local horizontal: Vector3 = Vector3.new(current.X, 0, current.Z)
        local curSpeed: number = horizontal.Magnitude
        if curSpeed < 0.01 then
            runtime.velocityExcess[assembly] = 0
            return
        end
        local base: number = boostedVehicleBase(curSpeed, runtime.velocityExcess[assembly] or 0, multiplier)
        local target: number = base * multiplier
        local direction: Vector3 = forcedDirection or horizontal.Unit
        direction = Vector3.new(direction.X, 0, direction.Z)
        if direction.Magnitude < 0.01 then
            return
        end
        direction = direction.Unit
        assembly.AssemblyLinearVelocity = direction * target + Vector3.new(0, current.Y, 0)
        runtime.velocityExcess[assembly] = math.max(target - base, 0)
    end

    local function boostVehicleMotors(model: Model?, multiplier: number, motorTorque: number): ()
        rememberVehicleParts(model)
        for hinge: HingeConstraint, original: HingeState in pairs(runtime.originalMotorHinges) do
            if not hinge.Parent or (model and not hinge:IsDescendantOf(model)) then
                continue
            end
            local current: number = hinge.AngularVelocity
            local sign: number = current < 0 and -1 or 1
            local magnitude: number = math.abs(current)
            local base: number = boostedVehicleBase(magnitude, runtime.motorExcess[hinge] or 0, multiplier)
            local target: number = base * multiplier
            hinge.AngularVelocity = sign * target
            hinge.MotorMaxTorque = math.max(
                original.motorMaxTorque * multiplier,
                motorTorque
            )
            runtime.motorExcess[hinge] = math.max(target - base, 0)
        end
    end

    local function boostVehicleSeatProperties(model: Model?, seat: VehicleSeat?, multiplier: number): ()
        rememberVehicleParts(model)
        if seat and runtime.originalVehicleSeats[seat] == nil then
            runtime.originalVehicleSeats[seat] = {
                maxSpeed = seat.MaxSpeed,
                torque = seat.Torque,
                turnSpeed = seat.TurnSpeed,
            }
        end
        for candidate: VehicleSeat, original: VehicleSeatState in pairs(runtime.originalVehicleSeats) do
            if not candidate.Parent or (model and not candidate:IsDescendantOf(model)) then
                continue
            end
            candidate.MaxSpeed = original.maxSpeed * multiplier
            candidate.Torque = original.torque * multiplier
            candidate.TurnSpeed = original.turnSpeed * multiplier
        end
    end

    local function moveDirection(): Vector3
        local camera: Camera? = currentWorkspace.CurrentCamera
        local forward: number, right: number = 0, 0
        if movementInput.getVector then
            forward, right = movementInput.getVector()
        end
        if forward == 0 and right == 0 then
            local _, humanoid: Humanoid? = characterParts()
            local move: Vector3 = humanoid and humanoid.MoveDirection or Vector3.zero
            return move.Magnitude > 0.05 and move.Unit or Vector3.zero
        end
        if not camera then
            return Vector3.zero
        end
        local look: Vector3 = (camera :: Camera).CFrame.LookVector
        local side: Vector3 = (camera :: Camera).CFrame.RightVector
        local flatLook: Vector3 = Vector3.new(look.X, 0, look.Z)
        local flatSide: Vector3 = Vector3.new(side.X, 0, side.Z)
        if flatLook.Magnitude < 0.001 then
            return Vector3.zero
        end
        local direction: Vector3 =
            flatLook.Unit * forward + flatSide.Unit * right
        return direction.Magnitude > 0.05 and direction.Unit or Vector3.zero
    end

    local function blocked(root: BasePart, step: Vector3): Vector3
        local parameters: RaycastParams = RaycastParams.new()
        parameters.FilterType = Enum.RaycastFilterType.Exclude
        parameters.RespectCanCollide = true
        local ignore: {Instance} = {LocalPlayer.Character :: Instance}
        for _, player: Player in ipairs(host.Players:GetPlayers()) do
            if player ~= LocalPlayer and player.Character then
                table.insert(ignore, player.Character :: Instance)
            end
        end
        parameters.FilterDescendantsInstances = ignore
        local hit: RaycastResult? =
            currentWorkspace:Raycast(root.Position, step, parameters)
        if not hit then
            return step
        end
        return ((hit :: RaycastResult).Position + (hit :: RaycastResult).Normal)
            - root.Position
    end

    local speed: any
    speed = framework.Categories.Movement:CreateModule({
        Name = "Speed",
        Category = "Movement",
        ConfigKey = "Universal.Speed",
        Order = 1,
        Tooltip = "Move faster on foot or in vehicles, by whichever method works best.",
        Function = function(enabled: boolean): ()
            runtime.nextTeleportAt = 0
            restoreWalkSpeed()
            restoreVehicle()
            if not enabled then
                speed:SetStatus(nil)
                return
            end
            speed:SetStatus(
                tostring(speed.Options["Mode"].Value)
                    .. " "
                    .. tostring(math.round(speed.Options["Speed"].Value))
            )
            speed:Clean(function(): ()
                restoreWalkSpeed()
                restoreVehicle()
            end)
            speed:Loop(function(deltaTime: number): ()
                local options: any = speed.Options
                local _, humanoid: Humanoid?, root: BasePart? = characterParts()
                if not humanoid or not root then
                    return
                end
                local resolvedHumanoid: Humanoid = humanoid :: Humanoid
                local resolvedRoot: BasePart = root :: BasePart
                if resolvedHumanoid.Health <= 0 then
                    return
                end

                if options["Vehicle speed"] and options["Vehicle speed"].Value then
                    local assembly: BasePart?, model: Model?, seat: VehicleSeat? =
                        resolveVehicle()
                    if assembly then
                        local vehMode: string = options["Vehicle mode"] and options["Vehicle mode"].Value or "Multiplier"
                        local vehMultiplier: number = options["Vehicle multiplier"] and options["Vehicle multiplier"].Value or 2
                        local motorTorque: number = options["Motor torque"] and options["Motor torque"].Value or 50000
                        if vehMode == "Multiplier" then
                            boostVehicleVelocity(assembly :: BasePart, nil, vehMultiplier)
                        elseif vehMode == "Motors" then
                            boostVehicleMotors(model, vehMultiplier, motorTorque)
                        elseif vehMode == "Velocity" then
                            local direction: Vector3? = seat
                                and (seat :: VehicleSeat).CFrame.LookVector
                                    * (seat :: VehicleSeat).ThrottleFloat
                                or nil
                            boostVehicleVelocity(assembly :: BasePart, direction, vehMultiplier)
                        else
                            boostVehicleSeatProperties(model, seat, vehMultiplier)
                        end
                        return
                    end
                end

                local mode: string = options["Mode"].Value
                local target: number = options["Speed"].Value

                if mode == "WalkSpeed" then
                    if runtime.originalWalkSpeed[resolvedHumanoid] == nil then
                        runtime.originalWalkSpeed[resolvedHumanoid] =
                            resolvedHumanoid.WalkSpeed
                    end
                    resolvedHumanoid.WalkSpeed = target
                    return
                end
                restoreWalkSpeed()

                local direction: Vector3 = moveDirection()
                if direction.Magnitude < 0.05 then
                    return
                end

                if options["Auto jump"].Value
                    and resolvedHumanoid.FloorMaterial ~= Enum.Material.Air then
                    resolvedHumanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                end

                local velocity: Vector3 = resolvedRoot.AssemblyLinearVelocity
                if mode == "Velocity" then
                    resolvedRoot.AssemblyLinearVelocity = Vector3.new(
                        direction.X * target,
                        velocity.Y,
                        direction.Z * target
                    )
                    return
                end
                if mode == "Impulse" then
                    local wanted: Vector3 = direction * target
                    local difference: Vector3 = Vector3.new(
                        wanted.X - velocity.X,
                        0,
                        wanted.Z - velocity.Z
                    )
                    if difference.Magnitude > 2 then
                        resolvedRoot:ApplyImpulse(
                            difference * resolvedRoot.AssemblyMass
                        )
                    end
                    return
                end

                local extra: number =
                    math.max(target - resolvedHumanoid.WalkSpeed, 0)
                if mode == "Teleport" then
                    local now: number = os.clock()
                    if now < runtime.nextTeleportAt then
                        return
                    end
                    runtime.nextTeleportAt = now + options["Burst delay"].Value
                    local step: Vector3 = direction * extra
                        * options["Burst delay"].Value
                    if options["Wall check"].Value then
                        step = blocked(resolvedRoot, step)
                    end
                    resolvedRoot.CFrame = resolvedRoot.CFrame + step
                    return
                end

                local step: Vector3 = direction * extra * deltaTime
                if options["Wall check"].Value then
                    step = blocked(resolvedRoot, step)
                end
                resolvedRoot.CFrame = resolvedRoot.CFrame + step
            end)
        end,
    })

    speed:CreateDropdown({
        Name = "Mode",
        List = {"WalkSpeed", "Velocity", "Impulse", "CFrame", "Teleport"},
        Index = 1,
        Function = function(value: string): ()
            if speed.Enabled then
                speed:SetStatus(
                    value .. " " .. tostring(math.round(speed.Options["Speed"].Value))
                )
            end
        end,
        Tooltip = "WalkSpeed is the quietest; Velocity and Impulse are smooth physics; CFrame and Teleport step directly.",
    })
    speed:CreateSlider({
        Name = "Speed",
        Min = 16,
        Max = 200,
        Default = 32,
        Function = function(value: number): ()
            if speed.Enabled then
                speed:SetStatus(
                    tostring(speed.Options["Mode"].Value)
                        .. " "
                        .. tostring(math.round(value))
                )
            end
        end,
        Tooltip = "Studs per second for on-foot movement.",
    })
    speed:CreateToggle({
        Name = "Wall check",
        Show = {Option = "Mode", Values = {"CFrame", "Teleport"}},
        Default = true,
        Tooltip = "Stop at geometry instead of stepping through it.",
    })
    speed:CreateSlider({
        Name = "Burst delay",
        Show = {Option = "Mode", Values = {"Teleport"}},
        Min = 0.05,
        Max = 1,
        Default = 0.2,
        Tooltip = "Seconds between teleport steps.",
    })
    speed:CreateToggle({
        Name = "Auto jump",
        Show = {Option = "Mode", Values = {"Velocity", "Impulse", "CFrame", "Teleport"}},
        Default = false,
        Tooltip = "Hop continuously while moving.",
    })

    speed:CreateToggle({
        Name = "Vehicle speed",
        Default = false,
        Function = function(enabled: boolean): ()
            if not enabled then
                restoreVehicle()
            end
        end,
        Tooltip = "Boosts any vehicle or mount you are currently driving.",
    })
    speed:CreateDropdown({
        Name = "Vehicle mode",
        Show = {Option = "Vehicle speed", Values = {true}},
        List = {"Multiplier", "Motors", "Velocity", "Seat"},
        Index = 1,
        Function = function(): ()
            restoreVehicle()
        end,
        Tooltip = "Multiplier preserves vehicle steering; Motors powers wheel constraints; Velocity pushes the chassis; Seat boosts VehicleSeat properties.",
    })
    speed:CreateSlider({
        Name = "Vehicle multiplier",
        Show = {Option = "Vehicle speed", Values = {true}},
        Min = 1,
        Max = 10,
        Default = 2,
        Function = function(): ()
            clearVehicleBoostHistory()
        end,
        Tooltip = "Speed multiplier applied to vehicle driving speed.",
    })
    speed:CreateSlider({
        Name = "Motor torque",
        Show = {Option = "Vehicle speed", Values = {true}},
        Min = 1000,
        Max = 250000,
        Default = 50000,
        Tooltip = "Torque limit for motor hinges.",
    })

    activeCleanup = function(): ()
        restoreWalkSpeed()
        restoreVehicle()
    end
    Module.Initialized = true
    return speed
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Other/AntiAfk.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "AntiAfk",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local LocalPlayer: any = host.LocalPlayer
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local createUniversalFeature: any = host.createUniversalFeature
    local addFeatureTooltip: any = host.addFeatureTooltip
    local function toggleAntiAfk(enabled)
        disconnectFeatureConnection("AntiAFK")

        if not enabled then
            return
        end

        featureConnections.AntiAFK = LocalPlayer.Idled:Connect(function()
            local virtualUserOk, virtualUser = pcall(function()
                return game:GetService("VirtualUser")
            end)
            if virtualUserOk and virtualUser then
                virtualUser:CaptureController()
                virtualUser:ClickButton2(Vector2.new(0, 0))
            end
        end)
    end

    local AntiAfkFeature = createUniversalFeature(
        "AntiAFK",
        "Prevent the local idle event from disconnecting",
        13,
        toggleAntiAfk,
        {
            noOptions = true,
            configKey = "Universal.AntiAFK",
            categoryName = "Other",
        }
    )
    addFeatureTooltip(AntiAfkFeature, "Responds only to Roblox's local idle event and "
        .. "disconnects immediately when disabled.")

    activeCleanup = function(): ()

        disconnectFeatureConnection("AntiAFK")
    end
    Module.Initialized = true
    return AntiAfkFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Other/Disguise.lua"] = [[
--!strict
export type Runtime = {
    framework: any,
    host: any,
    services: any,
}

type AppearanceTemplate = {
    object: Instance,
    parent: Instance?,
}

type MeshTemplate = {
    part: MeshPart,
    meshId: string,
    textureId: string,
}

type AnimationTemplate = {
    animation: Animation,
    animationId: string,
}

type AppearanceSnapshot = {
    character: Model,
    items: {AppearanceTemplate},
    meshParts: {MeshTemplate},
    animations: {AnimationTemplate},
    emotes: any,
    equippedEmotes: any,
    scales: {[string]: number},
}

local Module = {
    Name = "Disguise",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCard: any = nil

local DEFAULT_USER_ID: number = 239702688
local SCALE_FIELDS: {string} = {
    "HeightScale",
    "WidthScale",
    "DepthScale",
    "HeadScale",
    "BodyTypeScale",
    "ProportionScale",
}
local BODY_PARTS: {[string]: boolean} = {
    Head = true,
    Torso = true,
    UpperTorso = true,
    LowerTorso = true,
    LeftArm = true,
    RightArm = true,
    LeftLeg = true,
    RightLeg = true,
    LeftUpperArm = true,
    LeftLowerArm = true,
    LeftHand = true,
    RightUpperArm = true,
    RightLowerArm = true,
    RightHand = true,
    LeftUpperLeg = true,
    LeftLowerLeg = true,
    LeftFoot = true,
    RightUpperLeg = true,
    RightLowerLeg = true,
    RightFoot = true,
}
local MOVEMENT_ANIMATIONS: {{descriptionField: string, scriptCategory: string}} = {
    {descriptionField = "IdleAnimation", scriptCategory = "idle"},
    {descriptionField = "WalkAnimation", scriptCategory = "walk"},
    {descriptionField = "RunAnimation", scriptCategory = "run"},
    {descriptionField = "JumpAnimation", scriptCategory = "jump"},
    {descriptionField = "ClimbAnimation", scriptCategory = "climb"},
    {descriptionField = "FallAnimation", scriptCategory = "fall"},
    {descriptionField = "SwimAnimation", scriptCategory = "swim"},
    {descriptionField = "SwimIdleAnimation", scriptCategory = "swimidle"},
    {descriptionField = "MoodAnimation", scriptCategory = "mood"},
}

function Module.init(context: Runtime): any
    local framework: any = context.framework
    local host: any = context.host
    local Players: Players = host.Players or (game :: any):GetService("Players")
    local MarketplaceService: MarketplaceService = host.MarketplaceService
        or (game :: any):GetService("MarketplaceService")
    local LocalPlayer: Player = host.LocalPlayer or Players.LocalPlayer

    local cloned = setmetatable({}, {__mode = "k"}) :: {[Instance]: boolean}
    local disguisedItems = setmetatable({}, {__mode = "k"}) :: {[Instance]: boolean}
    local snapshot: AppearanceSnapshot? = nil
    local filteredCharacter: Model? = nil
    local filterConnection: RBXScriptConnection? = nil
    local generation: number = 0
    local restoring: boolean = false
    local emotesAppliedToHumanoid: boolean = false
    local animationOverrideApplied: boolean = false
    local targetEmotes: any = nil
    local targetEquippedEmotes: any = nil

    local settings = {
        mode = "Character",
        id = tostring(DEFAULT_USER_ID),
        useTargetMovementAnimations = false,
    }

    local function notify(message: string): ()
        pcall(print, "[Wurst:Disguise] " .. message)
        if activeCard then
            pcall(activeCard.Notify, activeCard, message)
        end
    end

    local function isAppearanceItem(obj: Instance): boolean
        return obj:IsA("Accessory")
            or obj:IsA("ShirtGraphic")
            or obj:IsA("Shirt")
            or obj:IsA("Pants")
            or obj:IsA("BodyColors")
            or ((obj:IsA("Decal") or obj:IsA("Texture"))
                and string.lower(obj.Name) == "face")
    end

    local function isInsideCharacter(obj: Instance, character: Model): boolean
        local ok: boolean, result: any = pcall(function()
            return obj:IsDescendantOf(character)
        end)
        return ok and result == true
    end

    local function rebindAccessory(character: Model, accessory: Accessory): ()
        for _, descendant: Instance in ipairs(accessory:GetDescendants()) do
            if descendant:IsA("Weld") and descendant.Part1 then
                local part: Instance? = character:FindFirstChild(
                    descendant.Part1.Name
                )
                if part and part:IsA("BasePart") then
                    descendant.Part1 = part
                end
            elseif descendant:IsA("RigidConstraint")
                and descendant.Attachment1 then
                local attachment: Instance? = character:FindFirstChild(
                    descendant.Attachment1.Name,
                    true
                )
                if attachment and attachment:IsA("Attachment") then
                    descendant.Attachment1 = attachment
                end
            end
        end
    end

    local function destroySnapshot(): ()
        local current: AppearanceSnapshot? = snapshot
        snapshot = nil
        emotesAppliedToHumanoid = false
        animationOverrideApplied = false
        if current then
            for _, entry: AppearanceTemplate in ipairs(current.items) do
                pcall(entry.object.Destroy, entry.object)
            end
        end
    end

    local function getAppliedDescription(humanoid: Humanoid): (any?, boolean)
        local child: HumanoidDescription? = humanoid:FindFirstChildOfClass(
            "HumanoidDescription"
        ) :: HumanoidDescription?
        if not child then
            local waitOk: boolean, waited: any = pcall(function()
                return humanoid:WaitForChild("HumanoidDescription", 2)
            end)
            if waitOk and waited and waited:IsA("HumanoidDescription") then
                child = waited :: HumanoidDescription
            end
        end
        if child then
            return child, false
        end
        local ok: boolean, result: any = pcall(function()
            return humanoid:GetAppliedDescription()
        end)
        if ok and result then
            return result, true
        end
        return nil, false
    end

    local function cloneTable(value: any): any
        if type(value) ~= "table" then
            return value
        end
        local copy: any = {}
        for key: any, entry: any in pairs(value) do
            copy[key] = if type(entry) == "table" then table.clone(entry) else entry
        end
        return copy
    end

    local function readDescriptionEmotes(description: any): (any?, any?)
        local ok: boolean, emotes: any, equipped: any = pcall(function()
            return description:GetEmotes(), description:GetEquippedEmotes()
        end)
        if not ok or type(emotes) ~= "table" or type(equipped) ~= "table" then
            return nil, nil
        end
        return cloneTable(emotes), cloneTable(equipped)
    end

    local function applyDescriptionToHumanoid(
        humanoid: Humanoid,
        description: any
    ): (boolean, string?)
        local humanoidObject: any = humanoid
        local lastError: string = "ApplyDescription is unavailable."
        for _, methodName: string in ipairs({
            "ApplyDescriptionResetAsync",
            "ApplyDescriptionAsync",
            "ApplyDescriptionReset",
            "ApplyDescription",
        }) do
            local method: any = humanoidObject[methodName]
            if type(method) == "function" then
                local ok: boolean, result: any = pcall(
                    method,
                    humanoidObject,
                    description
                )
                if ok then
                    return true, nil
                end
                lastError = tostring(result)
            end
        end
        return false, lastError
    end

    local function setHumanoidEmotes(
        humanoid: Humanoid,
        emotes: any,
        equippedEmotes: any
    ): (boolean, string?)
        if type(emotes) ~= "table" or type(equippedEmotes) ~= "table" then
            return false, "The avatar description did not expose emote data."
        end
        local description: any, isTemporary: boolean = getAppliedDescription(humanoid)
        if not description then
            return false, "Could not read the current HumanoidDescription."
        end
        local setOk: boolean, setError: any = pcall(function()
            description:SetEmotes(cloneTable(emotes))
            description:SetEquippedEmotes(cloneTable(equippedEmotes))
        end)
        if not setOk then
            if isTemporary then
                pcall(description.Destroy, description)
            end
            return false, tostring(setError)
        end
        if not isTemporary then

            return true, nil
        end

        local applied: boolean, applyError: string? =
            applyDescriptionToHumanoid(humanoid, description)
        pcall(description.Destroy, description)
        return applied, applyError
    end

    local function captureSnapshot(
        character: Model,
        humanoid: Humanoid
    ): AppearanceSnapshot
        local items: {AppearanceTemplate} = {}
        local meshParts: {MeshTemplate} = {}
        local animations: {AnimationTemplate} = {}
        local scales: {[string]: number} = {}
        local emotes: any = {}
        local equippedEmotes: any = {}

        for _, obj: Instance in ipairs(character:GetDescendants()) do
            if isAppearanceItem(obj) then
                local ok: boolean, copy: any = pcall(function()
                    return obj:Clone()
                end)
                if ok and copy then
                    copy.Parent = nil
                    table.insert(items, {
                        object = copy,
                        parent = obj.Parent,
                    })
                end
            elseif obj:IsA("MeshPart") and BODY_PARTS[obj.Name] then
                table.insert(meshParts, {
                    part = obj,
                    meshId = obj.MeshId,
                    textureId = obj.TextureID,
                })
            elseif obj:IsA("Animation") then
                local animate: Instance? = character:FindFirstChild("Animate")
                if animate and obj:IsDescendantOf(animate) then
                    table.insert(animations, {
                        animation = obj,
                        animationId = obj.AnimationId,
                    })
                end
            end
        end

        local description: any, isTemporary: boolean = getAppliedDescription(humanoid)
        if description then
            for _, field: string in ipairs(SCALE_FIELDS) do
                local ok: boolean, value: any = pcall(function()
                    return description[field]
                end)
                if ok and type(value) == "number" then
                    scales[field] = value
                end
            end
            local originalEmotes: any, originalEquipped: any =
                readDescriptionEmotes(description)
            if originalEmotes and originalEquipped then
                emotes = originalEmotes
                equippedEmotes = originalEquipped
            end
            if isTemporary then
                pcall(description.Destroy, description)
            end
        end

        return {
            character = character,
            items = items,
            meshParts = meshParts,
            animations = animations,
            emotes = emotes,
            equippedEmotes = equippedEmotes,
            scales = scales,
        }
    end

    local function ensureSnapshot(
        character: Model,
        humanoid: Humanoid
    ): AppearanceSnapshot
        if snapshot and snapshot.character == character then
            return snapshot
        end
        destroySnapshot()
        snapshot = captureSnapshot(character, humanoid)
        return snapshot
    end

    local function restartAnimateScript(animate: Instance): ()
        local scriptObject: any = animate
        local enabledOk: boolean, wasEnabled: any = pcall(function()
            return scriptObject.Enabled
        end)
        if enabledOk and type(wasEnabled) == "boolean" then
            if not wasEnabled then
                return
            end
            local disabledOk: boolean = pcall(function()
                scriptObject.Enabled = false
            end)
            if disabledOk then
                task.wait()
                pcall(function()
                    scriptObject.Enabled = wasEnabled
                end)
                task.wait()
                return
            end
        end

        local disabledOk: boolean, wasDisabled: any = pcall(function()
            return scriptObject.Disabled
        end)
        if disabledOk and type(wasDisabled) == "boolean" then
            local pauseOk: boolean = pcall(function()
                scriptObject.Disabled = true
            end)
            if pauseOk then
                task.wait()
                pcall(function()
                    scriptObject.Disabled = wasDisabled
                end)
                task.wait()
            end
        end
    end


    local animationAssetCache: {[string]: {string}} = {}

    local function extractAnimationsFromAsset(rawAssetId: any): {string}
        local cacheKey: string = tostring(rawAssetId or "")
        if cacheKey == "" or cacheKey == "0" then
            return {}
        end
        if animationAssetCache[cacheKey] then
            return animationAssetCache[cacheKey]
        end

        local numericId: number? = nil
        if type(rawAssetId) == "number" and rawAssetId > 0 then
            numericId = rawAssetId
        elseif type(rawAssetId) == "string" then
            local matched: string? = string.match(rawAssetId, "%d+")
            if matched then
                numericId = tonumber(matched)
            end
        end

        local result: {string} = {}
        if numericId and numericId > 0 then

            local objectsOk: boolean, objects: any = pcall(function()
                return (game :: any):GetObjects("rbxassetid://" .. tostring(numericId))
            end)
            if objectsOk and type(objects) == "table" and #objects > 0 then
                for _, obj: Instance in ipairs(objects) do
                    if obj:IsA("Animation") and obj.AnimationId ~= "" then
                        table.insert(result, obj.AnimationId)
                    end
                    for _, descendant: Instance in ipairs(obj:GetDescendants()) do
                        if descendant:IsA("Animation") and descendant.AnimationId ~= "" then
                            table.insert(result, descendant.AnimationId)
                        end
                    end
                end
                for _, obj: Instance in ipairs(objects) do
                    destroyInstance(obj)
                end
            end

            if #result == 0 then
                local insertService: any = (game :: any):GetService("InsertService")
                if insertService and type(insertService.LoadAsset) == "function" then
                    local loadOk: boolean, loaded: any = pcall(function()
                        return insertService:LoadAsset(numericId)
                    end)
                    if loadOk and loaded then
                        if loaded:IsA("Animation") and loaded.AnimationId ~= "" then
                            table.insert(result, loaded.AnimationId)
                        end
                        for _, descendant: Instance in ipairs(loaded:GetDescendants()) do
                            if descendant:IsA("Animation") and descendant.AnimationId ~= "" then
                                table.insert(result, descendant.AnimationId)
                            end
                        end
                        destroyInstance(loaded)
                    end
                end
            end

            if #result == 0 then
                table.insert(result, "rbxassetid://" .. tostring(numericId))
            end
        elseif type(rawAssetId) == "string" and rawAssetId ~= "" then
            table.insert(result, rawAssetId)
        end

        animationAssetCache[cacheKey] = result
        return result
    end

    local function copyTargetMovementAnimations(
        character: Model,
        humanoid: Humanoid,
        description: any
    ): number
        local animate: Instance? = character:FindFirstChild("Animate")
        if not animate then
            return 0
        end

        local changedCount: number = 0
        for _, mapping in ipairs(MOVEMENT_ANIMATIONS) do
            local readOk: boolean, value: any = pcall(function()
                return description[mapping.descriptionField]
            end)
            local assetId: any = if readOk then value else nil
            local category: Instance? = animate:FindFirstChild(mapping.scriptCategory)
            if assetId and category then
                local animIds: {string} = extractAnimationsFromAsset(assetId)
                if #animIds > 0 then
                    local targets: {Animation} = {}
                    if category:IsA("Animation") then
                        table.insert(targets, category)
                    end
                    for _, descendant: Instance in ipairs(category:GetDescendants()) do
                        if descendant:IsA("Animation") then
                            table.insert(targets, descendant)
                        end
                    end
                    for idx: number, animation: Animation in ipairs(targets) do
                        local chosenId: string = animIds[idx] or animIds[1]
                        if chosenId and chosenId ~= "" and animation.AnimationId ~= chosenId then
                            local changed: boolean = pcall(function()
                                animation.AnimationId = chosenId
                            end)
                            if changed then
                                changedCount += 1
                            end
                        end
                    end
                end
            end
        end

        if changedCount > 0 then
            animationOverrideApplied = true
            local animator: Animator? = humanoid:FindFirstChildOfClass("Animator")
            if animator then
                local tracksOk: boolean, tracks: any = pcall(function()
                    return animator:GetPlayingAnimationTracks()
                end)
                if tracksOk and type(tracks) == "table" then
                    for _, track: AnimationTrack in ipairs(tracks) do
                        pcall(track.Stop, track)
                    end
                end
            end
            restartAnimateScript(animate)
        end
        return changedCount
    end

    local function applyTargetMovementAnimationsToCharacter(numericId: number): ()
        local character: Model? = LocalPlayer.Character
        local humanoid: Humanoid? = character
            and character:FindFirstChildOfClass("Humanoid")
            :: Humanoid?
        if not character or not humanoid or humanoid.Health <= 0 then
            notify("Your character is not available.")
            return
        end

        local animate: Instance? = character:FindFirstChild("Animate")
        if not animate then
            notify("Your character has no Animate script to update.")
            return
        end

        ensureSnapshot(character, humanoid)
        notify("Downloading target movement animations...")

        task.spawn(function(): ()
            local changedCount: number = 0

            local targetPlayer: Player? = Players:GetPlayerByUserId(numericId)
            if not targetPlayer then
                for _, p: Player in ipairs(Players:GetPlayers()) do
                    if tostring(p.UserId) == tostring(settings.id)
                        or string.lower(p.Name) == string.lower(tostring(settings.id))
                        or string.lower(p.DisplayName) == string.lower(tostring(settings.id)) then
                        targetPlayer = p
                        break
                    end
                end
            end

            local targetChar: Model? = targetPlayer and targetPlayer.Character
            local targetAnimate: Instance? = targetChar and targetChar:FindFirstChild("Animate")
            if targetAnimate then
                for _, mapping in ipairs(MOVEMENT_ANIMATIONS) do
                    local sourceCat: Instance? = targetAnimate:FindFirstChild(mapping.scriptCategory)
                    local targetCat: Instance? = animate:FindFirstChild(mapping.scriptCategory)
                    if sourceCat and targetCat then
                        local sourceAnims: {Animation} = {}
                        if sourceCat:IsA("Animation") and sourceCat.AnimationId ~= "" then
                            table.insert(sourceAnims, sourceCat)
                        end
                        for _, obj: Instance in ipairs(sourceCat:GetDescendants()) do
                            if obj:IsA("Animation") and obj.AnimationId ~= "" then
                                table.insert(sourceAnims, obj)
                            end
                        end
                        if #sourceAnims > 0 then
                            local targetAnims: {Animation} = {}
                            if targetCat:IsA("Animation") then
                                table.insert(targetAnims, targetCat)
                            end
                            for _, obj: Instance in ipairs(targetCat:GetDescendants()) do
                                if obj:IsA("Animation") then
                                    table.insert(targetAnims, obj)
                                end
                            end
                            for idx: number, targetAnim: Animation in ipairs(targetAnims) do
                                local src: Animation? = sourceAnims[idx] or sourceAnims[1]
                                if src and src.AnimationId ~= "" and targetAnim.AnimationId ~= src.AnimationId then
                                    local changed: boolean = pcall(function()
                                        targetAnim.AnimationId = src.AnimationId
                                    end)
                                    if changed then
                                        changedCount += 1
                                    end
                                end
                            end
                        end
                    end
                end
            end

            if changedCount == 0 then
                local description: any, fetchError: string? = getUserDescription(numericId)
                if not description then
                    notify("Could not load target avatar description: " .. tostring(fetchError))
                    return
                end
                changedCount = copyTargetMovementAnimations(character, humanoid, description)
                destroyInstance(description)
            else
                animationOverrideApplied = true
                local animator: Animator? = humanoid:FindFirstChildOfClass("Animator")
                if animator then
                    local tracksOk: boolean, tracks: any = pcall(function()
                        return animator:GetPlayingAnimationTracks()
                    end)
                    if tracksOk and type(tracks) == "table" then
                        for _, track: AnimationTrack in ipairs(tracks) do
                            pcall(track.Stop, track)
                        end
                    end
                end
                restartAnimateScript(animate)
            end

            if changedCount > 0 then
                notify("Applied " .. tostring(changedCount) .. " target movement animation slot(s); Animate restarted.")
            else
                notify("No custom movement animations found for ID " .. tostring(numericId) .. " (target may use default animations).")
            end
        end)
    end

    local function refreshMeshPartSnapshot(
        character: Model,
        current: AppearanceSnapshot
    ): ()
        local originalByName: {[string]: {meshId: string, textureId: string}} = {}
        for _, entry: MeshTemplate in ipairs(current.meshParts) do
            originalByName[entry.part.Name] = {
                meshId = entry.meshId,
                textureId = entry.textureId,
            }
        end

        local refreshed: {MeshTemplate} = {}
        for _, obj: Instance in ipairs(character:GetDescendants()) do
            if obj:IsA("MeshPart") and BODY_PARTS[obj.Name] then
                local original: {meshId: string, textureId: string}? =
                    originalByName[obj.Name]
                table.insert(refreshed, {
                    part = obj,
                    meshId = original and original.meshId or obj.MeshId,
                    textureId = original and original.textureId or obj.TextureID,
                })
            end
        end
        if #refreshed > 0 then
            current.meshParts = refreshed
        end
    end

    local function restoreOriginalAppearance(
        character: Model,
        humanoid: Humanoid?
    ): ()
        local current: AppearanceSnapshot? = snapshot
        if not current or current.character ~= character then
            return
        end

        restoring = true
        if emotesAppliedToHumanoid and humanoid then
            local emotesRestored: boolean = setHumanoidEmotes(
                humanoid,
                current.emotes,
                current.equippedEmotes
            )
            if emotesRestored then
                emotesAppliedToHumanoid = false
                refreshMeshPartSnapshot(character, current)
            end
        end

        local removals: {Instance} = {}
        table.clear(disguisedItems)
        table.clear(cloned)
        for _, obj: Instance in ipairs(character:GetDescendants()) do
            if isAppearanceItem(obj) then
                table.insert(removals, obj)
            end
        end
        for _, obj: Instance in ipairs(removals) do
            pcall(obj.Destroy, obj)
        end

        for _, entry: MeshTemplate in ipairs(current.meshParts) do
            if isInsideCharacter(entry.part, character) then
                pcall(function()
                    entry.part.MeshId = entry.meshId
                    entry.part.TextureID = entry.textureId
                end)
            end
        end
        for _, entry: AnimationTemplate in ipairs(current.animations) do
            if isInsideCharacter(entry.animation, character) then
                pcall(function()
                    entry.animation.AnimationId = entry.animationId
                end)
            end
        end

        local restartRestoredAnimations: boolean = animationOverrideApplied
        animationOverrideApplied = false

        for _, entry: AppearanceTemplate in ipairs(current.items) do
            local ok: boolean, copy: any = pcall(function()
                return entry.object:Clone()
            end)
            if ok and copy then
                local parent: Instance = entry.parent or character
                if parent ~= character and not isInsideCharacter(parent, character) then
                    if (copy:IsA("Decal") or copy:IsA("Texture"))
                        and string.lower(copy.Name) == "face" then
                        parent = character:FindFirstChild("Head") or character
                    else
                        parent = character
                    end
                end
                if copy:IsA("Accessory") then
                    rebindAccessory(character, copy)
                end
                pcall(function()
                    copy.Parent = parent
                end)
            end
        end
        restoring = false
        if restartRestoredAnimations then
            local animate: Instance? = character:FindFirstChild("Animate")
            if animate then
                if humanoid then
                    local animator: Animator? = humanoid:FindFirstChildOfClass("Animator")
                    if animator then
                        local tracksOk: boolean, tracks: any = pcall(function()
                            return animator:GetPlayingAnimationTracks()
                        end)
                        if tracksOk and type(tracks) == "table" then
                            for _, track: AnimationTrack in ipairs(tracks) do
                                pcall(track.Stop, track)
                            end
                        end
                    end
                end
                restartAnimateScript(animate)
            end
        end
    end

    local function stopAppearanceFilter(): ()
        if filterConnection then
            pcall(filterConnection.Disconnect, filterConnection)
            filterConnection = nil
        end
        filteredCharacter = nil
    end

    local function removeUnexpectedAppearance(obj: Instance): ()
        if restoring
            or not isAppearanceItem(obj)
            or cloned[obj]
            or disguisedItems[obj]
            or not activeCard
            or not activeCard.Enabled
            or settings.mode ~= "Character" then
            return
        end
        task.defer(function(): ()
            if restoring
                or not activeCard
                or not activeCard.Enabled
                or settings.mode ~= "Character"
                or cloned[obj]
                or disguisedItems[obj] then
                return
            end
            pcall(obj.Destroy, obj)
        end)
    end

    local function installAppearanceFilter(character: Model): ()
        if filteredCharacter == character
            and filterConnection
            and filterConnection.Connected then
            return
        end
        stopAppearanceFilter()
        filteredCharacter = character
        filterConnection = character.DescendantAdded:Connect(
            removeUnexpectedAppearance
        )
        if activeCard then
            activeCard:Clean(filterConnection)
        end
    end

    local function parseId(): (number?, string?)
        local trimmed: string = tostring(settings.id)
            :gsub("^%s+", "")
            :gsub("%s+$", "")
        if trimmed == "" then
            return nil, "Enter a positive integer ID or username first."
        end
        local value: number? = tonumber(trimmed)
        if value and value > 0 and value % 1 == 0 then
            return value, nil
        end
        for _, p: Player in ipairs(Players:GetPlayers()) do
            if string.lower(p.Name) == string.lower(trimmed)
                or string.lower(p.DisplayName) == string.lower(trimmed) then
                return p.UserId, nil
            end
        end
        local ok: boolean, resolvedId: any = pcall(function()
            return Players:GetUserIdFromNameAsync(trimmed)
        end)
        if ok and type(resolvedId) == "number" and resolvedId > 0 then
            return resolvedId, nil
        end
        return nil, "Enter a positive integer ID or valid username."
    end

    local function getUserDescription(userId: number): (any?, string?)
        local playersObject: any = Players
        local asyncGetter: any = playersObject.GetHumanoidDescriptionFromUserIdAsync
        local syncGetter: any = playersObject.GetHumanoidDescriptionFromUserId
        if type(asyncGetter) == "function" then
            local ok: boolean, result: any = pcall(asyncGetter, playersObject, userId)
            if ok and result then
                return result, nil
            end
            if not ok then
                local asyncError: string = tostring(result)
                if type(syncGetter) ~= "function" then
                    return nil, asyncError
                end
            end
        end
        if type(syncGetter) == "function" then
            local ok: boolean, result: any = pcall(syncGetter, playersObject, userId)
            if ok and result then
                return result, nil
            end
            return nil, tostring(result)
        end
        return nil, "This client does not expose a HumanoidDescription lookup API."
    end

    local function stillCurrent(token: number, character: Model): boolean
        return generation == token
            and activeCard ~= nil
            and activeCard.Enabled
            and LocalPlayer.Character == character
    end

    local function setDescriptionScales(
        description: any,
        current: AppearanceSnapshot
    ): ()
        for _, field: string in ipairs(SCALE_FIELDS) do
            local value: number? = current.scales[field]
            if value ~= nil then
                pcall(function()
                    description[field] = value
                end)
            end
        end
    end

    local function copyCharacterAppearance(
        character: Model,
        clone: Model
    ): ()
        local realHead: Instance? = character:FindFirstChild("Head")
        for _, source: Instance in ipairs(clone:GetChildren()) do
            if isAppearanceItem(source) then
                cloned[source] = true
                disguisedItems[source] = true
                if source:IsA("Accessory") then
                    rebindAccessory(character, source)
                end
                source.Parent = character
            elseif BODY_PARTS[source.Name]
                and source:IsA("MeshPart") then
                local target: Instance? = character:FindFirstChild(source.Name)
                if target and target:IsA("MeshPart") then

                    pcall(function()
                        target.MeshId = source.MeshId
                        target.TextureID = source.TextureID
                    end)
                end
            end
        end

        local targetFace: Instance? = clone:FindFirstChild("face", true)
        if targetFace and isAppearanceItem(targetFace) and realHead then
            cloned[targetFace] = true
            disguisedItems[targetFace] = true
            targetFace.Parent = realHead
        end

    end

    local function destroyInstance(instance: Instance?): ()
        if instance then
            pcall(instance.Destroy, instance)
        end
    end

    local function applyCharacterDisguise(
        token: number,
        character: Model,
        humanoid: Humanoid,
        userId: number
    ): ()
        local description: any, fetchError: string? = getUserDescription(userId)
        if not description then
            if stillCurrent(token, character) then
                notify("Could not load that avatar: " .. tostring(fetchError))
            end
            return
        end
        if not stillCurrent(token, character) then
            destroyInstance(description)
            return
        end

        local current: AppearanceSnapshot = ensureSnapshot(character, humanoid)
        restoreOriginalAppearance(character, humanoid)
        setDescriptionScales(description, current)

        local oldArchivable: boolean = character.Archivable
        character.Archivable = true
        local cloneOk: boolean, cloneResult: any = pcall(function()
            return character:Clone()
        end)
        character.Archivable = oldArchivable
        if not cloneOk or not cloneResult then
            destroyInstance(description)
            notify("Could not stage the disguise character.")
            return
        end

        local clone: Model = cloneResult :: Model
        local parentOk: boolean = pcall(function()
            clone.Parent = game
        end)
        if not parentOk then
            destroyInstance(description)
            destroyInstance(clone)
            notify("Could not stage the disguise character in this client.")
            return
        end

        local cloneHumanoid: Humanoid? = clone:FindFirstChildOfClass("Humanoid")
        if not cloneHumanoid then
            destroyInstance(description)
            destroyInstance(clone)
            notify("The staged character has no Humanoid.")
            return
        end

        local applied: boolean, applyError: string? =
            applyDescriptionToHumanoid(cloneHumanoid, description)
        if not applied then
            destroyInstance(description)
            destroyInstance(clone)
            notify("Could not apply the avatar description: " .. tostring(applyError))
            return
        end
        if not stillCurrent(token, character) then
            destroyInstance(description)
            destroyInstance(clone)
            return
        end

        targetEmotes, targetEquippedEmotes = readDescriptionEmotes(description)
        local emoteWarning: string? = nil
        if targetEmotes and targetEquippedEmotes then
            local emotesApplied: boolean, emoteError: string? = setHumanoidEmotes(
                humanoid,
                targetEmotes,
                targetEquippedEmotes
            )
            if emotesApplied then
                emotesAppliedToHumanoid = true
                refreshMeshPartSnapshot(character, current)
            else
                emoteWarning = tostring(emoteError)

                local rolledBack: boolean = setHumanoidEmotes(
                    humanoid,
                    current.emotes,
                    current.equippedEmotes
                )
                if not rolledBack then
                    emotesAppliedToHumanoid = true
                    emoteWarning ..= " The original emotes could not be restored yet."
                end
            end
        else
            emoteWarning = "The target avatar description did not expose emotes."
        end
        if not stillCurrent(token, character) then
            if emotesAppliedToHumanoid then
                local rolledBack: boolean = setHumanoidEmotes(
                    humanoid,
                    current.emotes,
                    current.equippedEmotes
                )
                if rolledBack then
                    emotesAppliedToHumanoid = false
                end
            end
            destroyInstance(description)
            destroyInstance(clone)
            return
        end

        local movementAnimationCount: number = 0
        if settings.useTargetMovementAnimations then
            movementAnimationCount = copyTargetMovementAnimations(
                character,
                humanoid,
                description
            )
            if not stillCurrent(token, character) then
                destroyInstance(description)
                destroyInstance(clone)
                return
            end
        end

        installAppearanceFilter(character)
        restoring = true
        local oldItems: {Instance} = {}
        for _, obj: Instance in ipairs(character:GetDescendants()) do
            if isAppearanceItem(obj) then
                table.insert(oldItems, obj)
            end
        end
        for _, obj: Instance in ipairs(oldItems) do
            pcall(obj.Destroy, obj)
        end
        restoring = false

        local copied: boolean, copyError: any = pcall(function()
            copyCharacterAppearance(character, clone)
        end)
        destroyInstance(description)
        destroyInstance(clone)
        if not copied then
            notify("The avatar was loaded, but some appearance parts could not be copied: "
                .. tostring(copyError))
            return
        end
        if stillCurrent(token, character) then
            activeCard:SetStatus("Character")
            local emoteCount: number = 0
            if type(targetEmotes) == "table" then
                for _ in pairs(targetEmotes) do
                    emoteCount += 1
                end
            end
            local message: string = "Avatar disguise applied; live body-part dimensions were left unchanged. "
            if emoteWarning then
                message ..= "Emotes could not be applied: " .. emoteWarning
            elseif emoteCount > 0 then
                message ..= tostring(emoteCount)
                    .. " target emote(s) copied; open the Roblox emote menu."
            else
                message ..= "The target description returned no emotes."
            end
            if settings.useTargetMovementAnimations then
                if movementAnimationCount > 0 then
                    message ..= " Copied " .. tostring(movementAnimationCount)
                        .. " target movement animation slot(s)."
                else
                    message ..= " No target movement animation IDs were available."
                end
            end
            notify(message)
        end
    end

    local function getService(name: string): any
        local supplied: any = host[name]
        if supplied then
            return supplied
        end
        local ok: boolean, result: any = pcall(function()
            return (game :: any):GetService(name)
        end)
        return if ok then result else nil
    end

    local function getBundleItems(
        bundleId: number,
        productInfo: any
    ): ({any}?, string?)
        local directItems: any = productInfo.Items or productInfo.items
        local hasDirectItems: boolean = type(directItems) == "table"
            and #directItems > 0
        local directType: string = tostring(productInfo.BundleType or "")
        if hasDirectItems and directType ~= "" then
            return directItems, directType
        end

        for _, serviceName: string in ipairs({"AssetService", "AvatarEditorService"}) do
            local service: any = getService(serviceName)
            local method: any = service and service.GetBundleDetailsAsync
            if type(method) == "function" then
                local ok: boolean, details: any = pcall(method, service, bundleId)
                if ok and type(details) == "table" then
                    local items: any = details.Items or details.items
                    local bundleType: string = tostring(
                        details.BundleType or directType
                    )
                    if bundleType ~= ""
                        and type(items) == "table"
                        and #items > 0 then
                        return items, bundleType
                    end
                    if bundleType ~= "" and hasDirectItems then
                        return directItems, bundleType
                    end
                end
            end
        end
        if hasDirectItems then
            return directItems, directType
        end
        return nil, nil
    end

    local function getAnimationType(itemName: string): string
        local normalized: string = string.lower(itemName)
            :gsub("%s*animations?%s*$", "")
            :gsub("%s+", "")
        local aliases: {[string]: string} = {
            pose = "idle",
            idling = "idle",
            walking = "walk",
            running = "run",
            jumping = "jump",
            falling = "fall",
            climbing = "climb",
            swimming = "swim",
        }
        return aliases[normalized] or normalized
    end

    local function applyAnimationBundle(
        token: number,
        character: Model,
        humanoid: Humanoid,
        bundleId: number
    ): ()
        local items: {any}?, rawBundleType: string? = getBundleItems(
            bundleId,
            {}
        )
        local productInfoError: string? = nil
        if not items or rawBundleType == nil or rawBundleType == "" then
            if not stillCurrent(token, character) then
                return
            end
            local infoOk: boolean, productInfo: any = pcall(function()
                return MarketplaceService:GetProductInfo(
                    bundleId,
                    Enum.InfoType.Bundle
                )
            end)
            if not stillCurrent(token, character) then
                return
            end
            if infoOk and type(productInfo) == "table" then
                local fallbackItems: {any}?, fallbackBundleType: string? =
                    getBundleItems(bundleId, productInfo)
                if fallbackItems then
                    items = fallbackItems
                end
                if fallbackBundleType and fallbackBundleType ~= "" then
                    rawBundleType = fallbackBundleType
                end
            else
                productInfoError = tostring(productInfo)
            end
        end
        if not stillCurrent(token, character) then
            return
        end
        if not items then
            local detail: string = productInfoError
                and (" " .. productInfoError)
                or ""
            notify("Could not read the bundle's animation items." .. detail)
            return
        end
        local bundleType: string = string.lower(tostring(rawBundleType or ""))
        if bundleType == "" then
            notify("This client could not verify the bundle type.")
            return
        end
        if not string.find(bundleType, "animation", 1, true) then
            notify("That ID is not an avatar animation bundle.")
            return
        end

        local current: AppearanceSnapshot = ensureSnapshot(character, humanoid)
        restoreOriginalAppearance(character, humanoid)
        stopAppearanceFilter()

        local animate: Instance? = character:FindFirstChild("Animate")
        if not animate then
            notify("This character has no Animate script to update.")
            return
        end

        local changedCount: number = 0
        for _, item: any in ipairs(items) do
            if not stillCurrent(token, character) then
                return
            end
            local itemName: string = tostring(item.Name or item.name or "")
            local itemId: number? = tonumber(item.Id or item.AssetId or item.id)
            local itemType: string = getAnimationType(itemName)
            local targetCategory: Instance? = animate:FindFirstChild(itemType)
            if itemId and targetCategory then
                local objectsOk: boolean, objects: any = pcall(function()
                    return (game :: any):GetObjects(
                        "rbxassetid://" .. tostring(itemId)
                    )
                end)
                if objectsOk and type(objects) == "table" then
                    if not stillCurrent(token, character) then
                        for _, object: Instance in ipairs(objects) do
                            destroyInstance(object)
                        end
                        return
                    end
                    local sourceAnimation: Animation? = nil
                    for _, object: Instance in ipairs(objects) do
                        if object:IsA("Animation") then
                            sourceAnimation = object
                            break
                        end
                        sourceAnimation = object:FindFirstChildWhichIsA(
                            "Animation",
                            true
                        ) :: Animation?
                        if sourceAnimation then
                            break
                        end
                    end
                    if sourceAnimation then
                        local targetAnimations: {Animation} = {}
                        if targetCategory:IsA("Animation") then
                            table.insert(targetAnimations, targetCategory)
                        end
                        for _, object: Instance in ipairs(targetCategory:GetDescendants()) do
                            if object:IsA("Animation") then
                                table.insert(targetAnimations, object)
                            end
                        end
                        for _, animation: Animation in ipairs(targetAnimations) do
                            local changed: boolean = pcall(function()
                                animation.AnimationId = sourceAnimation.AnimationId
                            end)
                            if changed then
                                changedCount += 1
                            end
                        end
                    end
                    for _, object: Instance in ipairs(objects) do
                        destroyInstance(object)
                    end
                end
            end
        end

        if changedCount == 0 then

            restoreOriginalAppearance(character, humanoid)
            notify("No compatible animations were found in that bundle.")
            return
        end

        animationOverrideApplied = true
        local animator: Animator? = humanoid:FindFirstChildOfClass("Animator")
        if animator then
            for _, track: AnimationTrack in ipairs(animator:GetPlayingAnimationTracks()) do
                pcall(track.Stop, track)
            end
        end
        restartAnimateScript(animate)
        if current.character == character and stillCurrent(token, character) then
            activeCard:SetStatus("Animation")
            notify("Animation bundle applied to " .. tostring(changedCount)
                .. " slots; Animate restarted. Original IDs return when disabled.")
        end
    end

    local function applyDisguise(): ()
        generation += 1
        local token: number = generation
        local character: Model? = LocalPlayer.Character
        local humanoid: Humanoid? = character
            and character:FindFirstChildOfClass("Humanoid")
            :: Humanoid?
        if not character or not humanoid or humanoid.Health <= 0 then
            notify("Your character is not ready yet.")
            return
        end
        local numericId: number?, idError: string? = parseId()
        if not numericId then
            notify(tostring(idError))
            return
        end

        local selectedMode: string = settings.mode
        targetEmotes = nil
        targetEquippedEmotes = nil
        task.spawn(function(): ()
            if selectedMode == "Character" then
                applyCharacterDisguise(
                    token,
                    character :: Model,
                    humanoid :: Humanoid,
                    numericId :: number
                )
            else
                applyAnimationBundle(
                    token,
                    character :: Model,
                    humanoid :: Humanoid,
                    numericId :: number
                )
            end
        end)
    end

    local function restoreAndRelease(): ()
        generation += 1
        stopAppearanceFilter()
        local character: Model? = LocalPlayer.Character
        local humanoid: Humanoid? = character
            and character:FindFirstChildOfClass("Humanoid")
            :: Humanoid?
        if character then
            restoreOriginalAppearance(character, humanoid)
        end
        destroySnapshot()
        table.clear(cloned)
        table.clear(disguisedItems)
    end

    local function sortedEmoteNames(data: any): {string}
        local names: {string} = {}
        if type(data) == "table" then
            for name: any in pairs(data) do
                if type(name) == "string" then
                    table.insert(names, name)
                end
            end
        end
        table.sort(names)
        return names
    end

    local function equippedEmoteNames(data: any): {string}
        local names: {string} = {}
        local seen: {[string]: boolean} = {}
        if type(data) == "table" then
            for key: any, entry: any in pairs(data) do
                local name: any = nil
                if type(entry) == "string" then
                    name = entry
                elseif entry == true and type(key) == "string" then
                    name = key
                elseif type(entry) == "table" then
                    name = entry.Name or entry.name or entry[1]
                end
                if type(name) == "string" and not seen[name] then
                    seen[name] = true
                    table.insert(names, name)
                end
            end
        end
        table.sort(names)
        return names
    end

    local function formatNameList(names: {string}): string
        if #names == 0 then
            return "none"
        end
        local shown: {string} = {}
        for index = 1, math.min(#names, 12) do
            table.insert(shown, names[index])
        end
        if #names > 12 then
            table.insert(shown, "+" .. tostring(#names - 12) .. " more")
        end
        return table.concat(shown, ", ")
    end

    local card: any
    card = framework.Categories.Other:CreateModule({
        Name = "Disguise",
        Category = "Other",
        ConfigKey = "Universal.Disguise",
        Order = 26,
        Tooltip = "Copies a target avatar's cosmetics and emotes; optionally copies its movement animations. Animation mode changes local motion IDs only, not the visible avatar.",
        Function = function(enabled: boolean): ()
            if enabled then
                card:SetStatus(settings.mode)
                card:Clean(LocalPlayer.CharacterAdded:Connect(function(): ()
                    generation += 1
                    stopAppearanceFilter()
                    destroySnapshot()
                    task.wait(0.5)
                    if card.Enabled then
                        applyDisguise()
                    end
                end))
                applyDisguise()
            else
                restoreAndRelease()
                card:SetStatus(nil)
            end
        end,
    })

    card:CreateDropdown({
        Name = "Mode",
        List = {"Character", "Animation"},
        Index = 1,
        Function = function(value: string): ()
            settings.mode = value
            card:SetStatus(value)
            if card.Enabled then
                if value == "Animation" then
                    targetEmotes = nil
                    targetEquippedEmotes = nil
                    local character: Model? = LocalPlayer.Character
                    local humanoid: Humanoid? = character
                        and character:FindFirstChildOfClass("Humanoid")
                        :: Humanoid?
                    if character then
                        restoreOriginalAppearance(character, humanoid)
                    end
                    stopAppearanceFilter()
                end
                applyDisguise()
            end
        end,
        Tooltip = "Character: visible avatar cosmetics and emotes from a user ID. Animation: movement animation IDs from a bundle; it does not render the target character.",
    })

    card:CreateButton({
        Name = "Use target movement animations",
        Function = function(): ()
            local numericId: number?, idError: string? = parseId()
            if not numericId then
                notify(tostring(idError))
                return
            end
            settings.useTargetMovementAnimations = true
            applyTargetMovementAnimationsToCharacter(numericId)
        end,
        Tooltip = "Downloads and applies the target user's movement animations (idle, walk, run, jump, climb, fall, swim) to your character. Original IDs return when Disguise is turned off.",
    })

    card:CreateTextBox({
        Name = "Target ID",
        Default = settings.id,
        Function = function(value: string): ()
            local trimmed: string = tostring(value or "")
                :gsub("^%s+", "")
                :gsub("%s+$", "")
            if trimmed == "" then
                notify("Enter a user ID or animation bundle ID first.")
                return
            end
            settings.id = trimmed
            if card.Enabled then
                applyDisguise()
            end
        end,
        Tooltip = "Positive integer user ID (Character) or avatar-animation bundle ID (Animation).",
    })

    card:CreateButton({
        Name = "Show target emotes",
        Function = function(): ()
            if type(targetEmotes) ~= "table" then
                notify("Load a user ID in Character mode before listing emotes.")
                return
            end
            local names: {string} = sortedEmoteNames(targetEmotes)
            local equipped: {string} = equippedEmoteNames(targetEquippedEmotes)
            notify(string.format(
                "Target emotes (%d): %s | Equipped (%d): %s",
                #names,
                formatNameList(names),
                #equipped,
                formatNameList(equipped)
            ))
        end,
        Tooltip = "Lists the emotes and equipped emote slots returned for the target user ID.",
    })

    activeCard = card
    Module.Initialized = true
    return card
end

function Module.destroy(): ()
    if activeCard then
        if activeCard.Enabled then
            pcall(activeCard.Toggle, activeCard, false)
        end
        activeCard = nil
    end
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Other/GameLearning.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "GameLearning",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeController: any = nil
local unsubscribeBridge: any = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local product: any = host.PRODUCT
    local notify: any = host.notify
    local createUniversalFeature: any = host.createUniversalFeature
    local addNumberOption: any = host.addNumberOption
    local addToggleOption: any = host.addToggleOption
    local addActionOption: any = host.addActionOption
    local addInformationOption: any = host.addInformationOption
    local TaskManager: any = host.TaskManager
    local LocalPlayer: any = host.LocalPlayer
    local PlayersService: any = host.Players or (game :: any):GetService("Players")
    local Stats: any = host.Stats or (game :: any):GetService("Stats")
    local httpService: any = host.HttpService or (game :: any):GetService("HttpService")
    local UserInputService: any = host.UserInputService or (game :: any):GetService("UserInputService")

    local isMM2: boolean = game.PlaceId == 142823291
    local gameBridge: any = context.services and
        context.services.gameBridge

    local controllerFactory = (function(): any
        type SceneEntry = {
            player: string,
            dist: number,
            angleDeg: number,
            los: string,
            root: {number},
            headOffset: number?,
            torso: {number}?,
        }
        type ShotRecord = {
            shotId: string?,
            sessionId: string?,
            buildStamp: string?,
            settings: any?,
            eventSource: string?,
            evidence: any?,
            deathObservation: any?,
            id: number,
            t: number,
            clockAt: number,
            pingMs: number,
            tool: string,
            kind: string?,
            origin: {number},
            aim: {number},
            scene: {SceneEntry},
            outcome: {[string]: any}?,
            silentSpawn: {variant: string, offset: number?}?,

            target: string?,
        }
        type MovementRecord = {
            t: number,
            kind: string,
            magnitude: number,
            detail: {[string]: any}?,
        }

        local tuning: any = {
            logShots = true,
            logMovement = true,
            logHitboxes = true,
            killWindowSeconds = 4,
            sceneRadius = 250,
            maxEvents = 300,
        }

        local executorEnvironment: {[string]: any} = getfenv() :: any
        local mouse: Mouse = LocalPlayer:GetMouse()
        local outputRoot: string = product.storageFolder
        local outputTelemetry: string = outputRoot .. "/Telemetry"
        local outputFolder: string = outputTelemetry .. "/Universal"
        local outputPath: string = outputFolder
            .. "/Place_"
            .. tostring(game.PlaceId)
            .. "_Game_Learning.json"
        local runtime: any = {
            enabled = false,
            sessionId = httpService:GenerateGUID(false),
            startedAt = os.time(),
            startedClock = os.clock(),
            buildStamp = tostring(host.SOURCE_STAMP or "unknown"),
            historyLoaded = false,
            persistenceBlocked = false,
            historyBackup = nil,
            shots = {} :: {ShotRecord},
            movements = {} :: {MovementRecord},
            hits = {} :: {{[string]: any}},
            aggregates = {
                shots = 0,
                confirmations = 0,
                targetHits = 0,
                projectileObservations = 0,
                unconfirmed = 0,
                deathAssociations = 0,
                kills = 0,
                cleanKills = 0,
                wallshotKills = 0,
                longrangeKills = 0,
                misses = 0,
                unattributedDeaths = 0,
                teleports = 0,
                speedSpikes = 0,
                longAirtime = 0,
                hitboxAnomalies = 0,
                hitboxKills = 0,
                farthestKill = 0,
            },
            shotCounter = 0,
            spawnShots = {} :: {[string]: number},
            spawnKills = {} :: {[string]: number},
            lastAuthoredAt = 0,
            saveDirty = false,
            revision = 0,
            connections = {} :: {RBXScriptConnection},
            observedTools = setmetatable({}, {__mode = "k"}) :: {[Tool]: boolean},
            watchedPlayers = setmetatable({}, {__mode = "k"}) :: {[Player]: boolean},
            anomalyCooldown = setmetatable({}, {__mode = "k"}) :: {[Player]: number},
            movementTask = nil :: any,
            hitboxTask = nil :: any,
            autosaveTask = nil :: any,
        }
        local controller: any
        local saveSnapshot: (reason: string) -> boolean

        controller = {} :: any
        controller.tuning = tuning

        local function vectorArray(value: Vector3): {number}
            return {value.X, value.Y, value.Z}
        end

        local function round1(value: number): number
            return math.floor(value * 10 + 0.5) / 10
        end

        local function round2(value: number): number
            return math.floor(value * 100 + 0.5) / 100
        end

        local function clampTrim(list: {any}, cap: number): ()
            while #list > cap do
                table.remove(list, 1)
            end
        end

        local function getPingMilliseconds(): number
            local pingMs: number = 0
            pcall(function(): ()
                local network: Instance? = Stats:FindFirstChild("Network")
                local serverItems: Instance? = network
                    and network:FindFirstChild("ServerStatsItem")
                local pingItem: any = serverItems
                    and serverItems:FindFirstChild("Data Ping")
                if pingItem and type(pingItem.GetValue) == "function" then
                    pingMs = tonumber(pingItem:GetValue()) or 0
                end
            end)
            return pingMs
        end

        local function findSceneEntry(
            shot: ShotRecord,
            player: Player
        ): SceneEntry?
            for _, entry: SceneEntry in ipairs(shot.scene) do
                if entry.player == player.Name then
                    return entry
                end
            end
            return nil
        end

        local function buildScene(
            shotOrigin: Vector3,
            aimDir: Vector3?
        ): {SceneEntry}
            local scene: {SceneEntry} = {}
            local character: Model? = LocalPlayer.Character
            local raycastParams: RaycastParams = RaycastParams.new()
            raycastParams.FilterType = Enum.RaycastFilterType.Exclude
            raycastParams.IgnoreWater = true
            raycastParams.FilterDescendantsInstances = {character :: Instance}
            for _, player: Player in ipairs(PlayersService:GetPlayers()) do
                if player ~= LocalPlayer then
                    local targetCharacter: Model? = player.Character
                    local targetRoot: BasePart? = targetCharacter
                        and targetCharacter:FindFirstChild("HumanoidRootPart")
                        :: BasePart?
                    local humanoid: Humanoid? = targetCharacter
                        and targetCharacter:FindFirstChildOfClass("Humanoid")
                        :: Humanoid?
                    if targetRoot
                        and humanoid
                        and humanoid.Health > 0 then
                        local toPlayer: Vector3 = targetRoot.Position - shotOrigin
                        local dist: number = toPlayer.Magnitude
                        if dist <= tuning.sceneRadius and dist > 0.01 then
                            local angleDeg: number = 0
                            if aimDir then
                                angleDeg = math.deg(
                                    math.acos(math.clamp(
                                        toPlayer.Unit:Dot(aimDir),
                                        -1,
                                        1
                                    ))
                                )
                            end
                            local hit: RaycastResult? = workspace:Raycast(
                                shotOrigin,
                                toPlayer,
                                raycastParams
                            )
                            local los: string = "clear"
                            if hit
                                and not hit.Instance:IsDescendantOf(
                                    targetCharacter :: Instance
                                ) then
                                los = "blocked"
                            end
                            local head: BasePart? = targetCharacter
                                and targetCharacter:FindFirstChild("Head")
                                :: BasePart?
                            local torso: BasePart? = targetCharacter
                                and targetCharacter:FindFirstChild("UpperTorso")
                                :: BasePart?
                            table.insert(scene, {
                                player = player.Name,
                                dist = round1(dist),
                                angleDeg = aimDir and round1(angleDeg) or nil,
                                los = los,
                                root = vectorArray(targetRoot.Position),
                                headOffset = head
                                    and round2(
                                        (head.Position
                                            - targetRoot.Position)
                                            .Magnitude
                                    )
                                    or nil,
                                torso = torso
                                    and {
                                        round2(torso.Size.X),
                                        round2(torso.Size.Y),
                                        round2(torso.Size.Z),
                                    }
                                    or nil,
                            })
                        end
                    end
                end
            end
            return scene
        end

        local function finalizeShot(
            shot: ShotRecord,
            explicitVariant: string?,
            explicitOffset: number?
        ): ()

            local variant: string? = explicitVariant
            local variantOffset: number? = explicitOffset
            if not isMM2 and not variant
                and gameBridge
                and type(gameBridge.silentShot) == "function" then
                local okInfo: boolean, info: any = pcall(gameBridge.silentShot)
                if okInfo
                    and type(info) == "table"
                    and info.variant ~= nil
                    and os.clock() - (tonumber(info.at) or 0) < 2 then
                    variant = info.variant
                    variantOffset = tonumber(info.offset)
                end
            end
            if variant then
                shot.silentSpawn = {variant = variant, offset = variantOffset}
                runtime.spawnShots[variant] = (runtime.spawnShots[variant] or 0) + 1
            end
            table.insert(runtime.shots, shot)
            clampTrim(runtime.shots, tuning.maxEvents)
            runtime.aggregates.shots += 1
            runtime.revision += 1
            runtime.saveDirty = true

            local timerSession = runtime.sessionId
            task.delay(tuning.killWindowSeconds + 0.5, function(): ()
                if timerSession ~= runtime.sessionId then return end
                if shot.outcome ~= nil then
                    return
                end
                shot.outcome = {verdict = "unconfirmed", evidence = "observation-timeout"}
                runtime.aggregates.unconfirmed += 1
                runtime.revision += 1
                runtime.saveDirty = true
            end)
        end

        local function recordShot(tool: Tool): ()
            -- MM2's core is the sole weapon observer; no mouse/Tool double count.
            if isMM2 then return end
            local name = string.lower(tool.Name)
            if not string.find(name, "gun", 1, true) and not string.find(name, "knife", 1, true)
                and not tool:FindFirstChild("Shoot") then return end
            runtime.lastAuthoredAt = os.clock()
            local character: Model? = LocalPlayer.Character
            local root: BasePart? = character
                and character:FindFirstChild("HumanoidRootPart")
                :: BasePart?
            local origin: Vector3? = root and root.Position or nil
            if not origin then
                return
            end
            local handle: BasePart? = tool:FindFirstChild("Handle") :: BasePart?
            local shotOrigin: Vector3 = handle and handle.Position or origin
            local aim: Vector3 = Vector3.zero
            pcall(function(): ()
                aim = mouse.Hit.Position
            end)
            local aimDelta: Vector3 = aim - shotOrigin
            local aimDir: Vector3? = aimDelta.Magnitude > 0.01 and aimDelta.Unit or nil
            runtime.shotCounter += 1
            local shot: ShotRecord = {
                sessionId = runtime.sessionId,
                buildStamp = runtime.buildStamp,
                id = runtime.shotCounter,
                t = os.time(),
                clockAt = os.clock(),
                pingMs = getPingMilliseconds(),
                tool = tool.Name,
                origin = vectorArray(shotOrigin),
                aim = vectorArray(aim),
                scene = buildScene(shotOrigin, aimDir),
                outcome = nil,
                silentSpawn = nil,
            }
            finalizeShot(shot, nil)
        end

        local function recordAuthoredShot(info: any): ()
            if type(info) ~= "table" then
                return
            end
            if info.kind == "knifeActivation" then return end -- activation is not a throw/stab
            if type(info.shotId) == "string" then
                for _, previous in ipairs(runtime.shots) do
                    if previous.shotId == info.shotId then return end
                end
            end
            local character: Model? = LocalPlayer.Character
            local root: BasePart? = character
                and character:FindFirstChild("HumanoidRootPart")
                :: BasePart?
            local shotOrigin: Vector3? =
                typeof(info.originPos) == "Vector3" and info.originPos or root
                    and root.Position
                    or nil
            if not shotOrigin then
                return
            end
            local aim: Vector3 =
                typeof(info.aimPos) == "Vector3" and info.aimPos or Vector3.zero
            if aim == Vector3.zero then
                pcall(function(): ()
                    aim = mouse.Hit.Position
                end)
            end
            local aimDelta: Vector3 = aim - shotOrigin
            local aimDir: Vector3? = aimDelta.Magnitude > 0.01 and aimDelta.Unit or nil
            runtime.lastAuthoredAt = os.clock()
            runtime.shotCounter += 1
            local shot: ShotRecord = {
                shotId = info.shotId,
                sessionId = info.sessionId or runtime.sessionId,
                buildStamp = info.buildStamp or runtime.buildStamp,
                settings = info.settings,
                eventSource = info.eventSource,
                id = runtime.shotCounter,
                t = os.time(),
                clockAt = os.clock(),
                pingMs = getPingMilliseconds(),
                tool = tostring(info.toolName or "Unknown"),
                kind = info.kind,
                origin = vectorArray(shotOrigin),
                aim = vectorArray(aim),
                scene = buildScene(shotOrigin, aimDir),
                outcome = nil,
                silentSpawn = nil,
                target = type(info.targetName) == "string" and info.targetName
                    or (typeof(info.target) == "Instance" and info.target.Name or nil),
            }
            finalizeShot(shot, info.variant, tonumber(info.offset))
        end

        local function recordConfirmation(info: any): ()
            if type(info) ~= "table" or type(info.shotId) ~= "string" then return end
            for index = #runtime.shots, 1, -1 do
                local shot = runtime.shots[index]
                if shot.shotId ~= info.shotId then continue end
                if shot.evidence then return end -- repeated notifications are idempotent
                if shot.outcome and shot.outcome.verdict == "unconfirmed" then
                    runtime.aggregates.unconfirmed = math.max(0, runtime.aggregates.unconfirmed - 1)
                end
                shot.evidence = {source = info.evidence, hitTarget = info.hitTarget,
                    latencyMs = info.latencyMs, targetName = info.targetName}
                local verdict = "projectile-observed"
                if info.kind == "gun" then
                    verdict = info.hitTarget == true and "target-hit" or "shot-confirmed"
                    if info.hitTarget == true then runtime.aggregates.targetHits += 1 end
                else
                    runtime.aggregates.projectileObservations += 1
                end
                runtime.aggregates.confirmations += 1
                shot.outcome = {verdict = verdict, evidence = info.evidence}
                runtime.revision += 1
                runtime.saveDirty = true
                return
            end
        end

        local function recordDeath(player: Player): ()
            -- Temporal association only: another player may have caused the death.
            local attributed = false
            for index = #runtime.shots, 1, -1 do
                local shot = runtime.shots[index]
                if os.clock() - shot.clockAt > tuning.killWindowSeconds then break end
                if shot.target ~= player.Name or shot.deathObservation then continue end
                shot.deathObservation = {player = player.Name,
                    delayMs = math.floor((os.clock() - shot.clockAt) * 1000),
                    evidence = "temporal-association-only"}
                runtime.aggregates.deathAssociations += 1
                table.insert(runtime.hits, {t = os.time(), shotId = shot.shotId,
                    player = player.Name, verdict = "death-associated-not-attributed"})
                clampTrim(runtime.hits, tuning.maxEvents)
                attributed = true
                break
            end
            if not attributed then runtime.aggregates.unattributedDeaths += 1 end
            runtime.revision += 1
            runtime.saveDirty = true
        end

        local function watchPlayer(player: Player): ()
            if runtime.watchedPlayers[player] then
                return
            end
            runtime.watchedPlayers[player] = true
            local function watchCharacter(character: Model): ()
                local humanoid: Humanoid? = character:FindFirstChildOfClass(
                    "Humanoid"
                ) :: Humanoid?
                if humanoid then
                    table.insert(
                        runtime.connections,
                        humanoid.Died:Connect(function(): ()
                            if runtime.enabled then
                                recordDeath(player)
                            end
                        end)
                    )
                end
            end
            if player.Character then
                watchCharacter(player.Character)
            end
            table.insert(
                runtime.connections,
                player.CharacterAdded:Connect(watchCharacter)
            )
        end

        local function recordMovement(
            kind: string,
            magnitude: number,
            detail: {[string]: any}?
        ): ()
            table.insert(runtime.movements, {
                t = os.time(),
                kind = kind,
                magnitude = round1(magnitude),
                detail = detail,
            } :: MovementRecord)
            clampTrim(runtime.movements, tuning.maxEvents)
            runtime.revision += 1
            runtime.saveDirty = true
        end

        local function observeTool(tool: Tool): ()
            if isMM2 then return end
            if runtime.observedTools[tool] then
                return
            end
            runtime.observedTools[tool] = true
            table.insert(
                runtime.connections,
                tool.Activated:Connect(function(): ()
                    if not (runtime.enabled and tuning.logShots) then
                        return
                    end

                    if os.clock() - runtime.lastAuthoredAt < 0.35 then
                        return
                    end
                    recordShot(tool)
                end)
            )
        end

        local function observeContainer(container: Instance?): ()
            if not container then
                return
            end
            for _, child: Instance in ipairs(container:GetChildren()) do
                if child:IsA("Tool") then
                    observeTool(child :: Tool)
                end
            end
            table.insert(
                runtime.connections,
                container.ChildAdded:Connect(function(child: Instance): ()
                    if child:IsA("Tool") then
                        observeTool(child :: Tool)
                    end
                end)
            )
        end

        local function startMovementProbe(): ()
            if runtime.movementTask then
                return
            end
            local lastPosition: Vector3? = nil
            local lastAt: number = 0
            local speedSince: number? = nil
            local airSince: number? = nil
            local airConsumed: boolean = false
            local movementElapsed: number = 0
            runtime.movementTask = TaskManager:Connect(function(deltaTime: number): ()
                movementElapsed += deltaTime
                if movementElapsed < 0.05 then
                    return
                end
                movementElapsed = 0
                if not (runtime.enabled and tuning.logMovement) then
                    lastPosition = nil
                    lastAt = 0
                    speedSince = nil
                    airSince = nil
                    airConsumed = false
                    return
                end
                local character: Model? = LocalPlayer.Character
                local root: BasePart? = character
                    and character:FindFirstChild("HumanoidRootPart")
                    :: BasePart?
                local humanoid: Humanoid? = character
                    and character:FindFirstChildOfClass("Humanoid")
                    :: Humanoid?
                if not root or not humanoid then
                    lastPosition = nil
                    lastAt = 0
                    return
                end
                local now: number = os.clock()
                local position: Vector3 = root.Position
                if lastPosition and lastAt > 0 then
                    local elapsed: number = now - lastAt
                    if elapsed >= 0.02 then
                        local jumped: number = (position - lastPosition).Magnitude

                        if jumped > 25 and elapsed < 0.15 and jumped < 3000 then
                            recordMovement("teleport", jumped, {
                                from = vectorArray(lastPosition),
                                to = vectorArray(position),
                            })
                            runtime.aggregates.teleports += 1
                        end
                        local speed: number =
                            root.AssemblyLinearVelocity.Magnitude
                        if speed > 90 then
                            if speedSince == nil then
                                speedSince = now
                            elseif now - speedSince > 0.3 then
                                recordMovement("speed", speed)
                                runtime.aggregates.speedSpikes += 1
                                speedSince = nil
                            end
                        else
                            speedSince = nil
                        end
                    end
                end
                if humanoid.FloorMaterial == Enum.Material.Air then
                    if airSince == nil then
                        airSince = now
                    end
                    if not airConsumed and now - airSince > 2.5 then
                        recordMovement(
                            "airtime",
                            math.floor((now - airSince) * 10) / 10
                        )
                        runtime.aggregates.longAirtime += 1
                        airConsumed = true
                    end
                else
                    airSince = nil
                    airConsumed = false
                end
                lastPosition = position
                lastAt = now
            end)
        end

        local function startHitboxProbe(): ()
            if runtime.hitboxTask then
                return
            end
            local hitboxElapsed: number = 0
            runtime.hitboxTask = TaskManager:Connect(function(deltaTime: number): ()
                hitboxElapsed += deltaTime
                if hitboxElapsed < 1 then
                    return
                end
                hitboxElapsed = 0
                if not (runtime.enabled and tuning.logHitboxes) then
                    return
                end
                for _, player: Player in ipairs(PlayersService:GetPlayers()) do
                    if player ~= LocalPlayer then
                        local character: Model? = player.Character
                        local root: BasePart? = character
                            and character:FindFirstChild("HumanoidRootPart")
                            :: BasePart?
                        local head: BasePart? = character
                            and character:FindFirstChild("Head")
                            :: BasePart?
                        local torso: BasePart? = character
                            and character:FindFirstChild("UpperTorso")
                            :: BasePart?
                        local anomaly: string? = nil
                        if root and head then
                            local offset: number =
                                (head.Position - root.Position).Magnitude
                            if offset > 3.2 or offset < 0.9 then
                                anomaly = "headOffset"
                            end
                        end
                        if not anomaly and root and torso then
                            local torsoY: number = torso.Size.Y
                            if torsoY > 2.6 or torsoY < 0.7 then
                                anomaly = "torsoSize"
                            end
                        end
                        if anomaly then
                            local lastFlag: number? = runtime.anomalyCooldown[player]
                            if not lastFlag or os.clock() - lastFlag > 5 then
                                runtime.anomalyCooldown[player] = os.clock()
                                runtime.aggregates.hitboxAnomalies += 1
                                runtime.revision += 1
                                runtime.saveDirty = true
                            end
                        end
                    end
                end
            end)
        end

        local function buildInsights(): {string}
            local agg = runtime.aggregates
            return {
                string.format("%d attempts; %d observations confirmed; %d intended-target gun impacts.",
                    agg.shots, agg.confirmations, agg.targetHits),
                string.format("%d projectile observations are NOT impact/damage confirmations.", agg.projectileObservations),
                string.format("%d attempts unconfirmed; absence of evidence is NOT a miss.", agg.unconfirmed),
                string.format("%d temporally associated deaths do NOT establish who caused them.", agg.deathAssociations),
                "Local movement/geometry observations do not establish server tolerance or successful hitbox manipulation.",
            }
        end

        local MAX_STORED_EVENTS: number = 3000

        local function loadStoredLogs(): ()
            if runtime.historyLoaded then return end
            runtime.historyLoaded = true
            if type(executorEnvironment.readfile) ~= "function" then
                runtime.persistenceBlocked = true
                return
            end
            local ok, raw = pcall(executorEnvironment.readfile, outputPath)
            if not ok then
                local okExists, exists = pcall(function() return executorEnvironment.isfile(outputPath) end)
                runtime.persistenceBlocked = not (okExists and exists == false)
                return
            end
            if type(raw) ~= "string" then runtime.persistenceBlocked = true; return end
            if #raw == 0 then return end
            local backup = outputPath .. ".before-" .. runtime.sessionId .. ".json"
            local okBackup = type(executorEnvironment.writefile) == "function"
                and pcall(executorEnvironment.writefile, backup, raw)
            local okVerify, backedUp = pcall(executorEnvironment.readfile, backup)
            if not okBackup or not okVerify or backedUp ~= raw then
                runtime.persistenceBlocked = true
                notify("Game Learning: history backup failed; existing file protected")
                return
            end
            runtime.historyBackup = backup
            -- Retained logs stay in the backup, never in this session's counters.
        end

        saveSnapshot = function(reason: string?, silent: boolean?): boolean
            if runtime.persistenceBlocked then return false end
            loadStoredLogs()
            if runtime.persistenceBlocked then return false end
            if type(executorEnvironment.writefile) ~= "function" then
                return false
            end
            if type(executorEnvironment.makefolder) == "function" then
                pcall(executorEnvironment.makefolder, outputRoot)
                pcall(executorEnvironment.makefolder, outputTelemetry)
                pcall(executorEnvironment.makefolder, outputFolder)
            end
            while #runtime.shots > MAX_STORED_EVENTS do
                table.remove(runtime.shots, 1)
            end
            while #runtime.movements > MAX_STORED_EVENTS do
                table.remove(runtime.movements, 1)
            end
            while #runtime.hits > MAX_STORED_EVENTS do
                table.remove(runtime.hits, 1)
            end
            local savedRevision = runtime.revision
            local payload: {[string]: any} = {
                schema = 2,
                buildStamp = runtime.buildStamp,
                sessionId = runtime.sessionId,
                historyBackup = runtime.historyBackup,
                kind = "game-learning-log",
                outcomeContract = "attempts != confirmations != impacts; kills not measured; legacy kill/miss fields are unused",
                placeId = game.PlaceId,
                savedAt = os.time(),
                savedReason = reason or "manual",
                session = {
                    startedAt = runtime.startedAt,
                    countersScope = "this-session-only",
                    uptimeSeconds = math.floor(os.clock() - runtime.startedClock),
                },
                aggregates = runtime.aggregates,
                insights = buildInsights(),
                spawnShots = runtime.spawnShots,
                spawnKills = runtime.spawnKills,
                shots = runtime.shots,
                movements = runtime.movements,
                hits = runtime.hits,
            }
            local okEncode: boolean, encoded: any = pcall(
                httpService.JSONEncode,
                httpService,
                payload
            )
            if not okEncode or type(encoded) ~= "string" then
                return false
            end
            local okWrite: boolean = pcall(
                executorEnvironment.writefile,
                outputPath,
                encoded
            )
            if okWrite then
                runtime.saveDirty = runtime.revision ~= savedRevision
                if not silent then
                    notify("Game Learning: saved " .. outputPath)
                end
            end
            return okWrite
        end
        local function status(): string
            local agg = runtime.aggregates
            return string.format("%d attempts · %d confirmed · %d target hits · %d unconfirmed",
                agg.shots, agg.confirmations, agg.targetHits, agg.unconfirmed)
        end

        local function deleteLogs(): boolean
            for key in pairs(runtime.aggregates) do runtime.aggregates[key] = 0 end
            runtime.sessionId = httpService:GenerateGUID(false)
            runtime.startedAt = os.time()
            runtime.startedClock = os.clock()
            runtime.spawnShots = {}
            runtime.spawnKills = {}
            runtime.shots = {}
            runtime.hits = {}
            runtime.movements = {}
            runtime.shotCounter = 0
            runtime.saveDirty = false
            local deleteFile: any = executorEnvironment.delfile
            local okDelete: boolean = false
            if type(deleteFile) == "function" then
                okDelete = pcall(deleteFile, outputPath)
            elseif type(executorEnvironment.writefile) == "function" then
                okDelete = pcall(executorEnvironment.writefile, outputPath, "{}")
            end
            notify("Game Learning: history cleared")
            return okDelete
        end

        function controller:setEnabled(enabled: boolean): ()
            if runtime.enabled == enabled then
                return
            end
            if not enabled then
                runtime.enabled = false
                for _, connection: RBXScriptConnection in ipairs(
                    runtime.connections
                ) do
                    connection:Disconnect()
                end
                table.clear(runtime.connections)
                runtime.observedTools = setmetatable({}, {__mode = "k"})

                runtime.watchedPlayers = setmetatable({}, {__mode = "k"})
                if runtime.movementTask then
                    runtime.movementTask:Disconnect()
                    runtime.movementTask = nil
                end
                if runtime.hitboxTask then
                    runtime.hitboxTask:Disconnect()
                    runtime.hitboxTask = nil
                end
                if runtime.autosaveTask then
                    runtime.autosaveTask:Disconnect()
                    runtime.autosaveTask = nil
                end
                if runtime.saveDirty then

                    saveSnapshot("disabled")
                end
                return
            end
            runtime.enabled = true
            loadStoredLogs()
            startMovementProbe()
            startHitboxProbe()
            if not runtime.autosaveTask then
                local elapsed: number = 0
                runtime.autosaveTask = TaskManager:Connect(function(deltaTime: number): ()
                    elapsed += deltaTime
                    if elapsed < 15 then
                        return
                    end
                    elapsed = 0
                    if runtime.enabled and runtime.saveDirty then
                        saveSnapshot("autosave", true)
                    end
                end)
            end
            observeContainer(LocalPlayer:FindFirstChildOfClass("Backpack"))
            observeContainer(LocalPlayer.Character)
            table.insert(
                runtime.connections,
                LocalPlayer.CharacterAdded:Connect(function(character: Model): ()
                    observeContainer(character)
                end)
            )
            table.insert(
                runtime.connections,
                UserInputService.InputBegan:Connect(function(input: InputObject, gameProcessed: boolean): ()
                    if isMM2 or gameProcessed then
                        return
                    end
                    if input.UserInputType ~= Enum.UserInputType.MouseButton1
                        and input.UserInputType ~= Enum.UserInputType.Touch then
                        return
                    end
                    if not (runtime.enabled and tuning.logShots) then
                        return
                    end
                    local character: Model? = LocalPlayer.Character
                    local equippedTool: Tool? = character and character:FindFirstChildOfClass("Tool")
                    if not equippedTool then
                        return
                    end
                    if os.clock() - runtime.lastAuthoredAt < 0.35 then
                        return
                    end
                    runtime.lastAuthoredAt = os.clock()
                    recordShot(equippedTool)
                end)
            )
            for _, player: Player in ipairs(PlayersService:GetPlayers()) do
                watchPlayer(player)
            end
            table.insert(
                runtime.connections,
                PlayersService.PlayerAdded:Connect(watchPlayer)
            )
        end

        controller.save = function(_reason: string?): boolean
            loadStoredLogs() -- protect existing file even if Save is clicked before enabling
            return saveSnapshot("manual")
        end
        controller.flush = function(): boolean
            if not runtime.enabled then
                return false
            end
            return saveSnapshot("close")
        end
        controller.noteAuthoringShot = function(selfOrInfo: any, maybeInfo: any): ()
            local info: any = if type(maybeInfo) == "table" then maybeInfo else selfOrInfo
            if runtime.enabled and tuning.logShots and type(info) == "table" then
                recordAuthoredShot(info)
            end
        end
        controller.noteConfirmation = function(info: any): ()
            if runtime.enabled and tuning.logShots then recordConfirmation(info) end
        end
        controller.delete = function(): boolean
            return deleteLogs()
        end
        controller.status = status
        return controller
    end)()

    local gameLearning: any = controllerFactory

    if gameBridge and type(gameBridge.onEvent) == "function" then
        unsubscribeBridge = gameBridge.onEvent(function(eventType: string, payload: any): ()
            if eventType == "authoringShot" then
                gameLearning:noteAuthoringShot(payload)
            elseif eventType == "shotConfirmation" then
                gameLearning.noteConfirmation(payload)
            end
        end)
    end

    pcall(function(): ()
        if type((game :: any).BindToClose) == "function" then
            game:BindToClose(function(): ()
                pcall(gameLearning.flush, gameLearning)
            end)
        end
    end)

    local GameLearningFeature: any = state.metricsFeature
    if not GameLearningFeature then
        GameLearningFeature = createUniversalFeature(
            "Metrics",
            "Calibration and game-learning telemetry in one card: projectile "
                .. "analytics, client observations, motion calibration.",
            16,
            function(_enabled: boolean): () end,
            {category = true, categoryName = "Other"}
        )
        state.metricsFeature = GameLearningFeature
    end
    addToggleOption(GameLearningFeature, "Game learning observer", false, function(value: boolean): ()
        gameLearning:setEnabled(value)
    end, "Optional scene/movement evidence logger, not prediction training. Turning OFF stops probes and saves pending data.")
    addToggleOption(
        GameLearningFeature,
        "Log shots",
        gameLearning.tuning.logShots,
        function(value: boolean): ()
            gameLearning.tuning.logShots = value
        end,
        "Snapshots every player's distance, angle, line of sight and hitbox "
            .. "geometry on each shot you fire."
    )
    addToggleOption(
        GameLearningFeature,
        "Log movement",
        gameLearning.tuning.logMovement,
        function(value: boolean): ()
            gameLearning.tuning.logMovement = value
        end,
        "Tracks teleports, sustained speed spikes and long airtime on your "
            .. "character. These are local observations, not proof of server tolerance."
    )
    addToggleOption(
        GameLearningFeature,
        "Log hitboxes",
        gameLearning.tuning.logHitboxes,
        function(value: boolean): ()
            gameLearning.tuning.logHitboxes = value
        end,
        "Samples other players' head offset and torso size once a second and "
            .. "flags abnormal geometry."
    )
    addNumberOption(
        GameLearningFeature,
        "Observation window",
        gameLearning.tuning.killWindowSeconds,
        1,
        10,
        function(value: number): ()
            gameLearning.tuning.killWindowSeconds = value
        end,
        "Seconds for observing a nearby-in-time death; this does not attribute a kill.",
        0.5
    )
    addActionOption(GameLearningFeature, "Learning status", function(): ()
        notify(gameLearning:status())
    end)
    addActionOption(GameLearningFeature, "Save learning logs", function(): ()
        gameLearning:save()
    end)
    addActionOption(GameLearningFeature, "Clear learning logs", function(): ()
        gameLearning:delete()
    end)
    addInformationOption(
        GameLearningFeature,
        "Local only: nothing is uploaded. Saved next to the Projectile "
            .. "Calibration file as _Game_Learning.json."
    )

    activeController = gameLearning

    Module.Initialized = true
    return Module
end

function Module.destroy(): ()
    if not Module.Initialized then
        return
    end
    Module.Initialized = false
    if activeController then
        activeController:setEnabled(false)
    end
    activeController = nil
    if type(unsubscribeBridge) == "function" then pcall(unsubscribeBridge) end
    unsubscribeBridge = nil
    Module.Events = {}
end

return Module

]],
        ["src/games/universal/Other/ImproveFps.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "ImproveFps",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local createUniversalFeature: any = host.createUniversalFeature
    local addToggleOption: any = host.addToggleOption

    local fpsSettings: {[string]: boolean} = {
        textures = true,
        particles = true,
        shadows = true,
        materials = false,
    }
    local fpsModeEnabled: boolean = false
    local ImproveFpsFeature: any = nil
    local function selectedEffectCount(): number
        local count: number = 0
        for _name: string, selected: boolean in pairs(fpsSettings) do
            if selected then count += 1 end
        end
        return count
    end

    local fpsVisualCache: any = setmetatable({}, {__mode = "k"})

    local function cacheFpsProperty(object: any, property: string): ()
        local data: any = fpsVisualCache[object]
        if not data then
            data = {}
            fpsVisualCache[object] = data
        end
        if data[property] == nil then
            data[property] = object[property]
        end
    end

    local function applyFpsObject(object: Instance): ()
        local target: any = object
        if fpsSettings.textures and (object:IsA("Decal") or object:IsA("Texture")) then
            cacheFpsProperty(object, "Transparency")
            target.Transparency = 1
        elseif fpsSettings.textures and object:IsA("MeshPart") then
            cacheFpsProperty(object, "TextureID")
            target.TextureID = ""
        end

        if fpsSettings.particles
            and (object:IsA("ParticleEmitter")
                or object:IsA("Trail")
                or object:IsA("Beam")
                or object:IsA("Smoke")
                or object:IsA("Fire")
                or object:IsA("Sparkles")) then
            cacheFpsProperty(object, "Enabled")
            target.Enabled = false
        end

        if object:IsA("BasePart") then
            if fpsSettings.shadows then
                cacheFpsProperty(object, "CastShadow")
                object.CastShadow = false
            end
            if fpsSettings.materials then
                cacheFpsProperty(object, "Material")
                cacheFpsProperty(object, "Reflectance")
                object.Material = Enum.Material.SmoothPlastic
                object.Reflectance = 0
            end
        end
    end

    local function restoreFpsObjects(): ()
        for object: any, properties: any in pairs(fpsVisualCache) do
            if object and object.Parent then
                for property: string, value: any in pairs(properties) do
                    pcall(function(): ()
                        object[property] = value
                    end)
                end
            end
        end
        fpsVisualCache = setmetatable({}, {__mode = "k"})
    end

    local function toggleImproveFps(enabled: boolean): ()
        fpsModeEnabled = enabled
        disconnectFeatureConnection("ImproveFPS")
        restoreFpsObjects()

        if not enabled then
            if ImproveFpsFeature then ImproveFpsFeature:SetStatus(nil) end
            return
        end
        ImproveFpsFeature:SetStatus(tostring(selectedEffectCount()) .. " effects")

        task.spawn(function(): ()
            for index: number, object: Instance in ipairs(workspace:GetDescendants()) do
                if not fpsModeEnabled then
                    return
                end
                pcall(applyFpsObject, object)
                if index % 250 == 0 then
                    task.wait()
                end
            end
        end)
        featureConnections.ImproveFPS = workspace.DescendantAdded:Connect(
            function(object: Instance): ()
                if fpsModeEnabled then
                    pcall(applyFpsObject, object)
                end
            end
        )
    end

    local function refreshFps(): ()
        if fpsModeEnabled then
            toggleImproveFps(true)
        end
    end

    ImproveFpsFeature = createUniversalFeature(
        "Improve FPS",
        "Apply only the selected reversible optimizations",
        26,
        toggleImproveFps,
        {categoryName = "Other"}
    )
    addToggleOption(ImproveFpsFeature, "Remove textures", true, function(value: boolean): ()
        fpsSettings.textures = value
        refreshFps()
    end)
    addToggleOption(ImproveFpsFeature, "Disable particles", true, function(value: boolean): ()
        fpsSettings.particles = value
        refreshFps()
    end)
    addToggleOption(ImproveFpsFeature, "Disable shadows", true, function(value: boolean): ()
        fpsSettings.shadows = value
        refreshFps()
    end)
    addToggleOption(ImproveFpsFeature, "Simple materials", false, function(value: boolean): ()
        fpsSettings.materials = value
        refreshFps()
    end)

    activeCleanup = function(): ()
        toggleImproveFps(false)
    end
    Module.Initialized = true
    return ImproveFpsFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Other/InteractExtender.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "InteractExtender",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local TaskManager: any = host.TaskManager
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local createUniversalFeature: any = host.createUniversalFeature
    local addToggleOption: any = host.addToggleOption
    local addNumberOption: any = host.addNumberOption
    type InteractionSettings = {
        distance: number,
        instantPrompts: boolean,
        proximityPrompts: boolean,
        clickDetectors: boolean,
    }
    type PromptState = {distance: number, holdDuration: number}
    local interactionSettings: InteractionSettings = {
        distance = 32,
        instantPrompts = false,
        proximityPrompts = true,
        clickDetectors = true,
    }
    local originalPrompts: {[ProximityPrompt]: PromptState} =
        setmetatable({}, {__mode = "k"}) :: any
    local originalClickDetectors: {[ClickDetector]: number} =
        setmetatable({}, {__mode = "k"}) :: any
    local interactionExtenderEnabled: boolean = false
    local InteractFeature: any = nil
    local interactionRefreshClock: number = 0

    local function refreshInteractionExtender(): ()
        for prompt: ProximityPrompt, original: PromptState in pairs(originalPrompts) do
            if not prompt.Parent then
                continue
            end
            local wantedDistance: number = interactionExtenderEnabled
                    and interactionSettings.proximityPrompts
                    and interactionSettings.distance
                or original.distance
            local wantedHold: number = interactionExtenderEnabled
                    and interactionSettings.proximityPrompts
                    and interactionSettings.instantPrompts
                    and 0
                or original.holdDuration

            if prompt.MaxActivationDistance ~= wantedDistance then
                prompt.MaxActivationDistance = wantedDistance
            end
            if prompt.HoldDuration ~= wantedHold then
                prompt.HoldDuration = wantedHold
            end
        end
        for detector: ClickDetector, originalDistance: number in pairs(originalClickDetectors) do
            if not detector.Parent then
                continue
            end
            local wantedDistance: number = interactionExtenderEnabled
                    and interactionSettings.clickDetectors
                    and interactionSettings.distance
                or originalDistance
            if detector.MaxActivationDistance ~= wantedDistance then
                detector.MaxActivationDistance = wantedDistance
            end
        end
    end

    local function applyInteractionExtension(instance: Instance): ()
        if not interactionExtenderEnabled then
            return
        end
        if instance:IsA("ProximityPrompt") then
            if originalPrompts[instance] == nil then
                originalPrompts[instance] = {
                    distance = instance.MaxActivationDistance,
                    holdDuration = instance.HoldDuration,
                }
            end
            local original: PromptState = originalPrompts[instance]
            instance.MaxActivationDistance = interactionSettings.proximityPrompts
                    and interactionSettings.distance
                or original.distance
            instance.HoldDuration = interactionSettings.proximityPrompts
                    and interactionSettings.instantPrompts
                    and 0
                or original.holdDuration
        elseif instance:IsA("ClickDetector") then
            if originalClickDetectors[instance] == nil then
                originalClickDetectors[instance] = instance.MaxActivationDistance
            end
            instance.MaxActivationDistance = interactionSettings.clickDetectors
                    and interactionSettings.distance
                or originalClickDetectors[instance]
        end
    end

    local function restoreInteractionExtender(): ()
        interactionExtenderEnabled = false
        refreshInteractionExtender()
        originalPrompts = setmetatable({}, {__mode = "k"}) :: any
        originalClickDetectors = setmetatable({}, {__mode = "k"}) :: any
    end

    local function toggleInteractionExtender(enabled: boolean): ()
        disconnectFeatureConnection("InteractExtender")
        disconnectFeatureConnection("InteractExtenderRefresh")
        restoreInteractionExtender()
        interactionRefreshClock = 0
        if not enabled then
            if InteractFeature then InteractFeature:SetStatus(nil) end
            return
        end
        InteractFeature:SetStatus(tostring(math.round(interactionSettings.distance)) .. " studs")
        interactionExtenderEnabled = true
        featureConnections.InteractExtender = workspace.DescendantAdded:Connect(
            applyInteractionExtension
        )
        featureConnections.InteractExtenderRefresh = TaskManager:Connect(
            function(deltaTime: number): ()
                interactionRefreshClock += deltaTime
                if interactionRefreshClock >= 0.5 then
                    interactionRefreshClock = 0
                    refreshInteractionExtender()
                end
            end
        )
        task.spawn(function(): ()
            for index: number, instance: Instance in ipairs(workspace:GetDescendants()) do
                if not interactionExtenderEnabled then
                    return
                end
                applyInteractionExtension(instance)
                if index % 240 == 0 then
                    task.wait()
                end
            end
        end)
    end

    InteractFeature = createUniversalFeature(
        "Interact Extender",
        "Extend prompt and click interaction range without auto-firing",
        24,
        toggleInteractionExtender,
        {categoryName = "Other"}
    )
    addNumberOption(
        InteractFeature,
        "Interaction distance",
        interactionSettings.distance,
        8,
        250,
        function(value: number): ()
            interactionSettings.distance = value
            if InteractFeature.enabled then
                InteractFeature:SetStatus(tostring(math.round(value)) .. " studs")
            end
            refreshInteractionExtender()
        end
    )
    addToggleOption(
        InteractFeature,
        "Instant prompts",
        interactionSettings.instantPrompts,
        function(value: boolean): ()
            interactionSettings.instantPrompts = value
            refreshInteractionExtender()
        end
    )
    addToggleOption(
        InteractFeature,
        "Proximity prompts",
        interactionSettings.proximityPrompts,
        function(value: boolean): ()
            interactionSettings.proximityPrompts = value
            refreshInteractionExtender()
        end
    )
    addToggleOption(
        InteractFeature,
        "Click detectors",
        interactionSettings.clickDetectors,
        function(value: boolean): ()
            interactionSettings.clickDetectors = value
            refreshInteractionExtender()
        end
    )

    activeCleanup = function(): ()
        disconnectFeatureConnection("InteractExtender")
        disconnectFeatureConnection("InteractExtenderRefresh")
        restoreInteractionExtender()
        interactionRefreshClock = 0
        if InteractFeature then
            InteractFeature:SetStatus(nil)
        end
    end
    Module.Initialized = true
    return InteractFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Other/LagSwitch.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "LagSwitch",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local TaskManager: any = host.TaskManager
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local createUniversalFeature: any = host.createUniversalFeature
    local addNumberOption: any = host.addNumberOption
    local lagSwitchSettings = {incomingLag = 999}
    local originalIncomingLag = 0
    local LagSwitchFeature: any = nil

    local function setIncomingReplicationLag(value)
        local success = pcall(function()
            settings():GetService("NetworkSettings").IncomingReplicationLag = value
        end)
        return success
    end

    local function toggleLagSwitch(enabled)
        disconnectFeatureConnection("LagSwitch")

        if not enabled then
            if LagSwitchFeature then LagSwitchFeature:SetStatus(nil) end
            setIncomingReplicationLag(originalIncomingLag)
            return
        end

        LagSwitchFeature:SetStatus(tostring(math.round(lagSwitchSettings.incomingLag)) .. " ms")
        pcall(function()
            originalIncomingLag = settings():GetService(
                "NetworkSettings"
            ).IncomingReplicationLag
        end)

        if not setIncomingReplicationLag(lagSwitchSettings.incomingLag) then
            error("NetworkSettings is not available in this client.")
        end

        featureConnections.LagSwitch = TaskManager:Connect(function()
            setIncomingReplicationLag(lagSwitchSettings.incomingLag)
        end)
    end

    LagSwitchFeature = createUniversalFeature(
        "Lag Switch",
        "Simulate extreme incoming replication delay",
        16,
        toggleLagSwitch,
        {categoryName = "Other"}
    )
    addNumberOption(
        LagSwitchFeature,
        "Incoming lag",
        lagSwitchSettings.incomingLag,
        1,
        999,
        function(value)
            lagSwitchSettings.incomingLag = value
            if LagSwitchFeature.enabled then
                LagSwitchFeature:SetStatus(tostring(math.round(value)) .. " ms")
            end
        end
    )

    activeCleanup = function(): ()
        disconnectFeatureConnection("LagSwitch")
        setIncomingReplicationLag(originalIncomingLag)
    end
    Module.Initialized = true
    return LagSwitchFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Other/Learning.lua"] = [[
export type Runtime = {
    framework: any,
    host: any,
    services: any,
}

local Module = {
    Name = "Learning",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCard: any = nil

function Module.init(context: Runtime): any
    local framework: any = context.framework
    local host: any = context.host
    local services: any = context.services
    local captureService: any = services and services.screenCapture
    local product: any = host.PRODUCT or {}
    local httpService: any = host.HttpService
    local currentWorkspace: Workspace = host.workspace or workspace
    local sampleNumber: number = 0
    local card: any

    local function writeMetadata(path: string, payload: any): boolean
        if not captureService or type(captureService.writeText) ~= "function" then
            return false
        end
        local ok: boolean, encoded: any = pcall(function(): string
            return httpService:JSONEncode(payload)
        end)
        if not ok or type(encoded) ~= "string" then
            return false
        end
        return captureService.writeText(path, encoded) == true
    end

    local function captureSample(): ()
        if not captureService or type(captureService.isAvailable) ~= "function"
            or not captureService.isAvailable() then
            card:Notify("screenshot API unavailable")
            card:SetStatus("unavailable")
            return
        end
        if type(captureService.capture) ~= "function"
            or type(captureService.writeText) ~= "function" then
            card:Notify("screen capture service incomplete")
            card:SetStatus("unavailable")
            return
        end

        sampleNumber += 1
        local folder: string = tostring(product.storageFolder or "Wurst")
            .. "/Learning"
        local stamp: string = tostring(os.time())
        local base: string = folder
            .. "/"
            .. tostring(game.PlaceId)
            .. "-"
            .. stamp
            .. "-"
            .. tostring(sampleNumber)
        local imagePath: string = base .. ".png"
        local metadataPath: string = base .. ".json"
        local captured: boolean, reason: any = captureService.capture(imagePath)
        if not captured then
            card:Notify(tostring(reason or "screen capture failed"))
            card:SetStatus("failed")
            return
        end

        local camera: Camera? = currentWorkspace.CurrentCamera
        local viewport: Vector2 = camera
            and camera.ViewportSize
            or Vector2.new(0, 0)
        local payload: {[string]: any} = {
            schema = 1,
            kind = "learning-screen-sample",
            image = imagePath,
            capturedAt = os.time(),
            placeId = game.PlaceId,
            viewport = {width = viewport.X, height = viewport.Y},
            source = "manual Capture now action",
            menuVisible = services.menu.isVisible(),
        }
        local wrote: boolean = writeMetadata(metadataPath, payload)
        if not wrote then
            card:Notify("image saved; metadata could not be written")
            card:SetStatus("image saved")
            return
        end
        card:SetStatus("saved " .. tostring(sampleNumber))
        card:Notify("saved learning sample " .. tostring(sampleNumber))
    end

    card = framework.Categories.Other:CreateModule({
        Name = "Learning",
        Category = "Other",
        ConfigKey = "Universal.Learning",
        Kind = "group",
        Order = 26,
        Tooltip = "Save a manual local screenshot and a small metadata sidecar.",
        Function = function(_enabled: boolean): ()

        end,
    })
    card:CreateButton({
        Name = "Capture now",
        Tooltip = "Save one screenshot locally; no upload or background capture.",
        Function = captureSample,
    })
    card:CreateNote(
        "Manual and local only. Standard Roblox Luau has no screenshot API."
    )

    activeCard = card
    Module.Initialized = true
    return card
end

function Module.destroy(): ()
    if activeCard and activeCard.Enabled then
        activeCard:Toggle(false)
    end
    activeCard = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Other/RejoinServer.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "RejoinServer",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local LocalPlayer: any = host.LocalPlayer
    local createUniversalFeature: any = host.createUniversalFeature
    local cloneReference: any = host.cloneReference
    local notify: (string) -> () = host.notify
    local function rejoinCurrentServer(): ()
        local teleportService: TeleportService = cloneReference(
            game:GetService("TeleportService")
        )
        local placeId: number = game.PlaceId
        local jobId: string = tostring(game.JobId or "")

        local rejoined: boolean = false
        if jobId ~= "" then
            rejoined = pcall(function(): ()
                teleportService:TeleportToPlaceInstance(placeId, jobId, LocalPlayer)
            end)
        end
        if not rejoined then
            local ok: boolean, teleportError: any = pcall(function(): ()
                teleportService:Teleport(placeId, LocalPlayer)
            end)
            if not ok then
                notify("Rejoin failed: " .. tostring(teleportError))
            end
        end
    end
    local actionId: string = "RejoinServer"
    local registries: any = context.services.registries
    local wurstOptions: any = registries.wurstOptions()
    if wurstOptions and type(wurstOptions.RegisterAction) == "function" then
        local registered: boolean, registration: any = pcall(
            wurstOptions.RegisterAction,
            actionId,
            "Rejoin Server",
            rejoinCurrentServer,
            {
                description = "Reconnect to the current server instance",
                configKey = "Universal.RejoinServer",
            }
        )
        if not registered then
            error("Wurst Options refused Rejoin Server: " .. tostring(registration))
        end
        local search: any = registries.moduleSearch()
        local searchFeature: any = {
            name = "Rejoin Server",
            configKey = "Universal.RejoinServer",
            kind = "action",
            searchable = false,
            enabled = false,
            activate = rejoinCurrentServer,
        }
        if search and type(search.Register) == "function" then
            search.Register(searchFeature)
        end
        activeCleanup = function(): ()
            if search and type(search.Unregister) == "function" then
                search.Unregister(searchFeature)
            end
            if type(registration) == "table"
                and type(registration.Unregister) == "function" then
                registration.Unregister()
            elseif type(wurstOptions.UnregisterAction) == "function" then
                pcall(wurstOptions.UnregisterAction, actionId)
            end
        end
        Module.Initialized = true
        return registration
    end

    local feature: any = createUniversalFeature(
        "Rejoin Server",
        "Reconnect to the current server instance",
        22,
        rejoinCurrentServer,
        {
            action = true,
            noOptions = true,
            categoryName = "Other",
            searchable = false,
        }
    )

    activeCleanup = function(): () end
    Module.Initialized = true
    return feature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Other/RemoteLogger.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "RemoteLogger",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

local function fullName(instance: Instance): string
    local ok: boolean, name: any = pcall(function(): string
        return instance:GetFullName()
    end)
    return ok and tostring(name) or instance.Name
end

local function describe(value: any, depth: number): string
    local kind: string = typeof(value)
    if kind == "string" then
        return string.format("%q", (value :: string):sub(1, 200))
    end
    if kind == "number" or kind == "boolean" or kind == "nil" then
        return tostring(value)
    end
    if kind == "Instance" then
        return "«" .. (value :: Instance).ClassName .. " " .. fullName(value :: Instance) .. "»"
    end
    if kind == "Vector3" or kind == "Vector2" or kind == "CFrame"
        or kind == "Color3" or kind == "UDim2" or kind == "EnumItem" then
        return kind .. "(" .. tostring(value) .. ")"
    end
    if kind == "table" then
        if depth <= 0 then
            return "{...}"
        end
        local parts: {string} = {}
        local count: number = 0
        for key: any, entry: any in pairs(value :: any) do
            count += 1
            if count > 12 then
                table.insert(parts, "...")
                break
            end
            table.insert(
                parts,
                "[" .. describe(key, depth - 1) .. "] = " .. describe(entry, depth - 1)
            )
        end
        return "{" .. table.concat(parts, ", ") .. "}"
    end
    return kind
end

local function snippetFor(entry: any): string
    local parts: {string} = {}
    for _, argument: string in ipairs(entry.arguments) do
        table.insert(parts, argument)
    end
    return "game:GetService(\"ReplicatedStorage\")"
        .. " -- "
        .. entry.path
        .. "\n-- :"
        .. entry.method
        .. "("
        .. table.concat(parts, ", ")
        .. ")"
end

function Module.init(context: Runtime): any
    local host: any = context.host
    local framework: any = context.framework
    local httpService: HttpService = host.HttpService
    local product: any = host.PRODUCT
    local remoteLogFolder: string = product.storageFolder .. "/RemoteLogs"

    local log: {[string]: any} = {}
    local order: {string} = {}
    local pathCache: any = setmetatable({}, {__mode = "k"})
    local hooked: boolean = false
    local restore: (() -> ())? = nil
    local capturing: boolean = false

    local logger: any

    local function record(remote: Instance, method: string, ...: any): ()
        if not capturing then
            return
        end
        local options: any = logger.Options

        local path: string = pathCache[remote]
        if not path then
            path = fullName(remote)
            pathCache[remote] = path
        end
        local filter: string = tostring(options["Only containing"].Value or "")
        if filter ~= ""
            and not string.find(string.lower(path), string.lower(filter), 1, true) then
            return
        end

        local key: string = path .. "::" .. method
        local entry: any = log[key]
        if not entry then
            if #order >= math.round(options["Max remotes"].Value) then
                return
            end
            entry = {
                path = path,
                class = remote.ClassName,
                method = method,
                calls = 0,
                samples = 0,
                firstSeen = os.clock(),
                arguments = {},
            }
            log[key] = entry
            table.insert(order, key)
            if options["Announce new"].Value then
                logger:Notify(remote.Name .. " · " .. method)
            end
        end
        entry.calls += 1
        entry.lastSeen = os.clock()

        if entry.samples >= 3 and not options["Resample always"].Value then
            return
        end
        entry.samples += 1
        local described: {string} = {}
        local packed: {any} = table.pack(...)
        for index: number = 1, math.min(packed.n, 10) do
            table.insert(described, describe(packed[index], 3))
        end
        if packed.n > 10 then
            table.insert(described, "...")
        end
        entry.arguments = described
    end

    local queue: {any} = {}
    local queued: number = 0
    local inHook: boolean = false

    local function installHook(): boolean
        if hooked then
            return true
        end
        local environment: any = getfenv()
        local hookMetamethod: any = environment.hookmetamethod
        local getNamecall: any = environment.getnamecallmethod
        local checkCaller: any = environment.checkcaller
        if type(hookMetamethod) ~= "function" or type(getNamecall) ~= "function" then
            logger:Notify("executor lacks hookmetamethod")
            return false
        end

        local previous: any
        local ok: boolean = pcall(function(): ()
            previous = hookMetamethod(game, "__namecall", function(self: any, ...: any): any

                if not capturing or inHook then
                    return previous(self, ...)
                end
                local method: string = getNamecall()
                if method ~= "FireServer" and method ~= "InvokeServer" then
                    return previous(self, ...)
                end
                if type(checkCaller) == "function" and checkCaller() then
                    return previous(self, ...)
                end
                if queued < 256 then
                    inHook = true
                    queued += 1
                    queue[queued] = {
                        remote = self,
                        method = method,
                        count = select("#", ...),
                        arguments = table.pack(...),
                        at = os.clock(),
                    }
                    inHook = false
                end
                return previous(self, ...)
            end)
        end)
        if not ok then
            logger:Notify("could not install the hook")
            return false
        end
        hooked = true
        restore = function(): ()

            local removed: boolean = pcall(hookMetamethod, game, "__namecall", previous)
            if removed then
                hooked = false
                return
            end

            logger:Notify("hook stays until rejoin")
        end
        return true
    end

    local function drainQueue(): ()
        if queued == 0 then
            return
        end
        local pending: {any} = queue
        queue = {}
        local count: number = queued
        queued = 0
        for index: number = 1, count do
            local item: any = pending[index]
            if item then
                pcall(function(): ()
                    record(
                        item.remote,
                        item.method,
                        table.unpack(item.arguments, 1, item.count)
                    )
                end)
            end
        end
        logger:SetStatus(tostring(#order))
    end

    local function buildReport(): string
        local lines: {string} = {
            "-- " .. tostring(product.name) .. " remote log",
            "-- place " .. tostring(game.PlaceId),
            "-- " .. tostring(#order) .. " remotes",
            "",
        }
        for _, key: string in ipairs(order) do
            local entry: any = log[key]
            table.insert(lines, string.rep("-", 70))
            table.insert(lines, entry.path)
            table.insert(
                lines,
                "  class "
                    .. entry.class
                    .. "  ·  "
                    .. entry.method
                    .. "  ·  "
                    .. tostring(entry.calls)
                    .. " calls"
            )
            table.insert(lines, "  args  " .. table.concat(entry.arguments, ", "))
            table.insert(lines, snippetFor(entry))
        end
        return table.concat(lines, "\n")
    end

    local function saveReport(): ()
        local environment: any = getfenv()
        local writeFile: any = environment.writefile
        local makeFolder: any = environment.makefolder
        local isFolder: any = environment.isfolder
        if type(writeFile) ~= "function" then
            logger:Notify("executor has no writefile")
            return
        end
        if type(makeFolder) == "function" and type(isFolder) == "function" then
            if not isFolder(product.storageFolder) then
                pcall(makeFolder, product.storageFolder)
            end
            if not isFolder(remoteLogFolder) then
                pcall(makeFolder, remoteLogFolder)
            end
        end

        local stamp: string = tostring(math.round(os.time()))
        local base: string = remoteLogFolder
            .. "/"
            .. tostring(game.PlaceId)
            .. "-"
            .. stamp

        local wrote: boolean = pcall(writeFile, base .. ".txt", buildReport())

        local payload: {any} = {}
        for _, key: string in ipairs(order) do
            local entry: any = log[key]
            table.insert(payload, {
                path = entry.path,
                class = entry.class,
                method = entry.method,
                calls = entry.calls,
                arguments = entry.arguments,
            })
        end
        local encoded: boolean, json: any = pcall(function(): string
            return httpService:JSONEncode(payload)
        end)
        if encoded then
            pcall(writeFile, base .. ".json", json)
        end
        if wrote then
            logger:Notify("saved " .. tostring(#order) .. " remotes")
        else
            logger:Notify("could not write the log")
        end
    end

    logger = framework.Categories.Other:CreateModule({
        Name = "Remote Logger",
        Category = "Other",
        Order = 2,
        Tooltip = "Records the arguments the game sends to its own remotes and "
            .. "writes them to disk.",
        Function = function(enabled: boolean): ()
            capturing = enabled
            if not enabled then
                logger:SetStatus(nil)
                return
            end
            logger:SetStatus(tostring(#order))
            if not installHook() then
                capturing = false
                return
            end
            logger:Loop(drainQueue)
            logger:Clean(function(): ()
                capturing = false
                queue = {}
                queued = 0
                if restore then
                    (restore :: () -> ())()
                    restore = nil
                end
            end)
        end,
    })

    logger:CreateTextBox({
        Name = "Only containing",
        Default = "",
        Tooltip = "Record only remotes whose path contains this. Leave empty "
            .. "for everything.",
    })
    logger:CreateSlider({
        Name = "Max remotes",
        Min = 10,
        Max = 400,
        Default = 120,
        Tooltip = "Stops the log growing without bound in a chatty game.",
    })
    logger:CreateToggle({
        Name = "Announce new",
        Default = false,
        Tooltip = "Toast the first time each remote is seen.",
    })
    logger:CreateToggle({
        Name = "Resample always",
        Default = false,
        Tooltip = "Describe the arguments of every call instead of the first "
            .. "few. Useful for a remote whose shape changes; heavier.",
    })

    logger:CreateButton({
        Name = "Save to file",
        Tooltip = "Writes " .. remoteLogFolder .. "/<place>-<time>.txt and .json",
        Function = saveReport,
    })
    logger:CreateButton({
        Name = "Copy to clipboard",
        Function = function(): ()
            local environment: any = getfenv()
            local copy: any = environment.setclipboard or environment.toclipboard
            if type(copy) ~= "function" then
                logger:Notify("executor has no clipboard")
                return
            end
            pcall(copy, buildReport())
            logger:Notify("copied")
        end,
    })
    logger:CreateButton({
        Name = "Clear log",
        Function = function(): ()
            log = {}
            order = {}
            if logger.Enabled then
                logger:SetStatus("0")
            end
            logger:Notify("cleared")
        end,
    })
    logger:CreateNote(
        "Turn it on, do the thing you want a module to do — buy, mine, place, "
            .. "hit — then save. The log records what only a live game can "
            .. "tell you: the arguments, in order, as the game really sent "
            .. "them. It watches; it never blocks, delays or alters a call."
    )

    Module.entries = function(): {any}
        local list: {any} = {}
        for _, key: string in ipairs(order) do
            table.insert(list, log[key])
        end
        return list
    end
    Module.report = buildReport

    activeCleanup = function(): ()
        capturing = false
        if restore then
            (restore :: () -> ())()
            restore = nil
        end
        Module.entries = nil
        Module.report = nil
    end
    Module.Initialized = true
    return logger
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/Arrows.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    render: any,
    host: any,
    services: any,
}

local Module = {
    Name = "Arrows",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCard: any = nil

function Module.init(context: Runtime): any
    local framework: any = context.framework
    local entity: any = context.entity
    local render: any = context.render
    local protectedTargets: any = context.services.protectedTargets
    local currentWorkspace: Workspace = context.host.workspace or workspace
    local layer: Frame = render:Layer("ArrowsLayer")
    local shown: {[Player]: boolean} = {}

    local card: any
    local function clear(): ()
        render:ReleaseAll(layer)
        table.clear(shown)
        layer.Visible = false
    end

    card = framework.Categories.Visuals:CreateModule({
        Name = "Arrows",
        Category = "Render",
        ConfigKey = "Universal.Arrows",
        Order = 3,
        Tooltip = "Points toward players outside the camera view.",
        Function = function(enabled: boolean): ()
            layer.Visible = enabled
            if not enabled then
                clear()
                card:SetStatus(nil)
                return
            end
            card:Render(function(): ()
                local camera: Camera? = currentWorkspace.CurrentCamera
                if not camera then
                    render:ReleaseAll(layer)
                    table.clear(shown)
                    return
                end
                local viewport: Vector2 = camera.ViewportSize
                local centre: Vector2 = Vector2.new(viewport.X / 2, viewport.Y / 2)
                local radius: number = math.max(40, math.min(viewport.X, viewport.Y) * 0.4)
                local seen: {[Player]: boolean} = {}
                local count: number = 0
                for _, target: any in ipairs(entity:Refresh()) do
                    local player: Player = target.Player
                    if (not card.Options["Teammates"].Value and target.IsFriendly)
                        or protectedTargets.isProtected(player)
                        or not target.Humanoid
                        or target.Humanoid.Health <= 0
                        or not target.RootPart
                        or target.Distance > card.Options["Max distance"].Value then
                        render:Release(layer, player)
                        continue
                    end
                    local projected: Vector3, onScreen: boolean =
                        camera:WorldToViewportPoint(target.RootPart.Position)
                    if onScreen then
                        render:Release(layer, player)
                        continue
                    end
                    local drawing: any = render:Set(layer, player)
                    local delta: Vector2 = Vector2.new(projected.X, projected.Y) - centre
                    if projected.Z < 0 then
                        delta = Vector2.new(-delta.X, -delta.Y)
                    end
                    if delta.Magnitude < 0.001 then
                        delta = Vector2.new(0, -1)
                    end
                    local direction: Vector2 = delta.Unit
                    local perpendicular: Vector2 = Vector2.new(-direction.Y, direction.X)
                    local tip: Vector2 = centre + direction * radius
                    local back: Vector2 = tip - direction * 16
                    local colour: Color3 = card.Options["Colour"].Value
                    drawing:Line("Arrow", 1, tip, back + perpendicular * 8, 2, colour)
                    drawing:Line("Arrow", 2, tip, back - perpendicular * 8, 2, colour)
                    drawing:HideLines("Arrow", 3, 8)
                    if card.Options["Distance"].Value then
                        drawing:Label(
                            "Distance",
                            tostring(math.round(target.Distance)) .. "m",
                            tip - direction * 26,
                            0.5,
                            12,
                            colour,
                            true
                        )
                    else
                        drawing:HideLabel("Distance")
                    end
                    drawing:Show(true)
                    seen[player] = true
                    count += 1
                end
                for player: Player in pairs(shown) do
                    if not seen[player] then
                        render:Release(layer, player)
                    end
                end
                shown = seen
                card:SetStatus(tostring(count))
            end)
            card:Clean(clear)
        end,
    })

    card:CreateColor({Name = "Colour", Default = Color3.fromRGB(0, 204, 255)})
    card:CreateToggle({Name = "Distance", Default = true})
    card:CreateSlider({Name = "Max distance", Min = 25, Max = 2000, Step = 25, Default = 500})
    card:CreateToggle({Name = "Teammates", Default = false})

    activeCard = card
    Module.Initialized = true
    return card
end

function Module.destroy(): ()
    if activeCard and activeCard.Enabled then
        activeCard:Toggle(false)
    end
    activeCard = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/Chams.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "Chams",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCard: any = nil
local activeBridgeCleanup: (() -> ())? = nil

local PERK_ICONS: {[string]: string} = {
    ["Footsteps"] = "rbxassetid://336404773",
    ["Sleight"] = "rbxassetid://340309581",
    ["Ninja"] = "rbxassetid://416832054",
    ["Haste"] = "rbxassetid://416942717",
    ["FakeGun"] = "rbxassetid://17899774181",
    ["Fake Gun"] = "rbxassetid://17899774181",
    ["Ghost"] = "rbxassetid://335206856",
    ["Xray"] = "rbxassetid://340313896",
    ["X-Ray"] = "rbxassetid://340313896",
    ["Trap"] = "rbxassetid://4966828196",
    ["Sprint"] = "rbxassetid://4970219155",
    ["VampireBat"] = "rbxassetid://129078122681639",
    ["Bat Form"] = "rbxassetid://129078122681639",
    ["Decoy"] = "rbxassetid://113722008817201",
}

function Module.init(context: Runtime): any
    local framework: any = context.framework
    local entity: any = context.entity
    local host: any = context.host
    local protectedTargets: any = context.services.protectedTargets
    local currentWorkspace: Workspace = host.workspace or workspace
    local highlights: {[Player]: Highlight} = {}
    local murderTag: BillboardGui? = nil
    local roleTags: {[Player]: BillboardGui} = {}
    local lastUpdate: number = -math.huge

    local function destroyMurderTag(): ()
        if murderTag then
            pcall(murderTag.Destroy, murderTag)
            murderTag = nil
        end
    end

    local function clearRoleTags(): ()
        for player: Player, tag: BillboardGui in pairs(roleTags) do
            roleTags[player] = nil
            pcall(tag.Destroy, tag)
        end
    end

    local gameBridge: any = context.services.gameBridge
    if activeBridgeCleanup then
        pcall(activeBridgeCleanup)
        activeBridgeCleanup = nil
    end
    if type(gameBridge.onEvent) == "function" then
        activeBridgeCleanup = gameBridge.onEvent(function(kind: string): ()
            if kind == "roleUpdate" then
                lastUpdate = -math.huge
            end
        end)
    end

    local store: any = host.configData
    if store and store.values and store.states then
        local oldMode: any = store.values["Universal.PlayerESP.Chams"]
        if store.states["Universal.Chams"] == nil
            and (oldMode == "Overlay" or oldMode == "Outline") then
            store.states["Universal.Chams"] = true
            local fillKey: string = "Universal.Chams.Filltransparency"
            if store.values[fillKey] == nil then
                store.values[fillKey] = oldMode == "Outline" and 1 or 0.55
            end
            if type(host.queueConfigSave) == "function" then
                host.queueConfigSave()
            end
        end
    end

    local card: any

    local function syncMM2Extras(enabled: boolean): ()
        if state and state.mm2Core then
            if type(state.mm2Core.toggleGunEsp) == "function" then
                pcall(state.mm2Core.toggleGunEsp, enabled and card.Options["Gun ESP"] and card.Options["Gun ESP"].Value == true)
            end
            if type(state.mm2Core.toggleTrapEsp) == "function" then
                pcall(state.mm2Core.toggleTrapEsp, enabled and card.Options["Trap ESP"] and card.Options["Trap ESP"].Value == true)
            end
        end
    end

    local function clear(): ()
        for player: Player, highlight: Highlight in pairs(highlights) do
            highlights[player] = nil
            highlight:Destroy()
        end
        destroyMurderTag()
        clearRoleTags()
        syncMM2Extras(false)
    end

    card = framework.Categories.Visuals:CreateModule({
        Name = "Chams",
        Category = "Render",
        ConfigKey = "Universal.Chams",
        Order = 2,
        Tooltip = "Highlights live players, optionally through walls.",
        Function = function(enabled: boolean): ()
            if not enabled then
                clear()
                card:SetStatus(nil)
                return
            end
            card:SetStatus("0")
            syncMM2Extras(true)

            card:Render(function(): ()
                local now: number = os.clock()
                if now - lastUpdate < 0.2 then return end
                lastUpdate = now
                local seen: {[Player]: boolean} = {}
                local count: number = 0

                local targets: any = entity:Refresh()
                for _, target: any in ipairs(targets) do
                    local player: Player = target.Player
                    local allowedTeam: boolean = card.Options["Teammates"].Value
                        or not target.IsFriendly
                    local protected: boolean = protectedTargets.isProtected(player)
                    if allowedTeam and not protected
                        and target.Character
                        and target.Humanoid
                        and target.Humanoid.Health > 0 then
                        seen[player] = true
                        count += 1
                        local highlight: Highlight? = highlights[player]
                        if not highlight or not highlight.Parent then
                            highlight = Instance.new("Highlight")
                            highlight.Name = "Wurst_Chams"
                            highlight.Parent = currentWorkspace
                            highlights[player] = highlight
                        end
                        local resolved: Highlight = highlight :: Highlight
                        local roleColour: Color3? = nil
                        if type(gameBridge.playerRoleColor) == "function" then
                            roleColour = gameBridge.playerRoleColor(player)
                        end
                        local teamColour: Color3? = nil
                        local teamOption: any = card.Options["Team colours"]
                        if not roleColour
                            and teamOption ~= nil
                            and teamOption.Value == true then
                            local isTeammate: boolean = target.IsFriendly
                                or (LocalPlayer and target.Team and LocalPlayer.Team and target.Team == LocalPlayer.Team)
                                or (LocalPlayer and player:GetAttribute("Team") ~= nil and player:GetAttribute("Team") == LocalPlayer:GetAttribute("Team"))
                            teamColour = isTeammate and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(255, 0, 0)
                        end
                        local fillColour: Color3 = roleColour
                            or teamColour
                            or card.Options["Fill colour"].Value
                        local outlineColour: Color3 = roleColour
                            or teamColour
                            or card.Options["Outline colour"].Value
                        local fillTransparency: number = card.Options["Fill transparency"].Value
                        local outlineTransparency: number = card.Options["Outline transparency"].Value
                        local depthMode: Enum.HighlightDepthMode = card.Options["Through walls"].Value
                                and Enum.HighlightDepthMode.AlwaysOnTop
                            or Enum.HighlightDepthMode.Occluded
                        if resolved.Adornee ~= target.Character then resolved.Adornee = target.Character end
                        if resolved.FillColor ~= fillColour then resolved.FillColor = fillColour end
                        if resolved.OutlineColor ~= outlineColour then resolved.OutlineColor = outlineColour end
                        if resolved.FillTransparency ~= fillTransparency then resolved.FillTransparency = fillTransparency end
                        if resolved.OutlineTransparency ~= outlineTransparency then resolved.OutlineTransparency = outlineTransparency end
                        if resolved.DepthMode ~= depthMode then resolved.DepthMode = depthMode end
                    end
                end
                for player: Player, highlight: Highlight in pairs(highlights) do
                    if not seen[player] then
                        highlights[player] = nil
                        highlight:Destroy()
                    end
                end

                local tagTarget: Player? = nil
                if card.Options["Murder tag"].Value == true
                    and type(gameBridge.playerRole) == "function" then
                    for _, target: any in ipairs(targets) do
                        local okRole: boolean, role: any = pcall(
                            gameBridge.playerRole,
                            target.Player
                        )
                        if okRole
                            and role == "Murderer"
                            and target.Character
                            and target.Humanoid
                            and target.Humanoid.Health > 0 then
                            tagTarget = target.Player
                            break
                        end
                    end
                end

                local tagHead: BasePart? = nil
                if not tagTarget then
                    destroyMurderTag()
                else
                    local tagCharacter: Model? = tagTarget.Character
                    tagHead = tagCharacter
                        and (tagCharacter:FindFirstChild("Head")
                            or tagCharacter:FindFirstChild("HumanoidRootPart"))
                        :: BasePart?
                    if not tagHead then
                        destroyMurderTag()
                    else
                        if not murderTag
                            or not murderTag.Parent
                            or murderTag.Adornee ~= tagHead then
                            destroyMurderTag()
                            local billboard: BillboardGui = Instance.new("BillboardGui")
                            billboard.Name = "Wurst_MurderTag"
                            billboard.AlwaysOnTop = true
                            billboard.LightInfluence = 0
                            billboard.Size = UDim2.fromOffset(150, 22)
                            billboard.StudsOffset = Vector3.new(0, 3.5, 0)
                            billboard.MaxDistance = 1500
                            billboard.Adornee = tagHead
                            billboard.Parent = tagHead
                            local label: TextLabel = Instance.new("TextLabel")
                            label.Name = "Murder"
                            label.BackgroundTransparency = 1
                            label.Size = UDim2.fromScale(1, 1)
                            label.Font = Enum.Font.GothamBold
                            label.TextSize = 14
                            label.TextScaled = false
                            label.Text = "Murder"
                            label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
                            label.TextStrokeTransparency = 0.3
                            label.Parent = billboard

                            local icon: ImageLabel = Instance.new("ImageLabel")
                            icon.Name = "PerkIcon"
                            icon.BackgroundTransparency = 1
                            icon.ImageTransparency = 1
                            icon.Visible = false
                            icon.Size = UDim2.fromOffset(20, 20)
                            icon.Position = UDim2.new(0, 3, 0.5, 0)
                            icon.AnchorPoint = Vector2.new(0, 0.5)
                            icon.Parent = billboard

                            murderTag = billboard
                        end
                        if type(gameBridge.playerRoleColor) == "function" then
                            local okColour: boolean, colour: any = pcall(
                                gameBridge.playerRoleColor,
                                tagTarget
                            )
                            if okColour and typeof(colour) == "Color3" then
                                local label: any =
                                    murderTag and murderTag:FindFirstChild("Murder")
                                if label and label.TextColor3 ~= colour then
                                    label.TextColor3 = colour
                                end
                            end
                        end
                    end
                end

                local perkIcon: any = murderTag
                    and murderTag:FindFirstChild("PerkIcon")
                if card.Options["Show Perk"] and card.Options["Show Perk"].Value == true
                    and tagTarget and perkIcon then
                    local targetPerk: string? = nil
                    if type(gameBridge.playerPerk) == "function" then
                        targetPerk = gameBridge.playerPerk(tagTarget)
                    end
                    if not targetPerk and state and state.mm2Core and type(state.mm2Core.getPlayerPerk) == "function" then
                        targetPerk = state.mm2Core.getPlayerPerk(tagTarget)
                    end

                    local perkIconId: string? = targetPerk and (PERK_ICONS[targetPerk] or PERK_ICONS[string.gsub(targetPerk, "%s+", "")]) or nil
                    if perkIconId then
                        if perkIcon.Image ~= perkIconId then
                            perkIcon.Image = perkIconId
                        end
                        if not perkIcon.Visible then
                            perkIcon.Visible = true
                        end
                        if perkIcon.ImageTransparency ~= 0 then
                            perkIcon.ImageTransparency = 0
                        end
                    elseif perkIcon.Visible then
                        perkIcon.Visible = false
                    end
                elseif perkIcon and perkIcon.Visible then
                    perkIcon.Visible = false
                end

                local roleTagsOption: any = card.Options["Role tags"]
                if roleTagsOption and roleTagsOption.Value == true
                    and type(gameBridge.playerRole) == "function" then
                    local seenRoleTags: {[Player]: boolean} = {}
                    for _, target: any in ipairs(targets) do
                        local player: Player = target.Player
                        if player ~= LocalPlayer
                            and target.Character
                            and target.Humanoid
                            and target.Humanoid.Health > 0
                            and not protectedTargets.isProtected(player) then
                            local okRole: boolean, role: any = pcall(gameBridge.playerRole, player)
                            if okRole and type(role) == "string" and role ~= "Dead" then

                                if card.Options["Murder tag"].Value == true and (role == "Murderer" or player == tagTarget) then
                                    continue
                                end

                                local head: BasePart? = target.Character:FindFirstChild("Head")
                                    or target.Character:FindFirstChild("HumanoidRootPart")
                                if head then
                                    seenRoleTags[player] = true
                                    local tag: BillboardGui? = roleTags[player]
                                    if not tag or not tag.Parent or tag.Adornee ~= head then
                                        if tag then pcall(tag.Destroy, tag) end
                                        local billboard: BillboardGui = Instance.new("BillboardGui")
                                        billboard.Name = "Wurst_RoleTag"
                                        billboard.AlwaysOnTop = true
                                        billboard.LightInfluence = 0
                                        billboard.Size = UDim2.fromOffset(170, 24)
                                        billboard.StudsOffset = Vector3.new(0, 2.7, 0)
                                        billboard.MaxDistance = 1500
                                        billboard.Adornee = head
                                        billboard.Parent = head

                                        local label: TextLabel = Instance.new("TextLabel")
                                        label.Name = "Role"
                                        label.BackgroundTransparency = 1
                                        label.Size = UDim2.fromScale(1, 1)
                                        label.Font = Enum.Font.GothamBold
                                        label.TextSize = 14
                                        label.TextScaled = false
                                        label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
                                        label.TextStrokeTransparency = 0.2
                                        label.Parent = billboard

                                        roleTags[player] = billboard
                                        tag = billboard
                                    end
                                    local label: any = tag and tag:FindFirstChild("Role")
                                    if label then
                                        local roleUpper: string = string.upper(role)
                                        if label.Text ~= roleUpper then
                                            label.Text = roleUpper
                                        end
                                        if type(gameBridge.playerRoleColor) == "function" then
                                            local okColor: boolean, color: any = pcall(gameBridge.playerRoleColor, player)
                                            if okColor and typeof(color) == "Color3" then
                                                if label.TextColor3 ~= color then
                                                    label.TextColor3 = color
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    for player: Player, tag: BillboardGui in pairs(roleTags) do
                        if not seenRoleTags[player] then
                            roleTags[player] = nil
                            pcall(tag.Destroy, tag)
                        end
                    end
                else
                    clearRoleTags()
                end

                syncMM2Extras(true)
                card:SetStatus(tostring(count))
            end)
            card:Clean(clear)
        end,
    })

    card:CreateColor({Name = "Fill colour", Default = Color3.fromRGB(150, 230, 255)})
    card:CreateColor({Name = "Outline colour", Default = Color3.fromRGB(235, 250, 255)})
    card:CreateSlider({Name = "Fill transparency", Min = 0, Max = 1, Step = 0.05, Default = 0.55})
    card:CreateSlider({Name = "Outline transparency", Min = 0, Max = 1, Step = 0.05, Default = 0})
    card:CreateToggle({Name = "Through walls", Default = true})
    card:CreateToggle({Name = "Teammates", Default = false})
    card:CreateToggle({Name = "Team colours", Default = true})
    card:CreateToggle({Name = "Murder tag", Default = true})
    card:CreateToggle({Name = "Role tags", Default = true})
    card:CreateToggle({Name = "Show Perk", Default = true})
    card:CreateToggle({Name = "Gun ESP", Default = true})
    card:CreateToggle({Name = "Trap ESP", Default = true})

    activeCard = card
    Module.Initialized = true
    return card
end

function Module.destroy(): ()
    if activeCard and activeCard.Enabled then
        activeCard:Toggle(false)
    end
    if activeBridgeCleanup then
        pcall(activeBridgeCleanup)
        activeBridgeCleanup = nil
    end
    activeCard = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/FieldOfView.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "FieldOfView",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local TaskManager: any = host.TaskManager
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local fovOwnership: any = context.services.fovOwnership
    local createUniversalFeature: any = host.createUniversalFeature
    local addNumberOption: any = host.addNumberOption
    local workspace: any = host.workspace
    local fovSettings = {value = 90}
    local FovFeature: any = nil

    local function toggleFov(enabled)
        disconnectFeatureConnection("FOV")
        fovOwnership.set("Universal", enabled and fovSettings.value or nil)
        if not enabled then
            if FovFeature then FovFeature:SetStatus(nil) end
            return
        end

        FovFeature:SetStatus(tostring(math.round(fovSettings.value)))
        featureConnections.FOV = TaskManager:Connect(function()
            fovOwnership.set("Universal", fovSettings.value)
            fovOwnership.apply(workspace.CurrentCamera)
        end)
    end

    FovFeature = createUniversalFeature(
        "FOV",
        "Keep the camera field of view fixed",
        10,
        toggleFov,
        {categoryName = "Render"}
    )
    addNumberOption(FovFeature, "Field of view", fovSettings.value, 20, 120, function(value)
        fovSettings.value = value
        if FovFeature.enabled then
            FovFeature:SetStatus(tostring(math.round(value)))
        end
    end)

    activeCleanup = function(): ()
        disconnectFeatureConnection("FOV")
        fovOwnership.set("Universal", nil)
    end
    Module.Initialized = true
    return FovFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/Fullbright.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "Fullbright",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local createUniversalFeature: any = host.createUniversalFeature
    local addNumberOption: any = host.addNumberOption
    local Lighting: any = host.Lighting
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local featureConnections: any = host.featureConnections
    local TaskManager: any = host.TaskManager

    local fullbrightSettings = {
        brightness = 3,
        clockTime = 14,
    }
    local originalLighting: any = nil

    local function toggleFullbright(enabled: boolean): ()
        disconnectFeatureConnection("Fullbright")

        if not enabled then
            if originalLighting then
                Lighting.Brightness = originalLighting.brightness
                Lighting.ClockTime = originalLighting.clockTime
                Lighting.GlobalShadows = originalLighting.globalShadows
                Lighting.FogEnd = originalLighting.fogEnd
                Lighting.Ambient = originalLighting.ambient
                Lighting.OutdoorAmbient = originalLighting.outdoorAmbient
            end
            return
        end

        originalLighting = {
            brightness = Lighting.Brightness,
            clockTime = Lighting.ClockTime,
            globalShadows = Lighting.GlobalShadows,
            fogEnd = Lighting.FogEnd,
            ambient = Lighting.Ambient,
            outdoorAmbient = Lighting.OutdoorAmbient,
        }

        featureConnections.Fullbright = TaskManager:Connect(function()
            Lighting.Brightness = fullbrightSettings.brightness
            Lighting.ClockTime = fullbrightSettings.clockTime
            Lighting.GlobalShadows = false
            Lighting.FogEnd = 100000
            Lighting.Ambient = Color3.fromRGB(178, 178, 178)
            Lighting.OutdoorAmbient = Color3.fromRGB(178, 178, 178)
        end)
    end

    local FullbrightFeature = createUniversalFeature(
        "Fullbright",
        "Keep the scene bright and remove global shadows",
        15,
        toggleFullbright,
        {categoryName = "Render"}
    )
    addNumberOption(
        FullbrightFeature,
        "Brightness",
        fullbrightSettings.brightness,
        0,
        10,
        function(value)
            fullbrightSettings.brightness = value
        end
    )
    addNumberOption(
        FullbrightFeature,
        "Clock time",
        fullbrightSettings.clockTime,
        0,
        24,
        function(value)
            fullbrightSettings.clockTime = value
        end
    )

    activeCleanup = function(): ()
        toggleFullbright(false)
    end
    Module.Initialized = true
    return FullbrightFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/ItemRender.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    render: any,
}

local Module = {
    Name = "ItemRender",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
    layer = nil :: Frame?,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local framework: any = context.framework
    local localPlayer: Player = host.LocalPlayer
    local userInput: UserInputService = host.UserInputService
    local currentWorkspace: Workspace = host.workspace or workspace
    local menu: any = context.services.menu

    local tracked: {[Instance]: boolean} = {}

    local index: {Instance} = {}
    local indexConnections: {RBXScriptConnection} = {}
    local indexDirty: boolean = true

    local known: {string} = {}
    local wanted: {string} = {}
    local picking: boolean = false

    local function release(instance: Instance): ()
        if not tracked[instance] then
            return
        end
        tracked[instance] = nil
        local renderLib: any = context.render
        if renderLib and Module.layer then
            renderLib:Release(Module.layer, instance)
        end
    end

    local function releaseAll(): ()
        for instance: Instance in pairs(tracked) do
            release(instance)
        end
    end

    local function nameMatches(name: string): boolean
        local lowered: string = string.lower(name)
        for _, entry: string in ipairs(wanted) do
            if string.find(lowered, string.lower(entry), 1, true) then
                return true
            end
        end
        return false
    end

    local function rebuildIndex(): ()
        table.clear(index)
        indexDirty = false
        if #wanted == 0 then
            return
        end
        for _, descendant: Instance in ipairs(currentWorkspace:GetDescendants()) do
            if descendant:IsA("BasePart") or descendant:IsA("Model") then
                if nameMatches(descendant.Name) then
                    table.insert(index, descendant)
                end
            end
        end
    end

    local function watchWorkspace(): ()
        table.insert(
            indexConnections,
            currentWorkspace.DescendantAdded:Connect(function(descendant: Instance): ()
                if #wanted == 0 then
                    return
                end
                if not descendant:IsA("BasePart") and not descendant:IsA("Model") then
                    return
                end
                if nameMatches(descendant.Name) then
                    table.insert(index, descendant)
                end
            end)
        )
        table.insert(
            indexConnections,
            currentWorkspace.DescendantRemoving:Connect(function(descendant: Instance): ()
                local position: number? = table.find(index, descendant)
                if position then
                    table.remove(index, position)
                end
            end)
        )
    end

    local renderLib: any = context.render
    local layer: Frame? = renderLib and renderLib:Layer("ItemRenderLayer") or nil
    Module.layer = layer

    local render: any
    render = framework.Categories.Visuals:CreateModule({
        Name = "ItemESP",
        Category = "Render",
        ConfigKey = "Universal.ItemRender",
        Order = 2,
        Tooltip = "Names and outlines every object on the list, wherever it is.",
        Function = function(enabled: boolean): ()
            if layer then
                layer.Visible = enabled
            end
            if not enabled then
                render:SetStatus(nil)
                releaseAll()
                picking = false
                return
            end
            render:SetStatus("0")
            render:Clean(function(): ()
                releaseAll()
                picking = false
                if layer then
                    layer.Visible = false
                end
            end)
            indexDirty = true
            watchWorkspace()
            render:Clean(function(): ()
                for _, connection: RBXScriptConnection in ipairs(indexConnections) do
                    pcall(function(): ()
                        connection:Disconnect()
                    end)
                end
                indexConnections = {}
                table.clear(index)
            end)
            render:Render(function(): ()
                if indexDirty then
                    rebuildIndex()
                end
                Module.render(context, render, tracked, wanted, release, index)
            end)
        end,
    })

    local objectList: any
    objectList = render:CreateList({
        Name = "Objects",
        Items = function(): {string}
            return known
        end,
        Tooltip = "Every object the module knows about. Tick the ones to draw.",
        Function = function(_selected: any, names: {string}): ()
            wanted = names
            indexDirty = true
            releaseAll()
        end,
    })

    local function learn(name: string): ()
        if name == "" then
            return
        end
        if not table.find(known, name) then
            table.insert(known, name)
            table.sort(known)
        end
        objectList:Set(name, true)
    end

    local function findBestMatchingName(query: string): string?
        local lowered: string = string.lower(query)
        local candidates: {string} = {}
        for _, descendant: Instance in ipairs(currentWorkspace:GetDescendants()) do
            if descendant:IsA("BasePart") or descendant:IsA("Model") or descendant:IsA("Tool") then
                local dName: string = descendant.Name
                local dLower: string = string.lower(dName)
                if dLower == lowered then
                    return dName
                end
                if string.find(dLower, lowered, 1, true) then
                    table.insert(candidates, dName)
                end
            end
        end
        for _, c: string in ipairs(candidates) do
            if string.find(string.lower(c), "^" .. lowered) then
                return c
            end
        end
        if #candidates > 0 then
            return candidates[1]
        end
        return nil
    end

    local pendingInput: string = ""
    local addBox: any

    local function commitAddByName(rawText: string?): ()
        local text: string = rawText or pendingInput
        local trimmed: string = string.match(text, "^%s*(.-)%s*$") or text
        if trimmed == "" or #trimmed < 2 then
            return
        end
        local best: string = findBestMatchingName(trimmed) or trimmed
        learn(best)
        render:Notify("Added: " .. best)
        pendingInput = ""
        if addBox and addBox.Object and typeof(addBox.Object) == "Instance" and addBox.Object:IsA("TextBox") then
            addBox.Object.Text = ""
        end
    end

    addBox = render:CreateTextBox({
        Name = "Add by name",
        Default = "",
        Tooltip = "Type a name and press Enter (or click Add Object). Finds closest matching items.",
        Function = function(value: string): ()
            pendingInput = value
        end,
    })

    if addBox and addBox.Object and typeof(addBox.Object) == "Instance" and addBox.Object:IsA("TextBox") then
        local box: TextBox = addBox.Object
        box.FocusLost:Connect(function(enterPressed: boolean)
            if enterPressed then
                commitAddByName(box.Text)
            end
        end)
    end

    render:CreateButton({
        Name = "Add object",
        Tooltip = "Adds the name typed above to the list.",
        Function = function(): ()
            local text: string = (addBox.Object and addBox.Object.Text) or pendingInput
            commitAddByName(text)
        end,
    })

    local function resolveItemInstance(part: BasePart): Instance
        local tool: Tool? = part:FindFirstAncestorOfClass("Tool")
        if tool then
            return tool
        end
        local parent: Instance? = part.Parent
        if parent and parent:IsA("Model") and parent ~= currentWorkspace then
            local parentNameLower: string = string.lower(parent.Name)
            local isGenericMap: boolean = parentNameLower == "map"
                or parentNameLower == "workspace"
                or parentNameLower == "geometry"
                or parentNameLower == "spawns"
                or parentNameLower == "terrain"
                or parentNameLower == "baseplate"
            local childCount: number = #parent:GetChildren()
            if not isGenericMap and childCount <= 15 then
                return parent
            end
        end
        return part
    end

    render:CreateButton({
        Name = "Touch part",
        Tooltip = "Hides the menu, then adds whatever you tap next.",
        Function = function(): ()
            if picking then
                picking = false
                render:Notify("cancelled")
                return
            end
            picking = true

            menu.setVisible(false)
            render:Notify("tap the object you want rendered")
        end,
    })

    render:CreateButton({
        Name = "Clear list",
        Function = function(): ()
            for _, name: string in ipairs(known) do
                objectList:Set(name, false)
            end
            table.clear(known)
            wanted = {}
            objectList:Refresh()
            releaseAll()
            render:Notify("list cleared")
        end,
    })

    render:CreateToggle({
        Name = "Show distance",
        Default = true,
    })
    render:CreateToggle({
        Name = "Outline",
        Default = true,
        Tooltip = "Draw the object's silhouette through walls.",
    })
    render:CreateSlider({
        Name = "Max distance",
        Min = 50,
        Max = 5000,
        Default = 1200,
    })
    render:CreateSlider({
        Name = "Text size",
        Min = 8,
        Max = 22,
        Default = 12,
    })
    render:CreateColor({
        Name = "Colour",
        Default = Color3.fromRGB(232, 232, 236),
    })

    local pickConnection: RBXScriptConnection = userInput.InputBegan:Connect(
        function(input: InputObject, processed: boolean): ()
            if not picking or processed then
                return
            end
            if input.UserInputType ~= Enum.UserInputType.Touch
                and input.UserInputType ~= Enum.UserInputType.MouseButton1 then
                return
            end
            local camera: Camera? = currentWorkspace.CurrentCamera
            if not camera then
                return
            end

            local ray: Ray = (camera :: Camera):ScreenPointToRay(
                input.Position.X,
                input.Position.Y
            )
            local parameters: RaycastParams = RaycastParams.new()
            parameters.FilterType = Enum.RaycastFilterType.Exclude
            parameters.IgnoreWater = true
            parameters.FilterDescendantsInstances = {
                localPlayer.Character :: any,
                camera,
            }
            local result: RaycastResult? = currentWorkspace:Raycast(
                ray.Origin,
                ray.Direction.Unit * 4096,
                parameters
            )
            if not result then
                render:Notify("nothing under that tap")
                return
            end
            picking = false

            local hit: Instance = (result :: RaycastResult).Instance
            if not hit:IsA("BasePart") then
                render:Notify("invalid part tapped")
                menu.setVisible(true)
                return
            end
            local targetItem: Instance = resolveItemInstance(hit :: BasePart)
            local name: string = targetItem.Name
            learn(name)
            menu.setVisible(true)
            render:Notify(name .. " added")
        end
    )

    render:CreateNote(
        "Every object sharing the name is rendered, not just the one you tapped."
    )

    activeCleanup = function(): ()
        picking = false
        pcall(function(): ()
            pickConnection:Disconnect()
        end)
        releaseAll()
    end
    Module.Initialized = true
    return render
end

function Module.render(
    context: Runtime,
    render: any,
    tracked: {[Instance]: any},
    wanted: {string},
    release: (Instance) -> (),
    index: {Instance}
): ()
    local host: any = context.host
    local renderLib: any = context.render
    local layer: Frame? = Module.layer
    local localPlayer: Player = host.LocalPlayer
    local options: any = render.Options
    local currentWorkspace: Workspace = host.workspace or workspace
    local camera: Camera? = currentWorkspace.CurrentCamera

    if #wanted == 0 or not renderLib or not layer or not camera then
        for instance: Instance in pairs(tracked) do
            release(instance)
        end
        return
    end

    local resolvedCamera: Camera = camera :: Camera
    local resolvedLayer: Frame = layer :: Frame
    local character: Model? = localPlayer.Character
    local root: BasePart? = character
        and character:FindFirstChild("HumanoidRootPart") :: BasePart?
    local origin: Vector3 = root and (root :: BasePart).Position or Vector3.zero
    local maxDistance: number = options["Max distance"].Value
    local colour: Color3 = options["Colour"].Value
    local textSize: number = math.round(options["Text size"].Value)
    local seen: {[Instance]: boolean} = {}

    local function lowerMatch(name: string): boolean
        local lowered: string = string.lower(name)
        for _, entry: string in ipairs(wanted) do
            if string.find(lowered, string.lower(entry), 1, true) then
                return true
            end
        end
        return false
    end

    for _, descendant: Instance in ipairs(index) do
        if not descendant.Parent then
            continue
        end
        local isPart: boolean = descendant:IsA("BasePart")
        local isModel: boolean = descendant:IsA("Model")
        if not isPart and not isModel then
            continue
        end
        if character and descendant:IsDescendantOf(character) then
            continue
        end
        if not lowerMatch(descendant.Name) then
            continue
        end
        if isPart and descendant:FindFirstAncestorOfClass("Model") then
            local ancestor: Instance? = descendant:FindFirstAncestorOfClass("Model")
            if ancestor and lowerMatch(ancestor.Name) then
                continue
            end
        end

        local anchor: BasePart? = nil
        if isPart then
            anchor = descendant :: BasePart
        else
            anchor = (descendant :: Model).PrimaryPart
                or (descendant :: Model):FindFirstChildWhichIsA("BasePart")
        end
        if not anchor then
            continue
        end
        local resolvedAnchor: BasePart = anchor :: BasePart
        local distance: number = (resolvedAnchor.Position - origin).Magnitude
        if distance > maxDistance then
            continue
        end
        local projected: Vector2? = renderLib:Project(resolvedCamera, resolvedAnchor.Position)
        if not projected then
            continue
        end

        seen[descendant] = true
        tracked[descendant] = true
        local drawings: any = renderLib:Set(resolvedLayer, descendant)
        drawings:Show(true)
        drawings:Label(
            "NameTag",
            options["Show distance"].Value
                    and (descendant.Name .. "  " .. tostring(math.round(distance)) .. "m")
                or descendant.Name,
            projected :: Vector2,
            0.5,
            textSize,
            colour,
            true
        )
        drawings:Highlight(
            descendant,
            colour,
            1,
            options["Outline"].Value and "Outline" or "Off"
        )
    end

    local count: number = 0
    for instance: Instance in pairs(tracked) do
        if not seen[instance] or not instance.Parent then
            release(instance)
        else
            count += 1
        end
    end
    local status: string = tostring(count)
    if render.Status ~= status then
        render:SetStatus(status)
    end
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.layer = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/NPCESP.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    render: any,
    host: any,
    services: any,
}

local Module = {
    Name = "NPCESP",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCard: any = nil

local STANDARD_PART_NAMES: {[string]: boolean} = {
    head = true,
    torso = true,
    uppertorso = true,
    lowertorso = true,
    humanoidrootpart = true,
    leftarm = true,
    rightarm = true,
    leftleg = true,
    rightleg = true,
    leftupperarm = true,
    leftlowerarm = true,
    lefthand = true,
    rightupperarm = true,
    rightlowerarm = true,
    righthand = true,
    leftupperleg = true,
    leftlowerleg = true,
    leftfoot = true,
    rightupperleg = true,
    rightlowerleg = true,
    rightfoot = true,
}

local VERDICT_COOLDOWN: number = 0.5

local function normalizeName(value: string): string
    local normalized: string = string.lower(value):gsub("[%s_%-]", "")
    return normalized
end

function Module.init(context: Runtime): any
    local framework: any = context.framework
    local render: any = context.render
    local host: any = context.host
    local players: Players = host.Players
    local currentWorkspace: Workspace = host.workspace or workspace
    local layer: Frame = render:Layer("NpcEspLayer")
    local lastStatusAt: number = -math.huge
    local lastSweepAt: number = -math.huge

    local bots: {[Model]: boolean} = {}
    local rigInfo: any = setmetatable({}, {__mode = "k"})
    local verdicts: any = setmetatable({}, {__mode = "k"})
    local forcedNames: {string} = {}

    local function modelFor(instance: Instance): Model?
        if instance:IsA("Model") then
            return instance :: Model
        end
        return instance:FindFirstAncestorOfClass("Model") :: Model?
    end

    local function isPlayerCharacterModel(model: Model): boolean
        if players:GetPlayerFromCharacter(model) ~= nil then
            return true
        end
        for _, player: Player in ipairs(players:GetPlayers()) do
            local character: Model? = player.Character
            if character and model:IsDescendantOf(character) then
                return true
            end
        end
        return false
    end

    local function matchesForcedName(model: Model): boolean
        local name: string = string.lower(model.Name)
        for _, needle: string in ipairs(forcedNames) do
            if needle ~= "" and string.find(name, needle, 1, true) then
                return true
            end
        end
        return false
    end

    local function classify(model: Model): string

        if model:GetAttribute("WurstDisguise") == true then
            return "reject"
        end
        if matchesForcedName(model) then
            return "rig"
        end
        local humanoid: Humanoid? = model:FindFirstChildOfClass("Humanoid") :: Humanoid?
        local standardParts: number = 0
        local motors: number = 0
        for _, child: Instance in ipairs(model:GetChildren()) do
            if child:IsA("BasePart") then
                if STANDARD_PART_NAMES[normalizeName(child.Name)] then
                    standardParts += 1
                end
            elseif child:IsA("Motor6D") then
                motors += 1
            end
        end
        if humanoid ~= nil then

            if standardParts >= 3 then
                return "rig"
            end
            return "creature"
        end

        if standardParts >= 4 or (standardParts >= 3 and motors >= 2) then
            return "rig"
        end
        if model:FindFirstChildWhichIsA("Humanoid", true) ~= nil then
            return "creature"
        end
        return "reject"
    end

    local function verdictFor(model: Model): string
        local entry: any = verdicts[model]
        if entry == nil then
            entry = {
                verdict = isPlayerCharacterModel(model) and "reject" or classify(model),
                at = os.clock(),
                dirty = false,
            }
            verdicts[model] = entry
            return entry.verdict
        end
        if entry.dirty then
            local now: number = os.clock()
            if now - entry.at >= VERDICT_COOLDOWN then
                entry.verdict =
                    isPlayerCharacterModel(model) and "reject" or classify(model)
                entry.at = now
                entry.dirty = false
            end
        end
        return entry.verdict
    end

    local function markDirty(model: Model): ()
        local entry: any = verdicts[model]
        if entry and not entry.dirty then
            entry.dirty = true
        end
        rigInfo[model] = nil
    end

    local function invalidate(instance: Instance): ()
        local parent: Instance? = instance.Parent
        if parent and parent:IsA("Model") then
            markDirty(parent :: Model)
        end
        if instance:IsA("Model") then
            markDirty(instance :: Model)
        end
    end

    local function add(model: Model, verdict: string): ()
        if verdict ~= "rig" then
            bots[model] = true
            return
        end

        for existing: Model in pairs(bots) do
            if existing:IsDescendantOf(model) then
                return
            end
            if model:IsDescendantOf(existing) then
                bots[existing] = nil
                render:Release(layer, existing)
            end
        end
        bots[model] = true
    end

    local function inspect(instance: Instance): ()
        if not (instance:IsA("Model") or instance:IsA("Humanoid")
            or instance:IsA("BasePart") or instance:IsA("Motor6D")) then
            return
        end
        invalidate(instance)
        local model: Model? = modelFor(instance)
        local creature: Model? = nil
        while model and model ~= currentWorkspace do
            local verdict: string = verdictFor(model)
            if verdict == "rig" then
                add(model, "rig")
                return
            end
            if verdict == "creature" and creature == nil then
                creature = model
            end
            local parent: Instance? = model.Parent
            if not parent then
                break
            end
            model = parent:IsA("Model") and parent :: Model
                or parent:FindFirstAncestorOfClass("Model") :: Model?
        end
        if creature then
            add(creature, "creature")
        end
    end

    local function sweep(now: number): ()
        for model: any, entry: any in pairs(verdicts) do
            if entry.dirty and now - entry.at >= VERDICT_COOLDOWN then
                local resolved: Model = model :: Model
                local verdict: string =
                    isPlayerCharacterModel(resolved) and "reject" or classify(resolved)
                entry.verdict = verdict
                entry.at = now
                entry.dirty = false
                if verdict == "rig" then
                    add(resolved, "rig")
                end
            end
        end
    end

    local function scan(): ()
        table.clear(bots)
        for _, object: Instance in ipairs(currentWorkspace:GetDescendants()) do
            if object:IsA("Model") then
                inspect(object)
            end
        end
    end

    local function clear(): ()
        render:ReleaseAll(layer)
        table.clear(bots)
        layer.Visible = false
    end

    local card: any
    card = framework.Categories.Visuals:CreateModule({
        Name = "NPCESP",
        Category = "Render",
        ConfigKey = "Universal.NPCESP",
        Order = 4,
        Tooltip = "Displays character-shaped NPC models - bots, shopkeepers "
            .. "and display statues like the creator's rig - whether or not "
            .. "their Humanoid is alive.",
        Function = function(enabled: boolean): ()
            layer.Visible = enabled
            if not enabled then
                clear()
                card:SetStatus(nil)
                return
            end
            scan()
            card:Event(currentWorkspace.DescendantAdded, inspect)
            card:Event(currentWorkspace.DescendantRemoving, invalidate)
            card:Render(function(): ()
                local camera: Camera? = currentWorkspace.CurrentCamera
                if not camera then
                    return
                end
                local resolvedCamera: Camera = camera :: Camera
                local now: number = os.clock()
                if now - lastSweepAt >= 1 then
                    lastSweepAt = now
                    sweep(now)
                end

                local maxDistance: number = card.Options["Max distance"].Value
                local includeCreatures: boolean = card.Options["All humanoids"].Value
                local localCharacter: Model? = host.LocalPlayer.Character
                local localRoot: BasePart? = localCharacter and (
                    localCharacter:FindFirstChild("HumanoidRootPart") :: BasePart?
                    or localCharacter.PrimaryPart
                    or localCharacter:FindFirstChildWhichIsA("BasePart", true) :: BasePart?
                ) or nil
                local origin: Vector3 = localRoot and localRoot.Position
                    or resolvedCamera.CFrame.Position
                local count: number = 0
                for model: Model in pairs(bots) do
                    if not model:IsDescendantOf(currentWorkspace)
                        or players:GetPlayerFromCharacter(model) ~= nil then
                        bots[model] = nil
                        render:Release(layer, model)

                        verdicts[model] = {verdict = "reject", at = now, dirty = false}
                        continue
                    end
                    local verdict: string = verdictFor(model)
                    if verdict == "reject" then
                        bots[model] = nil
                        render:Release(layer, model)
                        continue
                    end

                    if verdict == "creature" and not includeCreatures then

                        render:Release(layer, model)
                        continue
                    end

                    local drawing: any = render:Set(layer, model)

                    local info: any = rigInfo[model]
                    if not (info and info.root and info.root.Parent) then
                        info = {
                            root = model:FindFirstChild("HumanoidRootPart") :: BasePart?
                                or model.PrimaryPart
                                or model:FindFirstChildWhichIsA("BasePart", true) :: BasePart?,
                            humanoid = model:FindFirstChildOfClass("Humanoid") :: Humanoid?
                                or model:FindFirstChildWhichIsA("Humanoid", true) :: Humanoid?,
                        }
                        rigInfo[model] = info
                    end
                    local root: BasePart? = info.root
                    if not root or (root.Position - origin).Magnitude > maxDistance then
                        drawing:Show(false)
                        continue
                    end

                    if verdict == "creature"
                        and info.humanoid
                        and info.humanoid.Health <= 0 then
                        drawing:Show(false)
                        continue
                    end

                    local rect: any = render:ModelRect(resolvedCamera, model)
                    if not rect then
                        drawing:Show(false)
                        continue
                    end

                    local colour: Color3 = card.Options["Colour"].Value
                    drawing:Box(rect, card.Options["Box"].Value and "Full" or "Off", 1, colour)
                    if card.Options["Name"].Value then
                        local text: string = card.Options["Model name"].Value
                            and model.Name ~= "" and model.Name
                            or "BOT"
                        local humanoid: Humanoid? = info.humanoid
                        if humanoid and card.Options["Health"].Value then
                            text ..= " [" .. tostring(math.round(humanoid.Health)) .. "]"
                        end
                        drawing:Label(
                            "NameTag",
                            text,
                            Vector2.new(rect.centreX, rect.top - 4),
                            1,
                            13,
                            colour,
                            true
                        )
                    else
                        drawing:HideLabel("NameTag")
                    end
                    drawing:Highlight(
                        model,
                        colour,
                        0.55,
                        not card.Options["Highlight"].Value and "Off"
                            or (card.Options["Through walls"].Value and "AlwaysOnTop" or "Occluded")
                    )
                    drawing:Show(true)
                    count += 1
                end

                if now - lastStatusAt >= 0.25 then
                    lastStatusAt = now
                    card:SetStatus(tostring(count))
                end
            end)
            card:Clean(clear)
        end,
    })

    card:CreateToggle({Name = "Box", Default = true})
    card:CreateToggle({Name = "Highlight", Default = true})
    card:CreateToggle({Name = "Through walls", Default = true, Show = {Option = "Highlight"}})
    card:CreateToggle({Name = "Name", Default = true})
    card:CreateToggle({
        Name = "Model name",
        Show = {Option = "Name"},
        Default = false,
        Tooltip = "Label each model with its own name instead of BOT.",
    })
    card:CreateToggle({
        Name = "Health",
        Show = {Option = "Name"},
        Default = true,
        Tooltip = "Append the Humanoid's hit points to the label when the "
            .. "model has one.",
    })
    card:CreateToggle({
        Name = "All humanoids",
        Default = false,
        Tooltip = "Also flag non-character models that merely carry a living "
            .. "Humanoid (creatures, monsters). Off by default: NPCESP tracks "
            .. "character-shaped rigs.",
    })
    card:CreateColor({Name = "Colour", Default = Color3.new(1, 1, 1)})
    card:CreateSlider({Name = "Max distance", Min = 25, Max = 2000, Step = 25, Default = 500})

    local addBox: any
    addBox = card:CreateTextBox({
        Name = "Force by name",
        Default = "",
        Tooltip = "Type a model name and it is always treated as an NPC rig, "
            .. "whatever it is built from. Partial names match, so statue "
            .. "catches CreatorStatue.",
        Function = function(value: string): ()
            local trimmed: string = string.match(value, "^%s*(.-)%s*$") or value
            if trimmed == "" then
                return
            end
            local needle: string = string.lower(trimmed)
            if not table.find(forcedNames, needle) then
                table.insert(forcedNames, needle)
            end
            table.clear(verdicts)
            table.clear(rigInfo)
            if card.Enabled then
                scan()
            end
            addBox:Set("")
        end,
    })

    card:CreateButton({
        Name = "Clear forced names",
        Function = function(): ()
            table.clear(forcedNames)
            table.clear(verdicts)
            table.clear(rigInfo)
            if card.Enabled then
                scan()
            end
        end,
    })

    activeCard = card
    Module.Initialized = true
    return card
end

function Module.destroy(): ()
    if activeCard and activeCard.Enabled then
        activeCard:Toggle(false)
    end
    activeCard = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/PlayerESP.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "PlayerESP",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local framework: any = context.framework
    local players: Players = host.Players

    local render: any = context.render

    local container: Frame = render:Layer("PlayerEspLayer")
    local pool: {[Player]: boolean} = {}
    local lastStatusAt: number = -math.huge
    local visibilityCache: any = setmetatable({}, {__mode = "k"})

    local esp: any
    esp = framework.Categories.Visuals:CreateModule({
        Name = "PlayerESP",
        Category = "Render",
        ConfigKey = "Universal.PlayerESP",
        Order = 1,
        Tooltip = "Boxes, skeletons, name tags, health, tracers and chams, "
            .. "each independently switchable.",
        Function = function(enabled: boolean): ()
            container.Visible = enabled
            if not enabled then
                esp:SetStatus(nil)
                render:ReleaseAll(container)
                table.clear(pool)
                return
            end
            lastStatusAt = -math.huge
            esp:SetStatus("0")
            esp:Render(function(): ()
                Module.render(context, container, pool, esp, visibilityCache)
                local now: number = os.clock()
                if now - lastStatusAt >= 0.25 then
                    lastStatusAt = now
                    local count: number = 0
                    for _player: Player in pairs(pool) do
                        count += 1
                    end
                    esp:SetStatus(tostring(count))
                end
            end)
            esp:Event(players.PlayerRemoving, function(player: Player): ()
                render:Release(container, player)
                pool[player] = nil
            end)
            esp:Clean(function(): ()
                render:ReleaseAll(container)
                table.clear(pool)
                container.Visible = false
            end)
        end,
    })

    esp:CreateDropdown({
        Name = "Boxes",
        List = {"Corner", "Full", "Off"},
        Index = 1,
        Tooltip = "Corner draws four brackets, Full draws the whole rectangle.",
    })
    esp:CreateSlider({
        Name = "Box thickness",
        Show = {Option = "Boxes", Values = {"Corner", "Full"}},
        Min = 1,
        Max = 5,
        Default = 1,
    })
    esp:CreateToggle({
        Name = "Filled box",
        Show = {Option = "Boxes", Values = {"Corner", "Full"}},
        Default = false,
        Tooltip = "Wash the inside of the box in the target's colour. Reads "
            .. "at a glance across a map; noisy in a crowd.",
    })
    esp:CreateToggle({
        Name = "Skeleton",
        Default = false,
        Tooltip = "Draw the rig's bones. Works on both R6 and R15.",
    })
    esp:CreateToggle({
        Name = "Name tags",
        Default = true,
        Tooltip = "The player's name above the box.",
    })
    esp:CreateToggle({
        Name = "Display name",
        Show = {Option = "Name tags"},
        Default = true,
        Tooltip = "Show the display name rather than the account name.",
    })
    esp:CreateToggle({
        Name = "Health bar",
        Default = true,
        Tooltip = "Vertical bar on the left edge of the box.",
    })
    esp:CreateToggle({
        Name = "Health text",
        Default = false,
        Tooltip = "Print the exact hit points next to the name.",
    })
    esp:CreateToggle({
        Name = "Distance",
        Default = true,
        Tooltip = "Studs between you and the target.",
    })
    esp:CreateToggle({
        Name = "Held tool",
        Default = false,
        Tooltip = "Name of whatever the target currently has equipped.",
    })
    esp:CreateDropdown({
        Name = "Tracers",
        List = {"Off", "Bottom", "Centre", "Cursor"},
        Index = 1,
        Tooltip = "Where the line to each target starts.",
    })
    esp:CreateToggle({
        Name = "Team check",
        Default = false,
        Tooltip = "Skip players on your own team.",
    })
    esp:CreateToggle({
        Name = "Visibility check",
        Default = false,
        Tooltip = "Recolour targets that are behind geometry.",
    })
    esp:CreateSlider({
        Name = "Max distance",
        Min = 50,
        Max = 5000,
        Default = 2000,
    })

    esp:CreateColor({
        Name = "Colour",
        Default = Color3.fromRGB(255, 255, 255),
        Tooltip = "Used for every target the game gives no colour of its own.",
    })
    esp:CreateToggle({
        Name = "Team colours",
        Default = true,
        Tooltip = "Draw each player in their own team's colour where the game "
            .. "has teams.",
    })
    esp:CreateToggle({
        Name = "Name plate",
        Default = true,
        Tooltip = "Put the name on a dark plate so it stays readable against "
            .. "a bright map.",
    })
    esp:CreateSlider({
        Name = "Text size",
        Min = 8,
        Max = 24,
        Default = 13,
    })

    local extraRuntime: any = {
        roles = nil :: any,
        extras = {} :: {any},
    }
    Module.bridge = extraRuntime

    local function addRoleRows(provider: any): ()
        if extraRuntime.roles then
            return
        end
        extraRuntime.roles = provider

        for _, redundant: string in
            ipairs({"Team check", "Visibility check", "Team colours", "Colour"})
        do
            local row: any = esp.Options[redundant]
            if row then

                row.Show = {Option = "__roles", Values = {true}}
                pcall(function(): ()
                    row:SetVisible(false)
                    row.Visible = false
                end)
            end
        end
        esp:CreateToggle({
            Name = "Role colours",
            Default = true,
            Tooltip = "Colour every drawing by what the player is in this "
                .. "game instead of by team.",
        })
        esp:CreateToggle({
            Name = "Show role",
            Show = {Option = "Name tags"},
            Default = true,
            Tooltip = "Print the role next to the name.",
        })
        for _, roleName: string in ipairs(provider.Roles or {}) do
            esp:CreateColor({
                Name = roleName .. " colour",
                Default = (provider.Colors or {})[roleName]
                    or Color3.fromRGB(236, 236, 240),
                Function = function(value: Color3): ()

                    if type(provider.SetColor) == "function" then
                        pcall(provider.SetColor, roleName, value)
                    end
                end,
            })
        end
    end

    local function addExtraRows(extra: any): ()
        table.insert(extraRuntime.extras, extra)
        esp:CreateToggle({
            Name = extra.Name,
            Default = extra.Default == true,
            Tooltip = extra.Tooltip,
            Function = function(value: boolean): ()
                if type(extra.Toggle) == "function" then
                    pcall(extra.Toggle, value)
                end
            end,
        })
        if extra.Color then
            esp:CreateColor({
                Name = extra.Name .. " colour",
                Show = {Option = extra.Name},
                Default = extra.Color,
                Function = function(value: Color3): ()
                    if type(extra.SetColor) == "function" then
                        pcall(extra.SetColor, value)
                    end
                end,
            })
        end

        for _, definition: any in ipairs(extra.Options or {}) do
            local rowName: string = extra.Name .. " " .. definition.Name
            if definition.Kind == "toggle" then
                esp:CreateToggle({
                    Name = rowName,
                    Show = {Option = extra.Name},
                    Default = definition.Default == true,
                    Tooltip = definition.Tooltip,
                    Function = function(value: boolean): ()
                        if type(definition.Set) == "function" then
                            pcall(definition.Set, value)
                        end
                    end,
                })
            else
                esp:CreateSlider({
                    Name = rowName,
                    Show = {Option = extra.Name},
                    Min = definition.Min or 0,
                    Max = definition.Max or 100,
                    Default = definition.Default or definition.Min or 0,
                    Tooltip = definition.Tooltip,
                    Function = function(value: number): ()
                        if type(definition.Set) == "function" then
                            pcall(definition.Set, value)
                        end
                    end,
                })
            end
        end
    end

    local gameBridge: any = context.services.gameBridge
    if type(gameBridge.onEvent) == "function" then
        gameBridge.onEvent(function(kind: string, payload: any): ()
            if kind == "roles" then
                addRoleRows(payload)
            elseif kind == "extra" then
                addExtraRows(payload)
            end
        end)
    end

    activeCleanup = function(): ()
        render:ReleaseAll(container)
        table.clear(pool)
        container.Visible = false
    end
    Module.Initialized = true
    return esp
end

function Module.render(
    context: Runtime,
    container: Frame,
    pool: {[Player]: any},
    esp: any,
    visibilityCache: any
): ()
    local host: any = context.host
    local entityLibrary: any = context.entity
    local render: any = context.render
    local gameBridge: any = context.services.gameBridge
    local currentWorkspace: Workspace = host.workspace or workspace
    local camera: Camera? = currentWorkspace.CurrentCamera
    if not camera then
        return
    end
    local resolvedCamera: Camera = camera :: Camera
    local options: any = esp.Options
    local viewport: Vector2 = resolvedCamera.ViewportSize

    entityLibrary:Refresh()
    local seen: {[Player]: boolean} = {}

    for _, entity: any in ipairs(entityLibrary.List) do
        local player: Player = entity.Player
        if options["Team check"].Value and entity.IsFriendly then
            continue
        end
        if entity.Distance > options["Max distance"].Value then

            continue
        end

        local rect: any = render:ModelRect(resolvedCamera, entity.Character)

        seen[player] = true
        pool[player] = true
        local drawings: any = render:Set(container, player)

        if not rect then

            drawings:Show(false)
            continue
        end

        local visible: boolean = true
        if options["Visibility check"].Value then
            local cache: any = visibilityCache[player]
            local now: number = os.clock()
            if not cache or now - cache.at > 0.12 then
                cache = {at = now, value = entityLibrary:VisibleFrom(entity)}
                visibilityCache[player] = cache
            end
            visible = cache.value
        end
        local colour: Color3 = options["Colour"].Value

        local role: string? = nil
        if type(gameBridge.playerRole) == "function" then
            role = gameBridge.playerRole(player)
        end
        local roleOption: any = role and options[role .. " colour"] or nil
        local useRoleColour: boolean = roleOption ~= nil
            and options["Role colours"] ~= nil
            and options["Role colours"].Value == true
        if useRoleColour then
            colour = roleOption.Value
        end

        if not useRoleColour and options["Team colours"].Value then
            local isTeammate: boolean = entity.IsFriendly
                or (LocalPlayer and player.Team and LocalPlayer.Team and player.Team == LocalPlayer.Team)
                or (LocalPlayer and player:GetAttribute("Team") ~= nil and player:GetAttribute("Team") == LocalPlayer:GetAttribute("Team"))
            if isTeammate then
                colour = Color3.fromRGB(255, 255, 255)
            else
                colour = Color3.fromRGB(255, 0, 0)
            end
        end

        if not visible then
            colour = colour:Lerp(Color3.new(0, 0, 0), 0.45)
        end

        local left: number = rect.left
        local top: number = rect.top
        local bottom: number = rect.bottom
        local height: number = rect.height
        local centreX: number = rect.centreX

        drawings:Show(true)

        local thickness: number = math.round(options["Box thickness"].Value)
        local boxMode: string = options["Boxes"].Value
        drawings:Fill(
            options["Filled box"].Value and boxMode ~= "Off" and rect or nil,
            colour,
            0.82
        )
        drawings:Box(rect, boxMode, thickness, colour)

        if options["Skeleton"].Value then
            local bones: {{BasePart}} = entityLibrary:Rig(entity)
            for index: number = 1, 14 do
                local pair: {BasePart}? = bones[index]
                local first: Vector2? = pair
                    and render:Project(resolvedCamera, pair[1].Position)
                local second: Vector2? = pair
                    and render:Project(resolvedCamera, pair[2].Position)
                if first and second then
                    drawings:Line(
                        "Bone",
                        index,
                        first :: Vector2,
                        second :: Vector2,
                        1,
                        colour
                    )
                else
                    drawings:HideLines("Bone", index, index)
                end
            end
        else
            drawings:HideLines("Bone", 1, 14)
        end

        if options["Health bar"].Value then
            drawings:Bar(
                Vector2.new(left - 4, top),
                height,
                entity.Health / math.max(entity.MaxHealth, 1)
            )
        else
            drawings:HideBar()
        end

        local textSize: number = math.round(options["Text size"].Value)
        if options["Name tags"].Value then
            local shown: string = options["Display name"].Value
                and player.DisplayName
                or player.Name
            drawings:Label(
                "NameTag",
                (role
                        and options["Show role"] ~= nil
                        and options["Show role"].Value)
                    and (shown .. "  [" .. (role :: string) .. "]")
                    or shown,
                Vector2.new(centreX, top - 3),
                1,
                textSize,
                colour,
                options["Name plate"].Value
            )
        else
            drawings:HideLabel("NameTag")
        end

        local details: {string} = {}
        if options["Distance"].Value then
            table.insert(details, tostring(math.round(entity.Distance)) .. "m")
        end
        if options["Health text"].Value then
            table.insert(
                details,
                tostring(math.round(entity.Health))
                    .. "/"
                    .. tostring(math.round(entity.MaxHealth))
            )
        end
        if options["Held tool"].Value then
            local tool: Instance? = entity.Character:FindFirstChildOfClass("Tool")
            if tool then
                table.insert(details, tool.Name)
            end
        end
        if #details > 0 then
            drawings:Label(
                "Details",
                table.concat(details, "  "),
                Vector2.new(centreX, bottom + 2),
                0,
                math.max(textSize - 2, 8),
                colour,
                options["Name plate"].Value
            )
        else
            drawings:HideLabel("Details")
        end

        local tracerMode: string = options["Tracers"].Value
        if tracerMode == "Off" then
            drawings:HideLines("Tracer", 1, 1)
        else
            local origin: Vector2
            if tracerMode == "Bottom" then
                origin = Vector2.new(viewport.X * 0.5, viewport.Y)
            elseif tracerMode == "Centre" then
                origin = viewport * 0.5
            else
                origin = host.UserInputService:GetMouseLocation()
            end
            drawings:Line(
                "Tracer",
                1,
                origin,
                Vector2.new(centreX, bottom),
                1,
                colour
            )
        end

    end

    for player: Player in pairs(pool) do
        if not seen[player] then
            render:Release(container, player)
            pool[player] = nil
        end
    end
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/ProjectileCalibration.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
    services: any,
}

local Module = {
    Name = "ProjectileCalibration",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeController: any = nil
local activeRegistry: any = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local calibrationService: any = context.services.projectileCalibration
    local product: any = host.PRODUCT
    local notify: any = host.notify
    local createUniversalFeature: any = host.createUniversalFeature
    local addNumberOption: any = host.addNumberOption
    local addToggleOption: any = host.addToggleOption
    local addActionOption: any = host.addActionOption
    local addInformationOption: any = host.addInformationOption
    local TaskManager: any = host.TaskManager
    local LocalPlayer: any = host.LocalPlayer
    local HttpService: any = host.HttpService
    local Stats: any = host.Stats

    local controllerFactory = (function(): any
        type PendingActivation = {
            tool: Tool,
            activatedAt: number,
            origin: Vector3?,
            aim: Vector3?,
            pingMs: number,
        }
        type ProjectileSample = {
            t: number,
            position: {number},
            velocity: {number},
            speed: number,
        }
        type ProjectileTrack = {
            instance: BasePart,
            toolName: string,
            projectileName: string,
            startedAt: number,
            launchDelayMs: number,
            pingMs: number,
            origin: Vector3,
            previousAt: number?,
            previousPosition: Vector3?,
            speeds: {number},
            accelerations: {number},
            verticalAccelerations: {number},
            samples: {ProjectileSample},
            distance: number,
            destroyConnection: RBXScriptConnection?,
        }
        type BucketRecord = {
            count: number,
            speedSum: number,
            speedSquaredSum: number,
            delaySum: number,
        }
        type Controller = {
            setEnabled: (self: Controller, enabled: boolean) -> (),
            save: (self: Controller, reason: string?) -> boolean,
            delete: (self: Controller) -> boolean,
            status: (self: Controller) -> string,
            destroy: (self: Controller) -> (),
            tuning: {[string]: number},
        }

        local tuning: {[string]: number} = {
            bucketWidthMs = 5,
            maxBucketMs = 250,
            sampleWindowSeconds = 2.5,
            maxSamplesPerTrack = 150,
            minProjectileSpeed = 10,
            matchDistanceStuds = 40,
            maxPendingActivations = 10,
            candidateLifetimeSeconds = 1.1,
        }

        local executorEnvironment: {[string]: any} = getfenv() :: any
        local mouse: Mouse = LocalPlayer:GetMouse()
        local outputRoot: string = product.storageFolder
        local outputTelemetry: string = outputRoot .. "/Telemetry"
        local outputFolder: string = outputTelemetry .. "/Universal"
        local outputPath: string = outputFolder
            .. "/Place_"
            .. tostring(game.PlaceId)
            .. "_Projectile_Calibration.json"
        local runtime: any = {
            enabled = false,
            historyLoaded = false,
            dirty = false,
            startedAt = os.clock(),
            pending = {} :: {PendingActivation},
            tracks = {} :: {[BasePart]: ProjectileTrack},
            events = {} :: {{[string]: any}},
            buckets = {} :: {[string]: BucketRecord},
            connections = {} :: {RBXScriptConnection},
            observedTools = setmetatable({}, {__mode = "k"}) :: {[Tool]: boolean},
            observedCandidates = setmetatable({}, {__mode = "k"}) :: {[BasePart]: boolean},
            sampler = nil :: any,
            totalActivations = 0,
            totalProjectiles = 0,
            rejectedCandidates = 0,
        }
        local controller: Controller
        local saveSnapshot: (reason: string) -> boolean
        local finishTrack: (part: BasePart, reason: string) -> ()

        local function finite(value: number): boolean
            return value == value and value > -math.huge and value < math.huge
        end

        local function vectorArray(value: Vector3): {number}
            return {value.X, value.Y, value.Z}
        end

        local function median(values: {number}): number?
            if #values == 0 then
                return nil
            end
            local sorted: {number} = table.clone(values)
            table.sort(sorted)
            local middle: number = math.floor((#sorted + 1) / 2)
            if #sorted % 2 == 1 then
                return sorted[middle]
            end
            return (sorted[middle] + sorted[middle + 1]) * 0.5
        end

        local function pingBucketKey(pingMs: number): string
            local width: number = math.max(1, tuning.bucketWidthMs)
            local ceiling: number = math.max(width, tuning.maxBucketMs)
            if pingMs > ceiling then
                return tostring(ceiling) .. "+"
            end
            local lower: number = math.clamp(
                math.floor(pingMs / width) * width,
                0,
                math.max(0, ceiling - width)
            )
            local upper: number = lower + width
            return string.format("%03d-%03d", lower, upper)
        end

        local function ensureBucket(key: string): BucketRecord
            local existing: BucketRecord? = runtime.buckets[key]
            if existing then
                return existing
            end
            local created: BucketRecord = {
                count = 0,
                speedSum = 0,
                speedSquaredSum = 0,
                delaySum = 0,
            }
            runtime.buckets[key] = created
            return created
        end

        local function bucketPayload(): {[string]: any}
            local payload: {[string]: any} = {}
            for key: string, bucket: BucketRecord in pairs(runtime.buckets) do
                local meanSpeed: number = bucket.count > 0
                        and bucket.speedSum / bucket.count
                    or 0
                local variance: number = bucket.count > 1
                        and math.max(
                            0,
                            bucket.speedSquaredSum / bucket.count
                                - meanSpeed * meanSpeed
                        )
                    or 0
                payload[key] = {
                    count = bucket.count,
                    meanSpeed = meanSpeed,
                    speedStdDev = math.sqrt(variance),
                    meanLaunchDelayMs = bucket.count > 0
                            and bucket.delaySum / bucket.count
                        or 0,
                }
            end
            return payload
        end

        local function getPingMilliseconds(): number
            local pingMs: number = 0
            pcall(function(): ()
                local network: Instance? = Stats:FindFirstChild("Network")
                local serverItems: Instance? = network
                    and network:FindFirstChild("ServerStatsItem")
                local pingItem: any = serverItems
                    and serverItems:FindFirstChild("Data Ping")
                if pingItem and type(pingItem.GetValue) == "function" then
                    pingMs = tonumber(pingItem:GetValue()) or 0
                end
            end)
            return math.max(0, pingMs)
        end

        local function appendEvent(event: {[string]: any}): ()
            if #runtime.events >= 180 then
                table.remove(runtime.events, 1)
            end
            table.insert(runtime.events, event)
            runtime.dirty = true
        end

        saveSnapshot = function(reason: string): boolean
            if not runtime.historyLoaded then return false end -- enable first; do not overwrite unseen history
            if type(executorEnvironment.writefile) ~= "function" then
                return false
            end
            local payload: {[string]: any} = {
                schema = 1,
                kind = "universal-projectile-analytics",
                placeId = game.PlaceId,
                gameId = game.GameId,
                savedAt = DateTime.now():ToIsoDate(),
                reason = reason,
                bucketSpec = {
                    metric = "Data Ping",
                    widthMs = tuning.bucketWidthMs,
                    minimumMs = 0,
                    maximumMs = tuning.maxBucketMs,
                    overflow = tostring(tuning.maxBucketMs) .. "+",
                },
                summary = {
                    activations = runtime.totalActivations,
                    projectiles = runtime.totalProjectiles,
                    rejectedCandidates = runtime.rejectedCandidates,
                    elapsedSeconds = os.clock() - runtime.startedAt,
                },
                pingBuckets = bucketPayload(),
                projectiles = runtime.events,
            }
            local encodedOk: boolean, encoded: any = pcall(
                HttpService.JSONEncode,
                HttpService,
                payload
            )
            if not encodedOk or type(encoded) ~= "string" then
                return false
            end
            if type(executorEnvironment.makefolder) == "function" then
                pcall(executorEnvironment.makefolder, outputRoot)
                pcall(executorEnvironment.makefolder, outputTelemetry)
                pcall(executorEnvironment.makefolder, outputFolder)
            end
            local writeOk: boolean = pcall(
                executorEnvironment.writefile,
                outputPath,
                encoded
            )
            if not writeOk then
                return false
            end
            runtime.dirty = false
            return true
        end

        local function disconnectAll(): ()
            if runtime.sampler then
                runtime.sampler:Disconnect()
                runtime.sampler = nil
            end
            for _, connection: RBXScriptConnection in ipairs(runtime.connections) do
                connection:Disconnect()
            end
            table.clear(runtime.connections)
            for part: BasePart, track: ProjectileTrack in pairs(runtime.tracks) do
                if track.destroyConnection then
                    track.destroyConnection:Disconnect()
                end
                runtime.tracks[part] = nil
            end
            table.clear(runtime.pending)
            runtime.observedTools = setmetatable({}, {__mode = "k"})
            runtime.observedCandidates = setmetatable({}, {__mode = "k"})
        end

        local function compactPending(now: number): ()
            while #runtime.pending > 0
                and now - runtime.pending[1].activatedAt
                    > tuning.candidateLifetimeSeconds do
                table.remove(runtime.pending, 1)
            end
            while #runtime.pending > tuning.maxPendingActivations do
                table.remove(runtime.pending, 1)
            end
        end

        local function isCharacterPart(part: BasePart): boolean
            local model: Model? = part:FindFirstAncestorOfClass("Model")
            return model ~= nil and model:FindFirstChildOfClass("Humanoid") ~= nil
        end

        local function hasProjectileHint(part: BasePart): boolean
            local name: string = string.lower(part.Name)
            local parentName: string = part.Parent and string.lower(part.Parent.Name) or ""
            local combined: string = name .. " " .. parentName
            return string.find(combined, "projectile", 1, true) ~= nil
                or string.find(combined, "bullet", 1, true) ~= nil
                or string.find(combined, "arrow", 1, true) ~= nil
                or string.find(combined, "rocket", 1, true) ~= nil
                or string.find(combined, "missile", 1, true) ~= nil
                or string.find(combined, "knife", 1, true) ~= nil
                or string.find(combined, "grenade", 1, true) ~= nil
                or string.find(combined, "shell", 1, true) ~= nil
                or string.find(combined, "bolt", 1, true) ~= nil
                or string.find(combined, "orb", 1, true) ~= nil
                or part:GetAttribute("Projectile") == true
                or part:GetAttribute("ProjectileSpeed") ~= nil
                or part:GetAttribute("ThrowSpeed") ~= nil
        end

        local function resolveCandidate(instance: Instance): BasePart?
            if not instance:IsA("BasePart") then
                return nil
            end
            local part: BasePart = instance
            if part.Anchored
                or isCharacterPart(part)
                or (LocalPlayer.Character and part:IsDescendantOf(LocalPlayer.Character)) then
                return nil
            end
            local root: BasePart = part.AssemblyRootPart or part
            if runtime.observedCandidates[root] or isCharacterPart(root) then
                return nil
            end
            return root
        end

        local function ensureSampler(): ()
            if runtime.sampler then
                return
            end
            runtime.sampler = TaskManager:Connect(function(_deltaTime: number): ()
                local now: number = os.clock()
                local completed: {BasePart} = {}
                for part: BasePart, track: ProjectileTrack in pairs(runtime.tracks) do
                    if not part.Parent
                        or now - track.startedAt >= tuning.sampleWindowSeconds then
                        table.insert(completed, part)
                        continue
                    end
                    local position: Vector3 = part.Position
                    local velocity: Vector3 = part.AssemblyLinearVelocity
                    local speed: number = velocity.Magnitude
                    if track.previousPosition and track.previousAt then
                        local deltaTime: number = now - track.previousAt
                        if deltaTime >= 1 / 240 then
                            local measuredVelocity: Vector3 =
                                (position - track.previousPosition) / deltaTime
                            local measuredSpeed: number = measuredVelocity.Magnitude
                            if measuredSpeed >= 1 and measuredSpeed <= 5000 then
                                table.insert(track.speeds, measuredSpeed)
                                if #track.samples > 0 then
                                    local previousSample: ProjectileSample =
                                        track.samples[#track.samples]
                                    local previousVelocity: Vector3 = Vector3.new(
                                        previousSample.velocity[1],
                                        previousSample.velocity[2],
                                        previousSample.velocity[3]
                                    )
                                    local acceleration: Vector3 =
                                        (measuredVelocity - previousVelocity) / deltaTime
                                    if acceleration.Magnitude <= 10000 then
                                        table.insert(track.accelerations, acceleration.Magnitude)
                                        table.insert(track.verticalAccelerations, acceleration.Y)
                                    end
                                end
                            end
                            track.distance += (position - track.previousPosition).Magnitude
                        end
                    end
                    if #track.samples < tuning.maxSamplesPerTrack then
                        table.insert(track.samples, {
                            t = now - track.startedAt,
                            position = vectorArray(position),
                            velocity = vectorArray(velocity),
                            speed = speed,
                        })
                    end
                    track.previousPosition = position
                    track.previousAt = now
                end
                for _, part: BasePart in ipairs(completed) do
                    finishTrack(part, "sample-window-complete")
                end
                if next(runtime.tracks) == nil and runtime.sampler then
                    runtime.sampler:Disconnect()
                    runtime.sampler = nil
                end
            end)
        end

        finishTrack = function(part: BasePart, reason: string): ()
            local track: ProjectileTrack? = runtime.tracks[part]
            if not track then
                return
            end
            runtime.tracks[part] = nil
            if track.destroyConnection then
                track.destroyConnection:Disconnect()
                track.destroyConnection = nil
            end
            local speed: number? = median(track.speeds)
            if not speed or not finite(speed) or speed < 1 then
                runtime.rejectedCandidates += 1
                return
            end
            local acceleration: number? = median(track.accelerations)
            local verticalAcceleration: number? = median(track.verticalAccelerations)
            local bucketKey: string = pingBucketKey(track.pingMs)
            local bucket: BucketRecord = ensureBucket(bucketKey)
            bucket.count += 1
            bucket.speedSum += speed
            bucket.speedSquaredSum += speed * speed
            bucket.delaySum += track.launchDelayMs
            runtime.totalProjectiles += 1
            appendEvent({
                tool = track.toolName,
                projectile = track.projectileName,
                pingMs = track.pingMs,
                pingBucket = bucketKey,
                launchDelayMs = track.launchDelayMs,
                medianSpeed = speed,
                medianAcceleration = acceleration,
                medianVerticalAcceleration = verticalAcceleration,
                distanceStuds = track.distance,
                durationSeconds = os.clock() - track.startedAt,
                reason = reason,
                samples = track.samples,
            })
        end

        local function considerCandidate(instance: Instance): ()
            if not runtime.enabled or #runtime.pending == 0 then
                return
            end
            local part: BasePart? = resolveCandidate(instance)
            if not part then
                return
            end
            local now: number = os.clock()
            compactPending(now)
            if #runtime.pending == 0 then
                return
            end
            local hinted: boolean = hasProjectileHint(part)
            local speed: number = part.AssemblyLinearVelocity.Magnitude
            if not hinted and speed < tuning.minProjectileSpeed then
                return
            end
            local selectedIndex: number? = nil
            local selectedScore: number = math.huge
            for index: number = #runtime.pending, 1, -1 do
                local pending: PendingActivation = runtime.pending[index]
                if not part:IsDescendantOf(pending.tool) and pending.origin then
                    local offset: Vector3 = part.Position - pending.origin
                    local distance: number = offset.Magnitude
                    if distance <= 40 then
                        local alignmentPenalty: number = 0
                        if pending.aim and distance > 0.01 then
                            local desired: Vector3 = pending.aim - pending.origin
                            if desired.Magnitude > 0.01 then
                                local alignment: number = offset.Unit:Dot(desired.Unit)
                                if alignment < 0.35 and not hinted then
                                    continue
                                end
                                alignmentPenalty = (1 - alignment) * 0.25
                            end
                        end
                        local score: number = now - pending.activatedAt
                            + distance * 0.01
                            + alignmentPenalty
                            + (hinted and 0 or 0.2)
                        if score < selectedScore then
                            selectedScore = score
                            selectedIndex = index
                        end
                    end
                end
            end
            if not selectedIndex then
                runtime.rejectedCandidates += 1
                return
            end
            local pending: PendingActivation = table.remove(runtime.pending, selectedIndex)
            runtime.observedCandidates[part] = true
            local track: ProjectileTrack = {
                instance = part,
                toolName = pending.tool.Name,
                projectileName = part:GetFullName(),
                startedAt = now,
                launchDelayMs = math.max(0, (now - pending.activatedAt) * 1000),
                pingMs = pending.pingMs,
                origin = pending.origin :: Vector3,
                previousAt = now,
                previousPosition = part.Position,
                speeds = {},
                accelerations = {},
                verticalAccelerations = {},
                samples = {},
                distance = 0,
                destroyConnection = nil,
            }
            runtime.tracks[part] = track
            track.destroyConnection = part.Destroying:Connect(function(): ()
                finishTrack(part, "destroyed")
            end)
            ensureSampler()
        end

        local function observeTool(tool: Tool): ()
            if runtime.observedTools[tool] then
                return
            end
            runtime.observedTools[tool] = true
            table.insert(runtime.connections, tool.Activated:Connect(function(): ()
                if not runtime.enabled then
                    return
                end
                local originPart: BasePart? = tool:FindFirstChild("Handle") :: BasePart?
                local characterRoot: BasePart? = LocalPlayer.Character
                    and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                    :: BasePart?
                local origin: Vector3? = originPart and originPart:IsA("BasePart")
                        and originPart.Position
                    or characterRoot and characterRoot.Position
                    or nil
                if not origin then
                    return
                end
                local aim: Vector3? = nil
                pcall(function(): ()
                    aim = mouse.Hit.Position
                end)
                runtime.totalActivations += 1
                table.insert(runtime.pending, {
                    tool = tool,
                    activatedAt = os.clock(),
                    origin = origin,
                    aim = aim,
                    pingMs = getPingMilliseconds(),
                })
                compactPending(os.clock())
            end))
        end

        local function observeContainer(container: Instance?): ()
            if not container then
                return
            end
            for _, child: Instance in ipairs(container:GetChildren()) do
                if child:IsA("Tool") then
                    observeTool(child)
                end
            end
            table.insert(runtime.connections, container.ChildAdded:Connect(function(
                child: Instance
            ): ()
                if child:IsA("Tool") then
                    observeTool(child)
                end
            end))
        end

        local function loadSavedAnalytics(): ()
            if runtime.historyLoaded then return end
            runtime.historyLoaded = true
            if type(executorEnvironment.readfile) ~= "function" then
                return
            end
            local okRead: boolean, rawData: any = pcall(
                executorEnvironment.readfile,
                outputPath
            )
            if not okRead or type(rawData) ~= "string" or #rawData < 10 then
                return
            end
            local okDecode: boolean, decoded: any = pcall(function(): any
                return HttpService:JSONDecode(rawData)
            end)
            if not okDecode or type(decoded) ~= "table" then
                return
            end
            if type(decoded.summary) == "table" then
                runtime.totalActivations = tonumber(decoded.summary.totalActivations)
                    or tonumber(decoded.summary.activations)
                    or 0
                runtime.totalProjectiles = tonumber(decoded.summary.totalProjectiles)
                    or tonumber(decoded.summary.projectiles)
                    or 0
                runtime.rejectedCandidates = tonumber(decoded.summary.rejectedCandidates) or 0
            end
            if type(decoded.pingBuckets) == "table" then
                for key: string, bData: any in pairs(decoded.pingBuckets) do
                    if type(bData) == "table" then
                        local c: number = tonumber(bData.count) or 0
                        local speed: number = tonumber(bData.meanSpeed) or 0
                        local delay: number = tonumber(bData.meanLaunchDelayMs) or 0
                        if c > 0 then
                            local bucket: BucketRecord = ensureBucket(key)
                            bucket.count = c
                            bucket.speedSum = speed * c
                            bucket.speedSquaredSum = (speed * speed) * c
                            bucket.delaySum = delay * c
                        end
                    end
                end
            end
            if type(decoded.projectiles) == "table" then
                runtime.events = {}
                for _, p: any in ipairs(decoded.projectiles) do
                    table.insert(runtime.events, p)
                end
            end
        end

        controller = {} :: Controller
        controller.tuning = tuning

        function controller:setEnabled(enabled: boolean): ()
            if runtime.enabled == enabled then
                return
            end
            if not enabled then
                runtime.enabled = false
                disconnectAll()
                return
            end
            runtime.enabled = true
            runtime.startedAt = os.clock()
            loadSavedAnalytics()
            observeContainer(LocalPlayer:FindFirstChildOfClass("Backpack"))
            observeContainer(LocalPlayer.Character)
            table.insert(runtime.connections, LocalPlayer.CharacterAdded:Connect(function(
                character: Model
            ): ()
                observeContainer(character)
            end))
            table.insert(runtime.connections, workspace.DescendantAdded:Connect(
                considerCandidate
            ))
        end

        function controller:save(reason: string?): boolean
            return saveSnapshot(reason or "manual")
        end

        function controller:delete(): boolean
            runtime.historyLoaded = true
            runtime.events = {}
            runtime.buckets = {}
            runtime.totalActivations = 0
            runtime.totalProjectiles = 0
            runtime.rejectedCandidates = 0
            runtime.dirty = false
            local deleteFile: any = executorEnvironment.delfile
            local okDelete: boolean = false
            if type(deleteFile) == "function" then
                okDelete = pcall(deleteFile, outputPath)
            elseif type(executorEnvironment.writefile) == "function" then
                okDelete = pcall(executorEnvironment.writefile, outputPath, "{}")
            end
            return okDelete
        end

        function controller:status(): string
            return string.format(
                "Universal observer %s · activations %d · projectiles %d · buckets %d",
                runtime.enabled and "ON" or "OFF", runtime.totalActivations,
                runtime.totalProjectiles,
                (function(): number
                    local count: number = 0
                    for _key: string in pairs(runtime.buckets) do
                        count += 1
                    end
                    return count
                end)()
            )
        end

        function controller:destroy(): ()
            self:setEnabled(false)
        end

        return controller
    end)()

    local calibration: any = controllerFactory
    calibrationService.set(calibration)
    activeRegistry = calibrationService

    local tuning: any = calibration.tuning

    local ProjectileCalibrationFeature: any = state.metricsFeature
    if not ProjectileCalibrationFeature then
        ProjectileCalibrationFeature = createUniversalFeature(
            "Metrics",
            "Calibration and game-learning telemetry in one card: projectile "
                .. "analytics, client observations, optional motion calibration.",
            17,
            function(_enabled: boolean): () end,
            {category = true, categoryName = "Other"}
        )
        state.metricsFeature = ProjectileCalibrationFeature
    end
    addToggleOption(ProjectileCalibrationFeature, "Projectile observer", false, function(value: boolean): ()
        calibration:setEnabled(value)
    end, "Optional generic physical-projectile logger. It does not train MM2 Shoot/Knife and may not observe hitscan or direct remote requests.")
    tuning =
        calibration.tuning
    addNumberOption(
        ProjectileCalibrationFeature,
        "Bucket width (ms)",
        tuning.bucketWidthMs,
        1,
        25,
        function(value: number): ()
            tuning.bucketWidthMs = math.round(value)
        end
    )
    addNumberOption(
        ProjectileCalibrationFeature,
        "Bucket ceiling (ms)",
        tuning.maxBucketMs,
        25,
        500,
        function(value: number): ()
            tuning.maxBucketMs = math.round(value)
        end
    )
    addNumberOption(
        ProjectileCalibrationFeature,
        "Sample window (s)",
        tuning.sampleWindowSeconds,
        1,
        6,
        function(value: number): ()
            tuning.sampleWindowSeconds = value
        end
    )
    addNumberOption(
        ProjectileCalibrationFeature,
        "Max samples / track",
        tuning.maxSamplesPerTrack,
        30,
        600,
        function(value: number): ()
            tuning.maxSamplesPerTrack = math.round(value)
        end
    )
    addNumberOption(
        ProjectileCalibrationFeature,
        "Match radius (studs)",
        tuning.matchDistanceStuds,
        10,
        120,
        function(value: number): ()
            tuning.matchDistanceStuds = math.round(value)
        end
    )
    addNumberOption(
        ProjectileCalibrationFeature,
        "Min projectile speed",
        tuning.minProjectileSpeed,
        1,
        100,
        function(value: number): ()
            tuning.minProjectileSpeed = math.round(value)
        end
    )
    addActionOption(ProjectileCalibrationFeature, "Projectile status", function(): ()
        notify(calibration:status())
    end)
    addActionOption(ProjectileCalibrationFeature, "Save projectile data", function(): ()
        if calibration:save("manual") then
            notify("analytics saved")
        else
            notify("save failed; check F9")
        end
    end)
    addActionOption(ProjectileCalibrationFeature, "Clear projectile data", function(): ()
        if calibration:delete() then
            notify("calibration history cleared")
        else
            notify("clear history failed; check F9")
        end
    end)
    addInformationOption(
        ProjectileCalibrationFeature,
        "Opt-in observer. Enable before saving; OFF releases its listeners. Data is heuristic, not hit confirmation. MM2 prediction never consumes this dataset."
    )

    activeController = calibration
    Module.Initialized = true
    return calibration
end

function Module.destroy(): ()
    if activeController and type(activeController.destroy) == "function" then
        pcall(function(): ()
            activeController:destroy()
        end)
    end
    activeController = nil
    if activeRegistry then
        activeRegistry.set(nil)
    end
    activeRegistry = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/TimeChanger.lua"] = [[
--!strict
export type Runtime = {
    framework: any,
    host: any,
    services: any,
}

local Module = {
    Name = "TimeChanger",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCard: any = nil

function Module.init(context: Runtime): any
    local framework: any = context.framework
    local host: any = context.host
    local Lighting: Lighting = host.Lighting or (game :: any):GetService("Lighting")

    local originalTime: string? = nil
    local customTime: number = 14

    local function applyTime(hour: number): ()
        local timeString: string = string.format("%02d:00:00", math.floor(hour))
        pcall(function()
            Lighting.TimeOfDay = timeString
        end)
    end

    local card: any
    card = framework.Categories.Render:CreateModule({
        Name = "Time Changer",
        Category = "Render",
        ConfigKey = "Universal.TimeChanger",
        Order = 25,
        Tooltip = "Changes the client time of day in the current world.",
        Function = function(enabled: boolean): ()
            if enabled then
                originalTime = Lighting.TimeOfDay
                applyTime(customTime)
                card:SetStatus(string.format("%02d:00", customTime))

                card:Loop(function(): ()
                    if originalTime then
                        applyTime(customTime)
                    end
                end)
            else
                if originalTime then
                    pcall(function()
                        Lighting.TimeOfDay = originalTime
                    end)
                    originalTime = nil
                end
                card:SetStatus(nil)
            end
        end,
    })

    card:CreateSlider({
        Name = "Time",
        Min = 0,
        Max = 24,
        Default = 14,
        Step = 1,
        Function = function(value: number): ()
            customTime = value
            if card.Enabled then
                applyTime(value)
                card:SetStatus(string.format("%02d:00", value))
            end
        end,
        Tooltip = "Hour of day (0 = midnight, 12 = noon, 18 = sunset).",
    })

    activeCard = card
    Module.Initialized = true
    return card
end

function Module.destroy(): ()
    if activeCard and activeCard.Enabled then
        pcall(activeCard.Toggle, false)
    end
    activeCard = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/XRay.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "XRay",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local LocalPlayer: any = host.LocalPlayer
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local createUniversalFeature: any = host.createUniversalFeature
    local originalXrayTransparency: {[BasePart]: number} =
        setmetatable({}, {__mode = "k"}) :: any
    local xrayEnabled: boolean = false
    local feature: any = nil

    local function restoreXray(): ()
        for part: BasePart, transparency: number in pairs(originalXrayTransparency) do
            if part.Parent then
                part.LocalTransparencyModifier = transparency
            end
        end
        originalXrayTransparency = setmetatable({}, {__mode = "k"}) :: any
    end

    local function toggleXray(enabled: boolean): ()
        disconnectFeatureConnection("Xray")
        xrayEnabled = false
        restoreXray()
        if not enabled then
            if feature then feature:SetStatus(nil) end
            return
        end

        feature:SetStatus("72%")
        xrayEnabled = true
        local function applyToInstance(descendant: Instance): ()
            if not xrayEnabled or not descendant:IsA("BasePart") then
                return
            end
            local localCharacter: Model? = LocalPlayer.Character
            local ancestorModel: Model? = descendant:FindFirstAncestorOfClass("Model")
            if (localCharacter and descendant:IsDescendantOf(localCharacter))
                or descendant:FindFirstAncestorOfClass("Tool")
                or (ancestorModel and ancestorModel:FindFirstChildOfClass("Humanoid")) then
                return
            end
            if originalXrayTransparency[descendant] == nil then
                originalXrayTransparency[descendant] = descendant.LocalTransparencyModifier
            end
            descendant.LocalTransparencyModifier = math.max(
                descendant.LocalTransparencyModifier,
                0.72
            )
        end

        featureConnections.Xray = workspace.DescendantAdded:Connect(applyToInstance)
        task.spawn(function(): ()
            for index: number, descendant: Instance in ipairs(workspace:GetDescendants()) do
                if not xrayEnabled then
                    return
                end
                applyToInstance(descendant)
                if index % 240 == 0 then
                    task.wait()
                end
            end
        end)
    end

    feature = createUniversalFeature(
        "X-Ray",
        "Fade map geometry locally while keeping your character clear",
        18,
        toggleXray,
        {noOptions = true, categoryName = "Render"}
    )

    activeCleanup = function(): ()
        disconnectFeatureConnection("Xray")
        restoreXray()
    end
    Module.Initialized = true
    return feature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/games/universal/Render/ZoomUnlocker.lua"] = [[
export type Runtime = {
    framework: any,
    entity: any,
    host: any,
}

local Module = {
    Name = "ZoomUnlocker",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

function Module.init(context: Runtime): any
    local host: any = context.host
    local LocalPlayer: any = host.LocalPlayer
    local TaskManager: any = host.TaskManager
    local featureConnections: any = host.featureConnections
    local disconnectFeatureConnection: any = host.disconnectFeatureConnection
    local createUniversalFeature: any = host.createUniversalFeature
    local addToggleOption: any = host.addToggleOption
    local addNumberOption: any = host.addNumberOption
    type ZoomSettings = {
        minDistance: number,
        maxDistance: number,
        unlockFirstPerson: boolean,
    }
    type ZoomState = {
        minDistance: number,
        maxDistance: number,
        cameraMode: Enum.CameraMode,
    }
    local zoomSettings: ZoomSettings = {
        minDistance = 0.5,
        maxDistance = 400,
        unlockFirstPerson = true,
    }
    local originalZoomState: ZoomState? = nil
    local ZoomFeature: any = nil

    local function toggleZoomUnlocker(enabled: boolean): ()
        disconnectFeatureConnection("ZoomUnlocker")
        if originalZoomState then
            LocalPlayer.CameraMinZoomDistance = originalZoomState.minDistance
            LocalPlayer.CameraMaxZoomDistance = originalZoomState.maxDistance
            LocalPlayer.CameraMode = originalZoomState.cameraMode
            originalZoomState = nil
        end
        if not enabled then
            if ZoomFeature then ZoomFeature:SetStatus(nil) end
            return
        end
        ZoomFeature:SetStatus(tostring(math.round(zoomSettings.maxDistance)) .. " studs")
        originalZoomState = {
            minDistance = LocalPlayer.CameraMinZoomDistance,
            maxDistance = LocalPlayer.CameraMaxZoomDistance,
            cameraMode = LocalPlayer.CameraMode,
        }
        featureConnections.ZoomUnlocker = TaskManager:Connect(function(): ()
            LocalPlayer.CameraMinZoomDistance = math.min(
                zoomSettings.minDistance,
                zoomSettings.maxDistance
            )
            LocalPlayer.CameraMaxZoomDistance = math.max(
                zoomSettings.minDistance,
                zoomSettings.maxDistance
            )
            if zoomSettings.unlockFirstPerson then
                LocalPlayer.CameraMode = Enum.CameraMode.Classic
            elseif originalZoomState then
                LocalPlayer.CameraMode = originalZoomState.cameraMode
            end
        end)
    end

    ZoomFeature = createUniversalFeature(
        "Zoom",
        "Extend camera zoom and optionally leave forced first person",
        23,
        toggleZoomUnlocker,
        {
            configKey = "Universal.ZoomUnlocker",
            categoryName = "Render",
        }
    )
    addNumberOption(
        ZoomFeature,
        "Maximum distance",
        zoomSettings.maxDistance,
        25,
        2000,
        function(value: number): ()
            zoomSettings.maxDistance = value
            if ZoomFeature.enabled then
                ZoomFeature:SetStatus(tostring(math.round(value)) .. " studs")
            end
        end
    )
    addNumberOption(
        ZoomFeature,
        "Minimum distance",
        zoomSettings.minDistance,
        0.5,
        50,
        function(value: number): ()
            zoomSettings.minDistance = value
        end
    )
    addToggleOption(
        ZoomFeature,
        "Unlock forced first person",
        zoomSettings.unlockFirstPerson,
        function(value: boolean): ()
            zoomSettings.unlockFirstPerson = value
        end
    )

    activeCleanup = function(): ()
        disconnectFeatureConnection("ZoomUnlocker")
        if originalZoomState then
            pcall(function(): ()
                LocalPlayer.CameraMinZoomDistance = originalZoomState.minDistance
                LocalPlayer.CameraMaxZoomDistance = originalZoomState.maxDistance
                LocalPlayer.CameraMode = originalZoomState.cameraMode
            end)
            originalZoomState = nil
        end
    end
    Module.Initialized = true
    return ZoomFeature
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/guis/Wurst/Code/Cards.lua"] = [[
local Module = {
    Name = "Cards",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local moduleCleanup: () -> () = function(): () end

function Module.init(context: any): any
    local host: any = context
    local state: any = host.state
    local configData: any = host.configData
    local queueConfigSave: any = host.queueConfigSave
    local flushConfigSave: any = host.flushConfigSave or queueConfigSave
    local create: any = host.create
    local makeButton: any = host.makeButton
    local makeTextLabel: any = host.makeTextLabel
    local notify: any = host.notify
    local Theme: any = host.Theme
    local CONTROL_FONT: any = host.CONTROL_FONT
    local trackUiConnection: any = host.trackUiConnection
    local beginKeyCapture: any = host.beginKeyCapture
    local UserInputService: any = host.UserInputService
    local applyKeySlotStyle: any = host.applyKeySlotStyle
    local bindActionShortcut: any = host.bindActionShortcut
    local getFeatureCardParent: any = host.getFeatureCardParent

    local FEATURE_CATEGORIES: any = host.FEATURE_CATEGORIES
    local DEFAULT_FEATURE_CATEGORY: any = host.DEFAULT_FEATURE_CATEGORY
    local normalizeFeatureCategory: any = host.normalizeFeatureCategory

    local universalFeatures: any = host.universalFeatures
    local movementFeatures: any = host.movementFeatures
    local mm2Features: any = host.mm2Features
    local allFeatures: any = host.allFeatures
    local registeredSearchFeatures: {any} = {}

    local applyFeaturePresentation: any = host.applyFeaturePresentation
    local refreshFeatureToggle: any = host.refreshFeatureToggle
    local addFeatureTooltip: any = host.addFeatureTooltip

    local drawPixelIcon: any = host.drawPixelIcon
        or function(parent: Instance, _kind: string, _color: Color3?): Frame
            local existing: Instance? = (parent :: any):FindFirstChild("PixelIcon")
            if existing then
                existing:Destroy()
            end
            return create("Frame", {
                Parent = parent,
                Name = "PixelIcon",
                BackgroundTransparency = 1,
            }) :: Frame
        end

    local function createUniversalFeature(
        name: string,
        description: string,
        layoutOrder: number,
        onToggle: any,
        configuration: any?
    ): any
        configuration = configuration or {}
        local registry: any = configuration.registry or universalFeatures
        local sectionName: string = configuration.section
            or (registry == mm2Features and "MM2")
            or (registry == state.trsFeatures and "TRS")
            or (registry == state.vdFeatures and "VD")
            or (registry == state.bedFightFeatures and "BedFight")
            or (registry == state.bedWarsFeatures and "BedWars")
            or (registry == state.mvsdFeatures and "MVSD")
            or (registry == movementFeatures and "Movement")
            or "Universal"
        local configKey: string = configuration.configKey
            or (sectionName .. "." .. name:gsub("%W", ""))

        local rawCategory: any = type(configuration.categoryName) == "string"
            and configuration.categoryName
            or FEATURE_CATEGORIES[name]
            or DEFAULT_FEATURE_CATEGORY
        local categoryName: string = type(normalizeFeatureCategory) == "function"
            and normalizeFeatureCategory(rawCategory)
            or tostring(rawCategory)

        local feature: any = {
            name = name,
            description = description,
            categoryName = categoryName,
            enabled = false,
            expanded = false,

            kind = configuration.kind
                or (configuration.action == true and "action")
                or (configuration.holdAction == true and "hold")
                or (configuration.category == true and "group")
                or "toggle",
            silentAction = configuration.silentAction == true,
            searchable = configuration.searchable ~= false,
            onHold = configuration.onHold,
            optionCount = 0,
            optionRows = {},
            collapsedHeight = state.layout.cardHeight,
            onToggle = onToggle,
            configKey = configKey,
            registry = registry,
            sectionName = sectionName,
            searchText = string.lower(
                name
                    .. " "
                    .. description
                    .. " "
                    .. sectionName
                    .. " "
                    .. categoryName
            ),
            tooltipText = description,
            tooltipBound = false,
        }

        feature.isAction = feature.kind == "action"
        feature.isCategory = feature.kind == "group"
        feature.isHoldAction = feature.kind == "hold"
        feature.isAlwaysOn = feature.kind == "hold" or feature.kind == "group"

        local requestedParent: Instance? =
            configuration.parent :: any
        local fallback: Instance = (host :: any).ScreenGui or (host :: any).PopupLayer or ({} :: any)
        local rowParent: Instance = getFeatureCardParent(requestedParent or fallback)
        if type(rowParent) ~= "table" or (rowParent :: any).Children == nil then
            rowParent = fallback
        end
        local row: Frame = (create("Frame", {
            Parent = rowParent,
            Name = name:gsub("%W", "") .. "Feature",
            Active = true,
            BackgroundColor3 = state.guiStyle == "Default"
                and Theme.surface
                or Theme.background,
            BackgroundTransparency = state.guiStyle == "Default" and 0.82 or 1,
            BorderSizePixel = 0,
            ClipsDescendants = true,
            LayoutOrder = layoutOrder,
            Size = UDim2.new(1, 0, 0, feature.collapsedHeight),
        }) :: any) :: Frame
        feature.row = row

        row:SetAttribute("FeatureCategory", categoryName)
        row:SetAttribute("FeatureSortName", string.lower(name))

        local bitmapText: any = state.bitmapText
        local title: TextLabel? = nil
        if bitmapText and type(bitmapText.draw) == "function" then
            feature.drawTitle = function(color: Color3?, transparency: number?): ()
                if color ~= nil then
                    feature.titleColor = color
                end
                if transparency ~= nil then
                    feature.titleTransparency = transparency
                end
                bitmapText.draw(row, {
                    {
                        text = name,
                        color = feature.titleColor or Theme.text,
                    },
                }, {
                    Name = "Title",
                    TextSize = state.layout.titleFontSize,
                    ZIndex = 7,
                    align = "Center",
                    transparency = feature.titleTransparency or 0,

                    maxWidth = 140,
                })
            end
            feature.drawTitle(Theme.text, 0)
        else
            title = (makeTextLabel(row, name, state.layout.titleFontSize) :: any) :: TextLabel
            local label: TextLabel = title :: TextLabel
            label.FontFace = CONTROL_FONT

            label.Position = UDim2.fromOffset(28, 0)
            label.Size = UDim2.new(1, -56, 0, feature.collapsedHeight)
            label.TextXAlignment = Enum.TextXAlignment.Center
            label.TextTruncate = Enum.TextTruncate.AtEnd
            label.TextColor3 = state.guiStyle == "Default"
                and Theme.text
                or Theme.text
            feature.title = label
        end

        local arrow: TextButton? = nil
        local toggleExpansion: () -> () = function(): () end

        function feature.hasOptions(): boolean
            if configuration.noOptions == true then
                return false
            end
            for _, optionRow: GuiObject in ipairs(feature.optionRows) do
                if optionRow.Visible then
                    return true
                end
            end
            return false
        end

        local function syncArrow(): ()
            local expandable: boolean = feature.hasOptions()
            feature.hasSettings = expandable
            if expandable and not arrow then
                local built: TextButton = (create("TextButton", {
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    Parent = row,
                    Name = "Expand",
                    Active = true,
                    AnchorPoint = Vector2.new(1, 0),
                    AutoButtonColor = false,
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    FontFace = CONTROL_FONT,
                    Position = UDim2.new(1, 0, 0, 0),
                    Size = UDim2.fromOffset(22, feature.collapsedHeight),
                    Text = "",
                    TextSize = 10,
                    ZIndex = 9,
                }) :: any) :: TextButton
                trackUiConnection(built.MouseButton1Click:Connect(function(): ()
                    toggleExpansion()
                end))
                arrow = built
                feature.arrow = built
            end
            if arrow then
                (arrow :: TextButton).Visible = expandable

                drawPixelIcon(
                    arrow :: TextButton,
                    feature.expanded and "up" or "down",
                    Color3.fromRGB(0, 204, 0)
                )
            end
        end
        feature.syncArrow = syncArrow

        local activationTarget: TextButton = create("TextButton", {
            TextTruncate = Enum.TextTruncate.AtEnd,
            ClipsDescendants = true,
            Parent = row,
            Name = "ActivationTarget",
            Active = true,
            AutoButtonColor = false,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Position = UDim2.fromOffset(0, 0),
            Size = UDim2.new(1, 0, 0, feature.collapsedHeight),
            Text = "",
            ZIndex = 6,
        }) :: TextButton
        feature.activationTarget = activationTarget
        if title then
            (title :: TextLabel).ZIndex = 7
        end

        trackUiConnection(row.MouseEnter:Connect(function(): ()
            state.applyCardSkin(feature, true)
        end))
        trackUiConnection(row.MouseLeave:Connect(function(): ()
            state.applyCardSkin(feature, false)
        end))

        local options: Frame = (create("Frame", {
            Parent = row,
            Name = "Options",
            Active = true,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Position = UDim2.fromOffset(4, feature.collapsedHeight),
            Size = UDim2.new(1, -8, 0, 0),
            Visible = false,
            ZIndex = row.ZIndex + 10,
        }) :: any) :: Frame
        feature.options = options
        create("UIPadding", {
            Parent = options,
            PaddingBottom = UDim.new(0, 4),
            PaddingLeft = UDim.new(0, 0),
            PaddingRight = UDim.new(0, 0),
            PaddingTop = UDim.new(0, 4),
        })
        local optionsLayout: UIListLayout = (create("UIListLayout", {
            Parent = options,
            FillDirection = Enum.FillDirection.Vertical,
            HorizontalAlignment = Enum.HorizontalAlignment.Center,
            Padding = UDim.new(0, 4),
            SortOrder = Enum.SortOrder.LayoutOrder,
        }) :: any) :: UIListLayout

        local function updateExpandedSize(_animate: boolean?): ()

            local visibleOptions: number = 0
            local declaredHeight: number = 0
            for _, optionRow: GuiObject in ipairs(feature.optionRows) do
                if optionRow.Visible then
                    visibleOptions += 1
                    declaredHeight += optionRow.Size.Y.Offset
                end
            end
            local measuredHeight: number = optionsLayout.AbsoluteContentSize.Y
            if visibleOptions > 0 and measuredHeight <= 0 then
                measuredHeight = declaredHeight
                    + math.max(0, visibleOptions - 1) * 4
            end

            local optionsHeight: number = measuredHeight + 8
            feature.optionsHeight = optionsHeight
            options.Size = UDim2.new(1, 0, 0, optionsHeight)
            syncArrow()
            local settingsWindow: any = feature.settingsWindow
            if settingsWindow and settingsWindow.resizeToOptions then
                settingsWindow.resizeToOptions()
            end
        end
        feature.updateExpandedSize = updateExpandedSize
        trackUiConnection(
            optionsLayout:GetPropertyChangedSignal("AbsoluteContentSize")
                :Connect(function(): ()
                    updateExpandedSize(false)
                end)
        )

        toggleExpansion = function(): ()
            if not feature.hasOptions() then

                syncArrow()
                return
            end

            local windows: any = state.windows
            if windows and type(windows.OpenFeatureSettings) == "function" then
                windows.OpenFeatureSettings(feature)
            end
        end
        feature.toggleExpansion = toggleExpansion

        function feature.setHeld(held: boolean): ()
            if feature.held == held then
                return
            end
            feature.held = held
            local handler: any = feature.onHold
            if type(handler) ~= "function" then
                return
            end
            local ok: boolean, failure: any = pcall(handler, held)
            if not ok then
                warn("[Random Testing Menu] " .. name .. ": " .. tostring(failure))
                return
            end
            feature.active = held
            refreshFeatureToggle(feature)
        end

        local function activateFeature(): ()
            if feature.isHoldAction then

                return
            end
            if feature.isCategory then
                if not feature.hasOptions() then
                    return
                end
                feature.expanded = not feature.expanded
                updateExpandedSize(true)
                return
            end
            if feature.isAction then
                if feature.actionRunning then
                    return
                end
                feature.actionRunning = true
                task.spawn(function(): ()
                    local success: boolean, errorMessage: any = pcall(feature.onToggle)
                    feature.actionRunning = false
                    if success then

                        if not feature.silentAction then
                            notify(name .. " ran")
                        end
                    else
                        warn("[Random Testing Menu] " .. name .. ": " .. tostring(errorMessage))
                        notify("Could not run " .. name)
                    end
                end)
                return
            end

            local requestedState: boolean = not feature.enabled
            local success: boolean, errorMessage: any = pcall(
                feature.onToggle,
                requestedState
            )
            if success then
                feature.enabled = requestedState
                if requestedState then
                    feature.enabledAt = os.clock()
                end
                configData.states[feature.configKey] = requestedState
                flushConfigSave()
                notify(name .. (requestedState and " enabled" or " disabled"))
            else
                warn("[Random Testing Menu] " .. name .. ": " .. tostring(errorMessage))
                feature.enabled = false
                pcall(feature.onToggle, false)
                notify("Could not toggle " .. name)
            end
            refreshFeatureToggle(feature)
        end
        feature.activate = activateFeature

        state.applyCardSkin(feature, false)
        if feature.isAction then

            trackUiConnection(activationTarget.MouseButton1Down:Connect(function(): ()
                if feature.row then
                    (feature.row :: Frame).BackgroundTransparency = 0.46
                end
            end))
            trackUiConnection(activationTarget.MouseButton1Up:Connect(function(): ()
                state.applyCardSkin(feature, true)
            end))
        end

        trackUiConnection(activationTarget.MouseButton1Click:Connect(activateFeature))

        trackUiConnection(activationTarget.InputBegan:Connect(function(input: InputObject): ()
            if input.UserInputType == Enum.UserInputType.MouseButton2 then
                toggleExpansion()
            end
        end))

        local shortcutButton: TextButton? = nil
        if state.isMobile then
            local slot: TextButton =
                (makeButton(row, "KEY", 9) :: any) :: TextButton
            slot.Name = "Shortcut"

            slot.AnchorPoint = Vector2.new(0, 0.5)
            slot.Position = UDim2.new(0, 4, 0, feature.collapsedHeight / 2)
            slot.Size = UDim2.fromOffset(22, 22)
            slot.ZIndex = 9
            applyKeySlotStyle(slot)
            slot.TextScaled = true
            create("UITextSizeConstraint", {
                Parent = slot,
                MaxTextSize = 11,
                MinTextSize = 7,
            })
            shortcutButton = slot
        end
        feature.shortcutButton = shortcutButton
        if feature.kind == "group" then

            if shortcutButton then
                (shortcutButton :: TextButton).Visible = false
            end
        elseif feature.kind == "hold" then

            bindActionShortcut(
                shortcutButton,
                feature.configKey,
                name,
                function(): () end,
                {
                    hold = true,
                    onPress = function(): ()
                        feature.setHeld(true)
                    end,
                    onRelease = function(): ()
                        feature.setHeld(false)
                    end,
                }
            )
        else
            bindActionShortcut(
                shortcutButton,
                feature.configKey,
                name,
                activateFeature
            )
        end

        if (feature.kind == "toggle"
                or feature.kind == "action"
                or feature.kind == "hold")
            and not state.isMobile
            and type(beginKeyCapture) == "function"
            and type(state.shortcutBindings) == "table"
            and state.shortcutBindings[feature.configKey] ~= nil then
            local binding: any = state.shortcutBindings[feature.configKey]
            local UNBOUND_BG: Color3 = Color3.fromRGB(0, 0, 0)
            local BOUND_BG: Color3 = Color3.fromRGB(0, 80, 0)
            local CONFLICT_BG: Color3 = Color3.fromRGB(80, 0, 0)
            local BOUND_EDGE: Color3 = Color3.fromRGB(0, 204, 0)
            local CONFLICT_EDGE: Color3 = Color3.fromRGB(204, 0, 0)
            local square: TextButton = (create("TextButton", {
                TextTruncate = Enum.TextTruncate.AtEnd,
                Parent = row,
                Name = "BindSquare",
                Active = true,
                AnchorPoint = Vector2.new(0, 0.5),
                AutoButtonColor = false,
                BackgroundColor3 = UNBOUND_BG,
                BackgroundTransparency = 0.55,
                BorderSizePixel = 0,
                FontFace = CONTROL_FONT,
                Position = UDim2.new(0, 4, 0.5, 0),
                Size = UDim2.fromOffset(18, 18),
                Text = "",
                TextColor3 = Theme.text,
                TextTransparency = 0,
                TextSize = 8,
                ZIndex = 8,
            }) :: any) :: TextButton
            square:SetAttribute("CaptureIdleText", "")
            local edge: UIStroke = (create("UIStroke", {
                Parent = square,
                Name = "StyleStroke",
                Color = Theme.outline,
                Thickness = 1,
                Transparency = 0.6,
            }) :: any) :: UIStroke

            local COMPACT_KEY_NAMES: {[string]: string} = {
                LeftShift = "LS",
                RightShift = "RS",
                LeftControl = "LC",
                RightControl = "RC",
                LeftAlt = "LA",
                RightAlt = "RA",
                CapsLock = "CL",
                Backspace = "Bk",
                Return = "En",
                Escape = "Es",
                Space = "Sp",
                PageUp = "PU",
                PageDown = "PD",
                Insert = "Ins",
                Delete = "Del",
                Home = "Hm",
                End = "End",
            }
            local function keyCaption(): string
                if binding.key == nil or binding.key == Enum.KeyCode.Unknown then
                    return ""
                end
                local name: string = tostring(binding.key.Name or "")
                local compact: string? = COMPACT_KEY_NAMES[name]
                if compact then
                    return compact
                end
                local display: string = state.keyDisplayName
                        and tostring(state.keyDisplayName(name))
                    or name
                return string.sub(display, 1, 3)
            end

            local capturing: boolean = false
            local function conflictWith(): any
                if binding.key == nil or binding.key == Enum.KeyCode.Unknown then
                    return nil
                end
                for _, other: any in pairs(state.shortcutBindings) do
                    if other ~= binding and other.key == binding.key then
                        return other
                    end
                end
                return nil
            end
            local function syncSquare(): ()
                if capturing then
                    return
                end
                local caption: string = keyCaption()
                square.Text = caption
                square:SetAttribute("CaptureIdleText", caption)
                local bound: boolean = binding.key ~= nil
                    and binding.key ~= Enum.KeyCode.Unknown
                local conflict: any = bound and conflictWith() or nil
                if conflict then
                    square.BackgroundColor3 = CONFLICT_BG
                    square.BackgroundTransparency = 0.35
                    edge.Color = CONFLICT_EDGE
                    edge.Transparency = 0.15
                elseif bound then
                    square.BackgroundColor3 = BOUND_BG
                    square.BackgroundTransparency = 0.35
                    edge.Color = BOUND_EDGE
                    edge.Transparency = 0.25
                else
                    square.BackgroundColor3 = UNBOUND_BG
                    square.BackgroundTransparency = 0.55
                    edge.Color = Theme.outline
                    edge.Transparency = 0.6
                end
            end
            feature.bindSquare = square
            feature.syncBindSquare = syncSquare
            local refreshBinding: any = binding.refresh
            binding.refresh = function(): ()
                if refreshBinding then
                    refreshBinding()
                end
                syncSquare()
            end
            syncSquare()

            local function syncKeyboard(): ()
                square.Visible = UserInputService == nil
                    or UserInputService.KeyboardEnabled ~= false
            end
            syncKeyboard()
            pcall(function(): ()
                trackUiConnection(
                    UserInputService:GetPropertyChangedSignal("KeyboardEnabled")
                        :Connect(syncKeyboard)
                )
            end)

            local function tipText(): string
                local bound: boolean = binding.key ~= nil
                    and binding.key ~= Enum.KeyCode.Unknown
                if not bound then
                    return "Bind: click, then press a key"
                end
                local conflict: any = conflictWith()
                if conflict then
                    return binding.key.Name .. " — also bound to "
                        .. tostring(conflict.id)
                end
                return "Bound: " .. binding.key.Name
            end
            trackUiConnection(square.MouseEnter:Connect(function(): ()
                local tooltip: any = state.featureTooltip
                if not tooltip then
                    return
                end
                state.tooltipToken = (state.tooltipToken or 0) + 1
                local token: number = state.tooltipToken
                task.delay(0.4, function(): ()
                    if state.tooltipToken ~= token or not square.Parent then
                        return
                    end
                    local rawText: string = tipText()
                    local bitmap: any = state.bitmapText
                    local measured: number = bitmap
                            and type(bitmap.measure) == "function"
                            and tonumber(bitmap.measure({{text = rawText}}, 16))
                        or #rawText * 8
                    local width: number = math.clamp(measured + 24, 140, 360)
                    local wrapped: string = rawText
                    local lines: number = 1
                    if bitmap and type(bitmap.wrap) == "function" then
                        wrapped, lines = bitmap.wrap(rawText, width - 24, 16)
                    end
                    tooltip.Text = wrapped
                    tooltip.TextTransparency = 1
                    tooltip.Size = UDim2.fromOffset(width, math.max(30, lines * 18 + 12))
                    tooltip.Position = UDim2.fromOffset(
                        square.AbsolutePosition.X,
                        square.AbsolutePosition.Y + square.AbsoluteSize.Y + 8
                    )
                    if state.bitmapText and type(state.bitmapText.draw) == "function" then
                        state.bitmapText.draw(tooltip, {
                            {text = tooltip.Text},
                        }, {
                            Name = "Glyphs",
                            TextSize = 16,
                            maxWidth = width - 24,
                            ellipsis = true,
                            ZIndex = 251,
                        })
                    end
                    tooltip.Visible = true
                end)
            end))
            trackUiConnection(square.MouseLeave:Connect(function(): ()
                state.tooltipToken = (state.tooltipToken or 0) + 1
                if state.featureTooltip then
                    state.featureTooltip.Visible = false
                end
            end))

            local outsideConnection: RBXScriptConnection? = nil
            local function cleanupCapture(): ()
                capturing = false
                if outsideConnection then
                    pcall(function(): ()
                        (outsideConnection :: RBXScriptConnection):Disconnect()
                    end)
                    outsideConnection = nil
                end
                syncSquare()

                task.delay(0.2, function(): ()
                    if square.Parent and not capturing then
                        syncSquare()
                    end
                end)
            end
            trackUiConnection(square.MouseButton1Click:Connect(function(): ()
                if capturing then

                    if state.keyCaptureCancel then
                        state.keyCaptureCancel()
                    else
                        cleanupCapture()
                    end
                    return
                end
                capturing = true
                beginKeyCapture(square, function(keyCode: Enum.KeyCode): ()

                    local backspaceKey: any = (Enum.KeyCode :: any).Backspace
                    local deleteKey: any = (Enum.KeyCode :: any).Delete
                    if keyCode == backspaceKey or keyCode == deleteKey then
                        if binding.key ~= Enum.KeyCode.Unknown
                            and type(binding.assign) == "function" then
                            binding.assign(binding.key)
                        end
                    elseif type(binding.assign) == "function" then
                        binding.assign(keyCode)
                    end
                    cleanupCapture()
                end)

                local baseCancel: any = state.keyCaptureCancel
                state.keyCaptureCancel = function(): ()
                    if baseCancel then
                        baseCancel()
                    end
                    cleanupCapture()
                end

                pcall(function(): ()
                    outsideConnection = UserInputService.InputBegan:Connect(function(
                        input: InputObject
                    ): ()
                        if input.UserInputType ~= Enum.UserInputType.MouseButton1
                            and input.UserInputType ~= Enum.UserInputType.Touch then
                            return
                        end
                        local px: number = input.Position.X
                        local py: number = input.Position.Y
                        local ax: number = square.AbsolutePosition.X
                        local ay: number = square.AbsolutePosition.Y
                        if px < ax or px > ax + square.AbsoluteSize.X
                            or py < ay or py > ay + square.AbsoluteSize.Y then
                            if state.keyCaptureCancel then
                                state.keyCaptureCancel()
                            end
                        end
                    end)
                end)
            end))
        end

        feature.applyLayout = function(): ()
            local metrics: LayoutMetrics = state.layout
            feature.collapsedHeight = metrics.cardHeight
            if title then
                state.setTextMetric(title, metrics.titleFontSize)
            elseif feature.drawTitle then

                feature.drawTitle(nil, nil)
            end
            if arrow then
                (arrow :: TextButton).Size =
                    UDim2.fromOffset(22, metrics.cardHeight)
            end
            if shortcutButton then
                (shortcutButton :: TextButton).Size = UDim2.fromOffset(22, 22);
                (shortcutButton :: TextButton).Position =
                    UDim2.new(0, 4, 0, metrics.cardHeight / 2)
            end
            activationTarget.Size = UDim2.new(1, 0, 0, metrics.cardHeight)
            options.Position = UDim2.fromOffset(4, metrics.cardHeight)
            syncArrow()
            updateExpandedSize(false)
        end

        feature.applyLayout()

        function feature:SetStatus(status: string?): ()
            feature.status = status
        end

        registry[name] = feature
        table.insert(allFeatures, feature)

        if state.floatingUi then
            state.floatingUi.registerFeature(feature)
        end

        if state.clickGui then
            state.clickGui.place(feature)
        end
        applyFeaturePresentation(feature, state.guiStyle == "Default")

        if type(addFeatureTooltip) == "function" and description ~= "" then
            addFeatureTooltip(feature, description)
        end

        local search: any = state.moduleSearch
        if search and type(search.Register) == "function" then
            search.Register(feature)
            table.insert(registeredSearchFeatures, feature)
        end

        if feature.isAlwaysOn then
            task.defer(function(): ()
                local ok: boolean, failure: any = pcall(feature.onToggle, true)
                if not ok then
                    warn("[Random Testing Menu] " .. name .. ": " .. tostring(failure))
                end
            end)
        end

        if not feature.isAction
            and not feature.isCategory
            and not feature.isHoldAction
            and configuration.restore ~= false
            and configData.states[feature.configKey] == true then
            task.defer(function(): ()
                local success: boolean, errorMessage: any = pcall(
                    feature.onToggle,
                    true
                )
                if success then
                    feature.enabled = true
                    feature.enabledAt = os.clock()
                    refreshFeatureToggle(feature)
                else
                    configData.states[feature.configKey] = false
                    queueConfigSave()
                    warn(
                        "[Random Testing Menu] Could not restore "
                            .. name
                            .. ": "
                            .. tostring(errorMessage)
                    )
                end
            end)
        end
        return feature
    end

    moduleCleanup = function(): ()
        local search: any = state.moduleSearch
        if search and type(search.Unregister) == "function" then
            for _, feature: any in ipairs(registeredSearchFeatures) do
                search.Unregister(feature)
            end
        end
        table.clear(registeredSearchFeatures)
    end
    Module.Initialized = true
    return {createUniversalFeature = createUniversalFeature}
end

function Module.destroy(): ()
    moduleCleanup()
    moduleCleanup = function(): () end
    Module.Initialized = false
end

return Module

]],
        ["src/guis/Wurst/Code/ClickGui.lua"] = [[
export type CategoryWindow = {
    name: string,
    window: any,
    layout: UIListLayout,
    count: number,
}

local Module = {
    Name = "ClickGui",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

local activeCleanup: (() -> ())? = nil

local WINDOW_WIDTH: number = 200
local WINDOW_MAX_HEIGHT: number = 300

local SCALE_MINIMUM: number = 0.7
local SCALE_MAXIMUM: number = 1.6

local CALIBRATION_WIDTH: number = 1600
local CALIBRATION_HEIGHT: number = 900
local GRID_MARGIN: number = 10
local WINDOW_GAP: number = 2

local GRID_GAP: number = 10
local TITLE_HEIGHT: number = 26

local CATEGORY_ORDER: {string} = {
    "Combat",
    "Render",
    "Blocks",
    "Movement",
    "Fun",
    "Items",
    "Other",
}

local CATEGORY_ALIASES: {[string]: string} = {
    ["Visuals"] = "Render",
    ["Protection"] = "Movement",
    ["Utility"] = "Other",
    ["Spoof"] = "Fun",
    ["General"] = "Other",
    ["Player"] = "Movement",
}

local function fallbackNormalize(raw: any): string
    local name: string = tostring(raw or "Other")
    if table.find(CATEGORY_ORDER, name) ~= nil then
        return name
    end
    return CATEGORY_ALIASES[name] or "Other"
end

function Module.init(context: any): any
    local host: any = context
    local state: any = host.state
    local create: any = host.create
    local allFeatures: {any} = host.allFeatures
    local normalizeFeatureCategory: any = host.normalizeFeatureCategory

    local function viewportScale(): number
        local shape: any = host.ThemeEngine and host.ThemeEngine.shape
        local wanted: number = shape and tonumber(shape.scale) or 1
        local camera: Camera? = workspace.CurrentCamera
        local viewport: Vector2 = camera
            and (camera :: Camera).ViewportSize
            or Vector2.new(CALIBRATION_WIDTH, CALIBRATION_HEIGHT)
        local fit: number = math.min(
            viewport.X / CALIBRATION_WIDTH,
            viewport.Y / CALIBRATION_HEIGHT
        )
        return math.clamp(wanted * fit, SCALE_MINIMUM, SCALE_MAXIMUM)
    end

    local function logicalViewport(): Vector2
        local camera: Camera? = workspace.CurrentCamera
        local viewport: Vector2 = camera
            and (camera :: Camera).ViewportSize
            or Vector2.new(CALIBRATION_WIDTH, CALIBRATION_HEIGHT)
        local factor: number = viewportScale()
        return Vector2.new(viewport.X / factor, viewport.Y / factor)
    end

    local windows: any = state.windows
    if not windows then

        error("ClickGui requires the window manager")
    end

    local ClickGui: any = {
        categories = {} :: {[string]: CategoryWindow},
        order = {} :: {string},

        connections = {} :: {RBXScriptConnection},
    }

    local productVersion: string = tostring(
        (host.PRODUCT and host.PRODUCT.version) or "0.1 Beta"
    )
    local LOGO_CHIP_WIDTH: number = 142 + 10 + (8 + #productVersion * 15) + 4
    local LOGO_CHIP_HEIGHT: number = 44
    local TOP_ROW_X: number = 14 + LOGO_CHIP_WIDTH + GRID_GAP
    local TOP_ROW_Y: number = 10
    local nextX: number = TOP_ROW_X
    local nextY: number = TOP_ROW_Y
    local rowHeight: number = LOGO_CHIP_HEIGHT

    local function nextSlot(height: number): Vector2
        local viewport: Vector2 = logicalViewport()
        if nextX + WINDOW_WIDTH > viewport.X - GRID_MARGIN then
            nextX = GRID_MARGIN
            nextY += rowHeight + GRID_GAP
            rowHeight = 0
        end
        local slot: Vector2 = Vector2.new(nextX, nextY)
        nextX += WINDOW_WIDTH + GRID_GAP
        rowHeight = math.max(rowHeight, height)
        return slot
    end

    local function categoryWindow(name: string): CategoryWindow
        local existing: CategoryWindow? = ClickGui.categories[name]
        if existing then
            return existing :: CategoryWindow
        end

        local height: number = TITLE_HEIGHT + 8
        local window: any = windows.Create({
            id = "ClickGui_" .. name,
            title = name,
            size = Vector2.new(WINDOW_WIDTH, height),
            position = nextSlot(WINDOW_MAX_HEIGHT * 0.5),
            maxHeight = WINDOW_MAX_HEIGHT,

            closable = false,
        })

        local layout: UIListLayout = create("UIListLayout", {
            Parent = window.body,
            Padding = UDim.new(0, WINDOW_GAP),
            SortOrder = Enum.SortOrder.LayoutOrder,
        }) :: UIListLayout
        create("UIPadding", {
            Parent = window.body,
            PaddingTop = UDim.new(0, WINDOW_GAP),
            PaddingBottom = UDim.new(0, WINDOW_GAP),
            PaddingLeft = UDim.new(0, WINDOW_GAP),
            PaddingRight = UDim.new(0, WINDOW_GAP),
        })

        local record: CategoryWindow = {
            name = name,
            window = window,
            layout = layout,
            count = 0,
        }
        ClickGui.categories[name] = record
        table.insert(ClickGui.order, name)
        table.sort(ClickGui.order, function(left: string, right: string): boolean
            local leftRank: number = table.find(CATEGORY_ORDER, left) or math.huge
            local rightRank: number = table.find(CATEGORY_ORDER, right) or math.huge
            if leftRank == rightRank then
                return left < right
            end
            return leftRank < rightRank
        end)

        local function resize(): ()

            local limit: number = tonumber(state.uiMaxHeight) or WINDOW_MAX_HEIGHT
            if limit <= 0 then
                limit = math.huge
            end

            limit = math.min(limit, logicalViewport().Y - 12)

            local declaredHeight: number = 0
            local visibleRows: number = 0
            for _, child: Instance in ipairs(window.body:GetChildren()) do
                if child:IsA("GuiObject") and (child :: GuiObject).Visible then
                    visibleRows += 1
                    declaredHeight += (child :: GuiObject).Size.Y.Offset
                end
            end
            declaredHeight += math.max(visibleRows - 1, 0) * WINDOW_GAP
            local contentHeight: number = math.max(
                layout.AbsoluteContentSize.Y,
                declaredHeight
            )
            local wanted: number = math.min(
                TITLE_HEIGHT + contentHeight + 4,
                limit
            )
            window.fullHeight = wanted
            if not window.collapsed then
                window.root.Size = UDim2.fromOffset(WINDOW_WIDTH, wanted)
            end

            if windows.ClampWindow then
                windows.ClampWindow(window)
            end
        end
        table.insert(
            ClickGui.connections,
            layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(resize)
        )
        resize()
        record.resize = resize :: any
        return record
    end

    local function sortCategoryRows(record: CategoryWindow): ()
        local rows: {GuiObject} = {}
        for _, child: Instance in ipairs(record.window.body:GetChildren()) do
            if not child:IsA("GuiObject") then
                continue
            end
            local key: any = child:GetAttribute("FeatureSortName")
            if type(key) == "string" then
                table.insert(rows, child :: GuiObject)
            end
        end
        table.sort(rows, function(left: GuiObject, right: GuiObject): boolean
            local leftKey: string = tostring(left:GetAttribute("FeatureSortName") or "")
            local rightKey: string = tostring(right:GetAttribute("FeatureSortName") or "")
            if leftKey == rightKey then
                return left.Name < right.Name
            end
            return leftKey < rightKey
        end)
        for index: number, row: GuiObject in ipairs(rows) do
            row.LayoutOrder = index
        end
    end

    function ClickGui.place(feature: any): ()
        local row: Frame? = feature and feature.row
        if not row then
            return
        end

        local raw: any = (row :: Frame):GetAttribute("FeatureCategory")
        local name: string = type(normalizeFeatureCategory) == "function"
            and normalizeFeatureCategory(raw)
            or fallbackNormalize(raw)
        local record: CategoryWindow = categoryWindow(name)
        record.count += 1;
        (row :: Frame).Parent = record.window.body;
        (row :: Frame).Size = UDim2.new(1, 0, 0, feature.collapsedHeight or 22)
        sortCategoryRows(record)
        if record.resize then
            (record.resize :: () -> ())()
        end
        local userMoved: boolean = false
        for _, category: string in ipairs(ClickGui.order) do
            local candidate: CategoryWindow? = ClickGui.categories[category]
            if candidate and candidate.window.userMoved == true then
                userMoved = true
                break
            end
        end
        if not userMoved and type(ClickGui.Retile) == "function" then
            ClickGui.Retile()
        end
    end

    function ClickGui.Retile(): ()

        nextX = TOP_ROW_X
        nextY = TOP_ROW_Y
        rowHeight = LOGO_CHIP_HEIGHT
        for _, name: string in ipairs(ClickGui.order) do
            local record: CategoryWindow = ClickGui.categories[name]
            if record then
                local slot: Vector2 = nextSlot(
                    record.window.fullHeight or WINDOW_MAX_HEIGHT * 0.5
                )
                record.window.root.Position = UDim2.fromOffset(slot.X, slot.Y)
                if type(windows.ClampWindow) == "function" then
                    windows.ClampWindow(record.window)
                end
            end
        end
    end

    function ClickGui.RefreshHeights(): ()
        for _, name: string in ipairs(ClickGui.order) do
            local record: CategoryWindow = ClickGui.categories[name]
            if record and record.resize then
                (record.resize :: () -> ())()
            end
        end
    end

    function ClickGui.SetVisible(visible: boolean): ()
        for _, name: string in ipairs(ClickGui.order) do
            local record: CategoryWindow = ClickGui.categories[name]

            if not visible and record.window.pinned then
                continue
            end
            record.window:SetVisible(visible and record.window.userVisible ~= false)
        end
    end

    local function resolvedCategory(feature: any): string
        local row: any = feature and feature.row
        local raw: any = row and row:GetAttribute("FeatureCategory")
        if type(normalizeFeatureCategory) == "function" then
            return normalizeFeatureCategory(raw)
        end
        return fallbackNormalize(raw)
    end
    for _, name: string in ipairs(CATEGORY_ORDER) do
        for _, feature: any in ipairs(allFeatures) do
            if resolvedCategory(feature) == name then
                categoryWindow(name)
                break
            end
        end
    end

    for _, feature: any in ipairs(allFeatures) do
        ClickGui.place(feature)
    end

    local scale: UIScale = create("UIScale", {
        Parent = host.PopupLayer,
        Name = "ClickGuiScale",
        Scale = viewportScale(),
    }) :: UIScale

    state.onLayout(function(): ()
        scale.Scale = viewportScale()
        ClickGui.RefreshHeights()
    end)
    ClickGui.scale = scale

    state.clickGui = ClickGui
    state.addMenuVisibilityListener(function(visible: boolean): ()
        ClickGui.SetVisible(visible)
    end)
    ClickGui.SetVisible(state.visible == true)

    activeCleanup = function(): ()
        for _, name: string in ipairs(ClickGui.order) do
            local record: CategoryWindow? = ClickGui.categories[name]
            if record then
                pcall(function(): ()
                    (record :: CategoryWindow).window:Destroy()
                end)
            end
        end
        for _, connection: RBXScriptConnection in ipairs(ClickGui.connections) do
            pcall(function(): ()
                connection:Disconnect()
            end)
        end
        ClickGui.connections = {}
        ClickGui.categories = {}
        ClickGui.order = {}
        state.clickGui = nil
    end
    Module.Initialized = true
    return ClickGui
end

function Module.destroy(): ()
    if activeCleanup then
        pcall(activeCleanup)
    end
    activeCleanup = nil
    Module.Initialized = false
end

return Module

]],
        ["src/guis/Wurst/Code/FloatingWindows.lua"] = [[
export type FloatingWindowRecord = {
    id: string,
    root: Frame,
    body: Frame,
    closeButton: TextButton,
}

local activeCleanup: (() -> ())? = nil

local Module = {
    Name = "FloatingWindows",
    PlaceId = 0,
    Events = {} :: {[string]: any},
    Initialized = false,
}

function Module.init(context: any): any
    local host: any = context
    local state: any = host.state
    local configData: any = host.configData
    local queueConfigSave: any = host.queueConfigSave
    local create: any = host.create
    local makeButton: any = host.makeButton
    local makeTextBox: any = host.makeTextBox
    local makeTextLabel: any = host.makeTextLabel
    local Theme: any = host.Theme
    local ThemeEngine: any = host.ThemeEngine
    local CONTROL_FONT: any = host.CONTROL_FONT
    local THIN_FONT: any = host.THIN_FONT
    local VALVE_FONT: any = host.VALVE_FONT
    local PopupLayer: any = host.PopupLayer
    local UI_RADIUS: any = host.UI_RADIUS
    local cornerRadius: any = host.cornerRadius
    local trackUiConnection: any = host.trackUiConnection
    local createToggleSwitch: any = host.createToggleSwitch
    local setToggleSwitch: any = host.setToggleSwitch
    local TweenService: any = host.TweenService
    local UserInputService: any = host.UserInputService
    local Players: any = host.Players
    local LocalPlayer: any = host.LocalPlayer
    local Stats: any = host.Stats
    local TaskManager: any = host.TaskManager
    local allFeatures: any = host.allFeatures

    local function bind(instance: Instance, property: string, token: string): ()
        if ThemeEngine and type(ThemeEngine.Bind) == "function" then
            ThemeEngine.Bind(instance, property, token)
        else
            (instance :: any)[property] = Theme[token]
        end
    end

    local ownedTasks: {any} = {}

    local FloatingUi: any = {
        favorites = {},
        favoriteRows = {},
        overlays = {},
        featureRows = {},
        windows = {},
    }
    state.floatingUi = FloatingUi

    if type(configData.ui.favorites) ~= "table" then
        configData.ui.favorites = {}
    end
    if type(configData.ui.overlays) ~= "table" then
        configData.ui.overlays = {}
    end
    if type(configData.ui.floatingPositions) ~= "table" then
        configData.ui.floatingPositions = {}
    end
    if type(configData.ui.overlaySettings) ~= "table" then
        configData.ui.overlaySettings = {}
    end
    local overlaySettings: any = configData.ui.overlaySettings
    overlaySettings.TextGUI = type(overlaySettings.TextGUI) == "table"
        and overlaySettings.TextGUI
        or {}
    overlaySettings.SessionInfo = type(overlaySettings.SessionInfo) == "table"
        and overlaySettings.SessionInfo
        or {}
    overlaySettings.TargetInfo = type(overlaySettings.TargetInfo) == "table"
        and overlaySettings.TargetInfo
        or {}
    overlaySettings.Radar = type(overlaySettings.Radar) == "table"
        and overlaySettings.Radar
        or {}
    local textGuiSettings: any = overlaySettings.TextGUI
    textGuiSettings.sort = textGuiSettings.sort or "Alphabetical"
    textGuiSettings.font = textGuiSettings.font or "Builder Sans"
    textGuiSettings.colorMode = textGuiSettings.colorMode or "Match GUI"
    textGuiSettings.scale = math.clamp(tonumber(textGuiSettings.scale) or 1, 0.75, 2)
    textGuiSettings.shadow = textGuiSettings.shadow ~= false
    textGuiSettings.gradient = textGuiSettings.gradient == true
    textGuiSettings.v4Gradient = textGuiSettings.v4Gradient == true
    textGuiSettings.animations = textGuiSettings.animations ~= false
    textGuiSettings.watermark = textGuiSettings.watermark == true
    textGuiSettings.background = textGuiSettings.background == true
    textGuiSettings.hideModules = textGuiSettings.hideModules == true
    textGuiSettings.hideRender = textGuiSettings.hideRender == true
    textGuiSettings.customText = tostring(textGuiSettings.customText or "")
    local sessionSettings: any = overlaySettings.SessionInfo
    sessionSettings.showPerformance = sessionSettings.showPerformance ~= false
    sessionSettings.showServer = sessionSettings.showServer ~= false
    sessionSettings.showRole = sessionSettings.showRole ~= false
    sessionSettings.showDeaths = sessionSettings.showDeaths ~= false
    sessionSettings.showWins = sessionSettings.showWins ~= false
    local targetSettings: any = overlaySettings.TargetInfo
    targetSettings.mode = targetSettings.mode or "Smart Priority"
    targetSettings.showAvatar = targetSettings.showAvatar ~= false
    targetSettings.showHealth = targetSettings.showHealth ~= false
    targetSettings.showDistance = targetSettings.showDistance ~= false
    local radarSettings: any = overlaySettings.Radar
    radarSettings.range = math.clamp(tonumber(radarSettings.range) or 250, 25, 2000)
    radarSettings.size = math.clamp(tonumber(radarSettings.size) or 190, 140, 280)
    radarSettings.rotation = radarSettings.rotation or "Camera"
    radarSettings.colorMode = radarSettings.colorMode or "Smart"
    radarSettings.outOfRange = radarSettings.outOfRange or "Clamp"
    radarSettings.showNames = radarSettings.showNames == true
    radarSettings.showDistance = radarSettings.showDistance == true
    radarSettings.showTeam = radarSettings.showTeam ~= false
    radarSettings.aliveOnly = radarSettings.aliveOnly ~= false
    radarSettings.grid = radarSettings.grid ~= false
    radarSettings.rings = radarSettings.rings ~= false

    local function getFloatingViewport(): Vector2
        local camera: Camera? = workspace.CurrentCamera
        return camera and camera.ViewportSize or Vector2.new(1280, 720)
    end

    local function clampFloatingPosition(
        position: Vector2,
        size: Vector2
    ): Vector2
        local viewport: Vector2 = getFloatingViewport()
        return Vector2.new(
            math.clamp(position.X, 6, math.max(6, viewport.X - size.X - 6)),
            math.clamp(position.Y, 6, math.max(6, viewport.Y - size.Y - 6))
        )
    end

    local function bringFloatingToFront(record: FloatingWindowRecord): ()
        state.windows.Raise(record.id)
    end

    local function createFloatingWindow(
        id: string,
        titleText: string,
        size: Vector2,
        defaultPosition: Vector2,
        onClose: (() -> ())?,
        chromeless: boolean?
    ): FloatingWindowRecord
        local bare: boolean = chromeless == true
        local headerHeight: number = bare and 0 or 30
        local saved: any = configData.ui.floatingPositions[id]
        local position: Vector2 = type(saved) == "table"
            and Vector2.new(
                tonumber(saved[1]) or defaultPosition.X,
                tonumber(saved[2]) or defaultPosition.Y
            )
            or defaultPosition
        position = clampFloatingPosition(position, size)

        local root: Frame = create("Frame", {
            Parent = PopupLayer,
            Name = "Floating_" .. id,
            Active = true,
            BackgroundColor3 = Theme.background,
            BackgroundTransparency = bare and 1 or 0.08,
            BorderSizePixel = 0,
            ClipsDescendants = not bare,
            Position = UDim2.fromOffset(position.X, position.Y),
            Size = UDim2.fromOffset(size.X, size.Y),
            Visible = false,
            ZIndex = 150,
        }) :: Frame
        bind(root, "BackgroundColor3", "background")
        if not bare then
            create("UICorner", {
                Parent = root,
                CornerRadius = cornerRadius(UI_RADIUS.panel),
            })
            local edge: UIStroke = create("UIStroke", {
                Parent = root,
                Name = "WindowOutline",
                Color = Theme.outline,
                Transparency = 0.08,
                Thickness = 1,
            }) :: UIStroke
            bind(edge, "Color", "outline")

            local shade: Frame = create("Frame", {
                Parent = root,
                Name = "Readability",
                BackgroundColor3 = Theme.background,
                BackgroundTransparency = 0.28,
                BorderSizePixel = 0,
                Size = UDim2.fromScale(1, 1),
            }) :: Frame
            bind(shade, "BackgroundColor3", "background")
            shade:SetAttribute("FloatingDepth", 2)
        end

        local header: Frame = create("Frame", {
            Parent = root,
            Name = "Header",
            Active = not bare,
            BackgroundColor3 = Theme.surface,
            BackgroundTransparency = 0.24,
            BorderSizePixel = 0,
            Size = UDim2.new(1, 0, 0, headerHeight),
            Visible = not bare,
        }) :: Frame
        bind(header, "BackgroundColor3", "surface")
        header:SetAttribute("FloatingDepth", 3)

        local closeButton: TextButton
        if bare then

            closeButton = create("TextButton", {
                TextTruncate = Enum.TextTruncate.AtEnd,
                ClipsDescendants = true,
                Parent = header,
                Name = "Close",
                BackgroundTransparency = 1,
                Text = "",
                Visible = false,
            }) :: TextButton
        else
            local accent: Frame = create("Frame", {
                Parent = header,
                BackgroundColor3 = Theme.outline,
                BackgroundTransparency = 0.62,
                BorderSizePixel = 0,
                Position = UDim2.fromOffset(0, headerHeight - 1),
                Size = UDim2.new(1, 0, 0, 1),
            }) :: Frame
            bind(accent, "BackgroundColor3", "outline")
            accent:SetAttribute("FloatingDepth", 1)
            local title: TextLabel = makeTextLabel(header, titleText, 10)
            title.FontFace = CONTROL_FONT
            title.Position = UDim2.fromOffset(10, 0)
            title.Size = UDim2.new(1, -40, 1, 0)
            title.TextColor3 = Theme.text
            bind(title, "TextColor3", "text")
            title:SetAttribute("FloatingDepth", 2)

            closeButton = makeButton(header, "x", 9)
            closeButton.Name = "Close"
            closeButton.AnchorPoint = Vector2.new(1, 0.5)
            closeButton.BackgroundTransparency = 1
            closeButton.Position = UDim2.new(1, -6, 0.5, 0)
            closeButton.Size = UDim2.fromOffset(22, 22)
            closeButton.TextColor3 = Theme.textMuted
            closeButton:SetAttribute("ThemeRole", "Icon")
            closeButton:SetAttribute("FloatingDepth", 3)
            local closeStroke: UIStroke? =
                closeButton:FindFirstChild("StyleStroke") :: UIStroke?
            if closeStroke then
                closeStroke.Enabled = false
            end
        end

        local body: Frame = create("Frame", {
            Parent = root,
            Name = "Body",
            Active = false,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Position = UDim2.fromOffset(0, headerHeight),
            Size = UDim2.new(1, 0, 1, -headerHeight),
        }) :: Frame
        body:SetAttribute("FloatingDepth", 4)

        if bare then
            root.Active = state.visible == true

            create("UICorner", {
                Parent = root,
                CornerRadius = cornerRadius(UI_RADIUS.control),
            })
            local hint: UIStroke = create("UIStroke", {
                Parent = root,
                Name = "MoveHint",
                Color = Theme.outline,
                Thickness = 1,
                Transparency = state.visible and 0.72 or 1,
            }) :: UIStroke
            bind(hint, "Color", "outline")
            state.addMenuVisibilityListener(function(visible: boolean): ()
                if not root.Parent then
                    return
                end
                root.Active = visible
                hint.Transparency = visible and 0.72 or 1
            end)
        end

        local record: FloatingWindowRecord = {
            id = id,
            root = root,
            body = body,
            closeButton = closeButton,
        }

        state.windows.Adopt(root, {
            id = id,
            body = body,
            header = header,
            closeButton = closeButton,
            headerHeight = headerHeight,
            dragHandle = bare and root or header,
            requiresMenuOpen = bare,
            layered = true,
            onClose = onClose,
        })
        return record
    end

    function FloatingUi.reclamp(): ()
        state.windows.Reclamp()
    end

    state.onLayout(function(): ()
        FloatingUi.reclamp()
    end)

