    local function setHackListVisible(value: boolean): ()
        hudVisible = value ~= false
        hudFrame.Visible = hudVisible
        if hudVisible then
            forceHudRefresh()

            for _, row: any in pairs(hudRows) do
                slideHudRow(row)
            end
        end
    end
